-- Leesfuncties niet voor anon; saldo alleen voor het eigen bedrijf (of server zonder gebruiker)
create or replace function public.sa_credit_balance(p_company_id uuid)
returns integer language sql stable security definer set search_path = public as $$
  select case when auth.uid() is null or p_company_id = sa_my_company_id() then
    (select coalesce(sum(remaining), 0)::integer from sa_credit_lots
      where company_id = p_company_id and remaining > 0 and expires_at > now())
  else null end
$$;
revoke all on function public.sa_credit_balance(uuid) from public, anon;
revoke all on function public.sa_my_company_id() from public, anon;
revoke all on function public.gbqs_haven_region(uuid) from public, anon;
grant execute on function public.sa_credit_balance(uuid), public.sa_my_company_id(), public.gbqs_haven_region(uuid) to authenticated, service_role;

