-- Aanmelding vastleggen (aangeroepen door edge function surveyor-signup, na aanmaken van de auth-gebruiker)
create or replace function public.sa_register_company(
  p_user_id uuid, p_email text, p_full_name text, p_company text, p_country text,
  p_phone text default null, p_terms_version text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_email  text := lower(trim(coalesce(p_email,'')));
  v_domain text := split_part(lower(trim(coalesce(p_email,''))), '@', 2);
  v_free   boolean;
  v_co     uuid;
  v_int    uuid;
  v_sv     uuid;
begin
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' or coalesce(trim(p_company),'') = '' or coalesce(trim(p_full_name),'') = '' then
    return jsonb_build_object('ok', false, 'code', 'invalid', 'message', 'Please fill in your name, company and a valid email address.');
  end if;
  if exists (select 1 from surveyor_company_users where user_id = p_user_id) then
    return jsonb_build_object('ok', false, 'code', 'already_member', 'message', 'This account already belongs to a survey company.');
  end if;
  if exists (select 1 from client_users where user_id = p_user_id) then
    return jsonb_build_object('ok', false, 'code', 'client_user', 'message', 'This email address is already used for a client account. Please use another address.');
  end if;
  v_free := exists (select 1 from sa_free_mail_domains where domain = v_domain);
  if not v_free and exists (select 1 from surveyor_companies where domain = v_domain and status <> 'blocked') then
    return jsonb_build_object('ok', false, 'code', 'company_exists',
      'message', 'Your company already has a GlobalBQS account. Please ask your office administrator to invite you.');
  end if;

  select id into v_int from surveyor_interest where email = v_email
   or (not v_free and domain = v_domain) order by first_seen_at limit 1;

  insert into surveyor_companies(name, domain, country, phone, office_email, invoice_email, status, early_bird, interest_id,
                                 terms_version, terms_accepted_at)
  values (left(trim(p_company), 200), case when v_free then null else v_domain end, nullif(trim(p_country),''), nullif(trim(p_phone),''),
          v_email, v_email, 'pending', sa_is_early_bird(v_email, case when v_free then null else v_domain end), v_int,
          p_terms_version, case when p_terms_version is not null then now() end)
  returning id into v_co;

  -- bestaande surveyor (rating/historie) koppelen op e-mailadres
  select id into v_sv from surveyors where lower(email) = v_email and company_id is null order by created_at limit 1;
  if v_sv is not null then
    update surveyors set company_id = v_co where id = v_sv;
  end if;

  insert into surveyor_company_users(user_id, company_id, email, full_name, is_office, is_surveyor, is_admin, surveyor_id, status)
  values (p_user_id, v_co, v_email, left(trim(p_full_name), 120), true, true, true, v_sv, 'invited');

  return jsonb_build_object('ok', true, 'company_id', v_co, 'free_mail', v_free, 'linked_surveyor', v_sv is not null);
end $$;

-- Eerste login afronden: lidmaatschap actief + welkomsttegoed (bij gratis e-maildomein pas na controle door ops)
create or replace function public.sa_complete_signup()
returns jsonb language plpgsql security definer set search_path = public as $$
declare u surveyor_company_users; c surveyor_companies; r jsonb := null; v_free boolean;
begin
  select * into u from surveyor_company_users where user_id = auth.uid();
  if u.user_id is null then return jsonb_build_object('ok', false, 'code', 'not_surveyor'); end if;
  if u.status = 'disabled' then return jsonb_build_object('ok', false, 'code', 'disabled'); end if;
  select * into c from surveyor_companies where id = u.company_id;
  if c.status in ('suspended','blocked') then return jsonb_build_object('ok', false, 'code', c.status); end if;
  if u.status = 'invited' then
    update surveyor_company_users set status = 'active', updated_at = now() where user_id = u.user_id;
  end if;
  v_free := c.domain is null;
  if u.is_admin and (not v_free or c.status = 'approved') then
    r := sa_grant_welcome_credits(c.id, 'signup');
  end if;
  return jsonb_build_object('ok', true, 'company_id', c.id, 'welcome', r, 'awaiting_check', v_free and c.status <> 'approved');
end $$;

-- Wie ben ik (surveyor)? Leeg voor alle anderen.
create or replace function public.sa_portal_me()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'kind', 'surveyor', 'user_id', u.user_id, 'email', u.email, 'full_name', u.full_name,
    'member_status', u.status, 'is_office', u.is_office, 'is_surveyor', u.is_surveyor, 'is_admin', u.is_admin,
    'company_id', c.id, 'company', c.name, 'company_status', c.status, 'early_bird', c.early_bird,
    'logo_path', c.logo_path, 'credit_balance', sa_credit_balance(c.id),
    'awaiting_check', (c.domain is null and c.status <> 'approved'))
  from surveyor_company_users u join surveyor_companies c on c.id = u.company_id
  where u.user_id = auth.uid()
$$;

-- Ops: bedrijf goedkeuren (Retool A8); geeft welkomsttegoed als dat nog niet gebeurde
create or replace function public.sa_ops_set_company_status(p_company_id uuid, p_status text, p_by text default null, p_note text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare c surveyor_companies; r jsonb := null;
begin
  if p_status not in ('pending','approved','suspended','blocked') then
    return jsonb_build_object('ok', false, 'message', 'Onbekende status.');
  end if;
  update surveyor_companies set status = p_status,
         verified_at = case when p_status = 'approved' then coalesce(verified_at, now()) else verified_at end,
         verified_by = case when p_status = 'approved' then coalesce(p_by, verified_by) else verified_by end,
         notes = case when p_note is not null then coalesce(notes || E'\n', '') || to_char(now(),'YYYY-MM-DD') || ' ' || p_note else notes end,
         updated_at = now()
   where id = p_company_id returning * into c;
  if c.id is null then return jsonb_build_object('ok', false, 'message', 'Bedrijf niet gevonden.'); end if;
  if p_status = 'approved' and exists (select 1 from surveyor_company_users where company_id = c.id and status = 'active') then
    r := sa_grant_welcome_credits(c.id, coalesce(p_by, 'ops'));
  end if;
  return jsonb_build_object('ok', true, 'status', c.status, 'welcome', r);
end $$;

revoke all on function public.sa_register_company(uuid,text,text,text,text,text,text) from public, anon, authenticated;
revoke all on function public.sa_ops_set_company_status(uuid,text,text,text) from public, anon, authenticated;
revoke all on function public.sa_complete_signup() from public, anon;
revoke all on function public.sa_portal_me() from public, anon;
grant execute on function public.sa_register_company(uuid,text,text,text,text,text,text), public.sa_ops_set_company_status(uuid,text,text,text) to service_role;
grant execute on function public.sa_complete_signup(), public.sa_portal_me() to authenticated, service_role;

-- A12: diensten per surveybedrijf, dashboard en bedrijfsgegevens voor het surveyorportaal
alter table public.surveyor_companies
  add column if not exists offered_types text[] not null default array['bunker_quantity_survey','bunker_delivery_survey','on_hire_bunker','on_hire_condition','on_hire_bc','off_hire_bunker','off_hire_condition','off_hire_bc']::text[],
  add column if not exists can_issue_certificate boolean not null default true,
  add column if not exists ports_text text;

alter table public.surveyor_companies drop constraint if exists surveyor_companies_offered_types_check;
alter table public.surveyor_companies add constraint surveyor_companies_offered_types_check
  check (offered_types <@ array['bunker_quantity_survey','bunker_delivery_survey','on_hire_bunker','on_hire_condition','on_hire_bc','off_hire_bunker','off_hire_condition','off_hire_bc']::text[]);

create or replace function public.sa_portal_dashboard()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_u surveyor_company_users%rowtype;
  v_c surveyor_companies%rowtype;
  v_res jsonb;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid();
  if not found then return null; end if;
  select * into v_c from surveyor_companies where id = v_u.company_id;

  select jsonb_build_object(
    'me', jsonb_build_object('full_name', v_u.full_name, 'email', v_u.email, 'is_office', v_u.is_office,
           'is_surveyor', v_u.is_surveyor, 'is_admin', v_u.is_admin, 'status', v_u.status,
           'role_label', case when v_u.is_office and v_u.is_surveyor then 'Office · Surveyor'
                              when v_u.is_office then 'Office' else 'Surveyor' end),
    'company', jsonb_build_object('id', v_c.id, 'name', v_c.name, 'country', v_c.country, 'status', v_c.status,
           'early_bird', v_c.early_bird, 'logo_path', v_c.logo_path, 'region_code', v_c.region_code,
           'region_name', (select name from sa_regions where code = v_c.region_code),
           'created_at', v_c.created_at, 'verified_at', v_c.verified_at,
           'awaiting_check', v_c.status = 'pending'),
    'credits', jsonb_build_object(
           'balance', (select coalesce(sum(remaining),0)::int from sa_credit_lots where company_id = v_c.id and remaining > 0 and expires_at > now()),
           'free', (select coalesce(sum(remaining),0)::int from sa_credit_lots where company_id = v_c.id and remaining > 0 and expires_at > now() and source in ('welcome','early_bird')),
           'next_expiry', (select min(expires_at) from sa_credit_lots where company_id = v_c.id and remaining > 0 and expires_at > now()),
           'low_warn', coalesce((select value::int from system_settings where key = 'sa_low_credit_warn'), 2)),
    'counts', jsonb_build_object(
           'upcoming', (select count(*) from surveyor_jobs j where j.company_id = v_c.id and j.status in ('draft','open','in_progress')
                          and (v_u.is_office or j.assigned_user_id = v_u.user_id)),
           'on_hold', (select count(*) from surveyor_jobs j where j.company_id = v_c.id and j.status = 'on_hold'
                          and (v_u.is_office or j.assigned_user_id = v_u.user_id)),
           'issued', (select count(*) from surveyor_jobs j where j.company_id = v_c.id and j.status = 'issued'),
           'issued_12m', (select count(*) from surveyor_jobs j where j.company_id = v_c.id and j.status = 'issued' and j.updated_at > now() - interval '12 months'),
           'vessels_12m', (select count(distinct coalesce(j.imo_number, j.vessel_name)) from surveyor_jobs j where j.company_id = v_c.id and j.status = 'issued' and j.updated_at > now() - interval '12 months')),
    'upcoming', coalesce((select jsonb_agg(x order by x->>'eta' nulls last) from (
           select jsonb_build_object('id', j.id, 'reference', j.reference, 'vessel', j.vessel_name, 'imo', j.imo_number,
                  'port', coalesce(h.name, j.port_text), 'eta', j.eta, 'etc', j.etc, 'survey_type', j.survey_type,
                  'client', sc.name, 'status', j.status, 'source', 'own') as x
           from surveyor_jobs j
           left join havens h on h.id = j.haven_id
           left join surveyor_clients sc on sc.id = j.surveyor_client_id
           where j.company_id = v_c.id and j.status in ('draft','open','in_progress','on_hold')
             and (v_u.is_office or j.assigned_user_id = v_u.user_id)
           order by j.eta nulls last limit 10) s), '[]'::jsonb),
    'recent', coalesce((select jsonb_agg(x) from (
           select jsonb_build_object('id', j.id, 'reference', j.reference, 'vessel', j.vessel_name,
                  'port', coalesce(h.name, j.port_text), 'survey_type', j.survey_type, 'client', sc.name, 'updated_at', j.updated_at) as x
           from surveyor_jobs j
           left join havens h on h.id = j.haven_id
           left join surveyor_clients sc on sc.id = j.surveyor_client_id
           where j.company_id = v_c.id and j.status = 'issued'
             and (v_u.is_office or j.assigned_user_id = v_u.user_id)
           order by j.updated_at desc limit 5) s), '[]'::jsonb)
  ) into v_res;
  return v_res;
end $$;

create or replace function public.sa_portal_company()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', c.id, 'name', c.name, 'domain', c.domain, 'country', c.country, 'address', c.address,
     'zip_code', c.zip_code, 'city', c.city, 'vat_number', c.vat_number, 'office_email', c.office_email,
     'invoice_email', c.invoice_email, 'phone', c.phone, 'website', c.website, 'logo_path', c.logo_path,
     'region_code', c.region_code, 'status', c.status, 'verified_at', c.verified_at,
     'offered_types', to_jsonb(c.offered_types), 'can_issue_certificate', c.can_issue_certificate, 'ports_text', c.ports_text,
     'can_edit', u.is_office,
     'regions', (select jsonb_agg(jsonb_build_object('code', code, 'name', name) order by sort) from sa_regions),
     'team', (select jsonb_agg(jsonb_build_object('full_name', m.full_name, 'email', m.email, 'is_office', m.is_office,
                 'is_surveyor', m.is_surveyor, 'is_admin', m.is_admin, 'status', m.status) order by m.created_at)
              from surveyor_company_users m where m.company_id = c.id))
  from surveyor_company_users u join surveyor_companies c on c.id = u.company_id
  where u.user_id = auth.uid()
$$;

create or replace function public.sa_portal_update_company(p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_u surveyor_company_users%rowtype;
  v_types text[];
  v_all text[] := array['bunker_quantity_survey','bunker_delivery_survey','on_hire_bunker','on_hire_condition','on_hire_bc','off_hire_bunker','off_hire_condition','off_hire_bc'];
  t text;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid();
  if not found or not v_u.is_office then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only office users can change company details.');
  end if;
  if p ? 'offered_types' then
    select coalesce(array_agg(distinct x), '{}') into v_types from jsonb_array_elements_text(p->'offered_types') x;
    foreach t in array v_types loop
      if not t = any(v_all) then return jsonb_build_object('ok', false, 'code', 'bad_type', 'message', 'Unknown survey type.'); end if;
    end loop;
    if cardinality(v_types) = 0 then
      return jsonb_build_object('ok', false, 'code', 'no_types', 'message', 'Select at least one survey type you offer.');
    end if;
  end if;
  if p ? 'region_code' and nullif(p->>'region_code','') is not null
     and not exists (select 1 from sa_regions where code = p->>'region_code') then
    return jsonb_build_object('ok', false, 'code', 'bad_region', 'message', 'Unknown region.');
  end if;

  update surveyor_companies c set
    country       = case when p ? 'country' then left(nullif(trim(p->>'country'),''), 80) else c.country end,
    address       = case when p ? 'address' then left(nullif(trim(p->>'address'),''), 200) else c.address end,
    zip_code      = case when p ? 'zip_code' then left(nullif(trim(p->>'zip_code'),''), 20) else c.zip_code end,
    city          = case when p ? 'city' then left(nullif(trim(p->>'city'),''), 80) else c.city end,
    vat_number    = case when p ? 'vat_number' then left(nullif(trim(p->>'vat_number'),''), 40) else c.vat_number end,
    phone         = case when p ? 'phone' then left(nullif(trim(p->>'phone'),''), 40) else c.phone end,
    website       = case when p ? 'website' then left(nullif(trim(p->>'website'),''), 200) else c.website end,
    office_email  = case when p ? 'office_email' then lower(left(nullif(trim(p->>'office_email'),''), 200)) else c.office_email end,
    invoice_email = case when p ? 'invoice_email' then lower(left(nullif(trim(p->>'invoice_email'),''), 200)) else c.invoice_email end,
    region_code   = case when p ? 'region_code' then nullif(p->>'region_code','') else c.region_code end,
    ports_text    = case when p ? 'ports_text' then left(nullif(trim(p->>'ports_text'),''), 500) else c.ports_text end,
    offered_types = case when p ? 'offered_types' then v_types else c.offered_types end,
    can_issue_certificate = case when p ? 'can_issue_certificate' then coalesce((p->>'can_issue_certificate')::boolean, c.can_issue_certificate) else c.can_issue_certificate end,
    updated_at = now()
  where c.id = v_u.company_id;
  return jsonb_build_object('ok', true, 'message', 'Saved.');
end $$;

create or replace function public.sa_notify_new_company()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_to text := coalesce(nullif((select value from system_settings where key = 'notify_email'), ''), 'reports@globalbqs.com');
begin
  perform gbqs_send_mail(v_to,
    'New surveyor sign-up – check company: ' || coalesce(new.name, '?'),
    format('<p>A new surveyor company signed up and is waiting for the company check.</p>'
        || '<table cellpadding="4" style="font-family:Arial,sans-serif;font-size:14px">'
        || '<tr><td><b>Company</b></td><td>%s</td></tr><tr><td><b>Country</b></td><td>%s</td></tr>'
        || '<tr><td><b>Domain</b></td><td>%s</td></tr><tr><td><b>Website</b></td><td>%s</td></tr>'
        || '<tr><td><b>Early registration</b></td><td>%s</td></tr></table>'
        || '<p>Approve or reject in the ops app (Surveyors › To check). The surveyor was told: up to two working days.</p>',
        coalesce(replace(replace(new.name,'<','&lt;'),'>','&gt;'),'–'), coalesce(new.country,'–'),
        coalesce(new.domain,'free e-mail address – credits after check'), coalesce(new.website,'–'),
        case when new.early_bird then 'yes' else 'no' end));
  return new;
exception when others then
  return new;
end $$;

drop trigger if exists trg_sa_notify_new_company on public.surveyor_companies;
create trigger trg_sa_notify_new_company after insert on public.surveyor_companies
  for each row execute function public.sa_notify_new_company();

