-- A5/A12: eigen logo van het surveybedrijf (opslag + koppeling)
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('surveyor-logos', 'surveyor-logos', false, 1048576, array['image/png','image/svg+xml','image/jpeg'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

create or replace function public.sa_is_office_of(p_company uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from surveyor_company_users u join surveyor_companies c on c.id = u.company_id
                 where u.user_id = auth.uid() and u.company_id = p_company and u.status = 'active'
                   and u.is_office and c.status in ('pending','approved'))
$$;
revoke all on function public.sa_is_office_of(uuid) from public, anon;
grant execute on function public.sa_is_office_of(uuid) to authenticated;

-- Map per bedrijf: <company_id>/logo-<tijd>.<ext>
drop policy if exists sa_logos_read on storage.objects;
create policy sa_logos_read on storage.objects for select to authenticated
  using (bucket_id = 'surveyor-logos' and (storage.foldername(name))[1] = public.sa_my_company_id()::text);
drop policy if exists sa_logos_insert on storage.objects;
create policy sa_logos_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'surveyor-logos' and public.sa_is_office_of(((storage.foldername(name))[1])::uuid));
drop policy if exists sa_logos_update on storage.objects;
create policy sa_logos_update on storage.objects for update to authenticated
  using (bucket_id = 'surveyor-logos' and public.sa_is_office_of(((storage.foldername(name))[1])::uuid));
drop policy if exists sa_logos_delete on storage.objects;
create policy sa_logos_delete on storage.objects for delete to authenticated
  using (bucket_id = 'surveyor-logos' and public.sa_is_office_of(((storage.foldername(name))[1])::uuid));

create or replace function public.sa_portal_set_logo(p_path text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_u surveyor_company_users%rowtype;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid();
  if not found or not v_u.is_office then
    return jsonb_build_object('ok', false, 'message', 'Only office users can change the logo.');
  end if;
  if p_path is not null and (p_path not like v_u.company_id::text || '/%'
       or not exists (select 1 from storage.objects o where o.bucket_id = 'surveyor-logos' and o.name = p_path)) then
    return jsonb_build_object('ok', false, 'message', 'The logo file was not found. Please upload it again.');
  end if;
  update surveyor_companies set logo_path = p_path, logo_updated_at = now(), updated_at = now() where id = v_u.company_id;
  return jsonb_build_object('ok', true, 'message', case when p_path is null then 'Logo removed.' else 'Logo saved.' end);
end $$;
