-- Bedrijfsgegevens: hoofdvestiging gelijk houden (stad, land, regio, havens)
create or replace function public.sa_portal_update_company(p jsonb)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare
  v_u surveyor_company_users%rowtype;
  v_types text[];
  v_all text[] := array['bunker_quantity_survey','bunker_delivery_survey','on_hire_bunker','on_hire_condition','on_hire_bc','off_hire_bunker','off_hire_condition','off_hire_bc'];
  t text;
  v_c surveyor_companies%rowtype;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid();
  if not found or not v_u.is_office then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only office users can change company details.');
  end if;
  if p ? 'offered_types' then
    select coalesce(array_agg(distinct x), '{}') into v_types from jsonb_array_elements_text(p->'offered_types') x;
    foreach t in array v_types loop
      if not t = any(v_all) then return jsonb_build_object('ok', false, 'code', 'bad_type', 'message', 'Unknown survey type.'); end if;
    end loop;
    if cardinality(v_types) = 0 then
      return jsonb_build_object('ok', false, 'code', 'no_types', 'message', 'Select at least one survey type you offer.');
    end if;
  end if;
  if p ? 'region_code' and nullif(p->>'region_code','') is not null
     and not exists (select 1 from sa_regions where code = p->>'region_code') then
    return jsonb_build_object('ok', false, 'code', 'bad_region', 'message', 'Unknown region.');
  end if;

  update surveyor_companies c set
    country       = case when p ? 'country' then left(nullif(trim(p->>'country'),''), 80) else c.country end,
    address       = case when p ? 'address' then left(nullif(trim(p->>'address'),''), 200) else c.address end,
    zip_code      = case when p ? 'zip_code' then left(nullif(trim(p->>'zip_code'),''), 20) else c.zip_code end,
    city          = case when p ? 'city' then left(nullif(trim(p->>'city'),''), 80) else c.city end,
    vat_number    = case when p ? 'vat_number' then left(nullif(trim(p->>'vat_number'),''), 40) else c.vat_number end,
    phone         = case when p ? 'phone' then left(nullif(trim(p->>'phone'),''), 40) else c.phone end,
    website       = case when p ? 'website' then left(nullif(trim(p->>'website'),''), 200) else c.website end,
    office_email  = case when p ? 'office_email' then lower(left(nullif(trim(p->>'office_email'),''), 200)) else c.office_email end,
    invoice_email = case when p ? 'invoice_email' then lower(left(nullif(trim(p->>'invoice_email'),''), 200)) else c.invoice_email end,
    region_code   = case when p ? 'region_code' then nullif(p->>'region_code','') else c.region_code end,
    ports_text    = case when p ? 'ports_text' then left(nullif(trim(p->>'ports_text'),''), 500) else c.ports_text end,
    offered_types = case when p ? 'offered_types' then v_types else c.offered_types end,
    can_issue_certificate = case when p ? 'can_issue_certificate' then coalesce((p->>'can_issue_certificate')::boolean, c.can_issue_certificate) else c.can_issue_certificate end,
    updated_at = now()
  where c.id = v_u.company_id
  returning * into v_c;

  -- Eén vestiging: die volgt de bedrijfsgegevens. Meer vestigingen: alleen als ze nog leeg zijn.
  update surveyor_company_locations l set
    city = v_c.city, country = v_c.country, region_code = v_c.region_code, ports_text = v_c.ports_text, updated_at = now()
  where l.company_id = v_c.id and l.is_main and l.archived_at is null
    and (select count(*) from surveyor_company_locations x where x.company_id = v_c.id and x.archived_at is null) = 1;

  return jsonb_build_object('ok', true, 'message', 'Saved.');
end $function$;

-- Vestiging opslaan (nieuw of wijzigen) – alleen Office
create or replace function public.sa_portal_save_location(p jsonb)
 returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_u surveyor_company_users%rowtype;
  v_id uuid := nullif(p->>'id','')::uuid;
  v_name text := left(nullif(trim(p->>'name'),''), 80);
  v_region text := nullif(p->>'region_code','');
  v_main boolean := coalesce((p->>'is_main')::boolean, false);
  v_l surveyor_company_locations%rowtype;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid();
  if not found or not v_u.is_office then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only office users can change locations.');
  end if;
  if v_name is null then
    return jsonb_build_object('ok', false, 'code', 'no_name', 'message', 'Give the location a name, for example the city.');
  end if;
  if v_region is not null and not exists (select 1 from sa_regions where code = v_region) then
    return jsonb_build_object('ok', false, 'code', 'bad_region', 'message', 'Unknown region.');
  end if;
  if v_id is not null then
    select * into v_l from surveyor_company_locations where id = v_id and company_id = v_u.company_id and archived_at is null;
    if not found then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Location not found.'); end if;
    if v_l.is_main then v_main := true; end if; -- hoofdvestiging blijft hoofdvestiging tot een andere het wordt
  end if;
  if v_main then
    update surveyor_company_locations set is_main = false, updated_at = now()
    where company_id = v_u.company_id and is_main and (v_id is null or id <> v_id);
  end if;
  if v_id is null then
    insert into surveyor_company_locations (company_id, name, city, country, region_code, ports_text, phone, email, is_main)
    values (v_u.company_id, v_name, left(nullif(trim(p->>'city'),''),80), left(nullif(trim(p->>'country'),''),80), v_region,
            left(nullif(trim(p->>'ports_text'),''),500), left(nullif(trim(p->>'phone'),''),40), lower(left(nullif(trim(p->>'email'),''),200)), v_main)
    returning * into v_l;
  else
    update surveyor_company_locations set
      name = v_name, city = left(nullif(trim(p->>'city'),''),80), country = left(nullif(trim(p->>'country'),''),80),
      region_code = v_region, ports_text = left(nullif(trim(p->>'ports_text'),''),500),
      phone = left(nullif(trim(p->>'phone'),''),40), email = lower(left(nullif(trim(p->>'email'),''),200)),
      is_main = v_main, updated_at = now()
    where id = v_id returning * into v_l;
  end if;
  -- Hoofdvestiging bepaalt stad/land/regio/havens van het bedrijf (achterwaarts compatibel)
  if v_l.is_main then
    update surveyor_companies set city = v_l.city, country = coalesce(v_l.country, country), region_code = v_l.region_code,
      ports_text = v_l.ports_text, updated_at = now() where id = v_u.company_id;
  end if;
  return jsonb_build_object('ok', true, 'id', v_l.id, 'message', 'Location saved.');
end $$;

-- Vestiging archiveren – niet de hoofdvestiging; surveyors zonder andere vestiging gaan naar de hoofdvestiging
create or replace function public.sa_portal_archive_location(p_id uuid)
 returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_u surveyor_company_users%rowtype;
  v_l surveyor_company_locations%rowtype;
  v_main uuid;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid();
  if not found or not v_u.is_office then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only office users can change locations.');
  end if;
  select * into v_l from surveyor_company_locations where id = p_id and company_id = v_u.company_id and archived_at is null;
  if not found then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Location not found.'); end if;
  if v_l.is_main then
    return jsonb_build_object('ok', false, 'code', 'is_main', 'message', 'Make another location the main office first.');
  end if;
  select id into v_main from surveyor_company_locations where company_id = v_u.company_id and is_main and archived_at is null;
  insert into surveyor_company_user_locations (user_id, location_id, company_id)
  select ul.user_id, v_main, ul.company_id from surveyor_company_user_locations ul
  where ul.location_id = p_id
    and not exists (select 1 from surveyor_company_user_locations o join surveyor_company_locations ol on ol.id = o.location_id
                    where o.user_id = ul.user_id and o.location_id <> p_id and ol.archived_at is null)
  on conflict do nothing;
  delete from surveyor_company_user_locations where location_id = p_id;
  update surveyor_company_locations set archived_at = now(), updated_at = now() where id = p_id;
  return jsonb_build_object('ok', true, 'message', 'Location removed.');
end $$;

-- Surveyor koppelen aan vestigingen – alleen Office, minstens één
create or replace function public.sa_portal_set_user_locations(p_user_id uuid, p_location_ids uuid[])
 returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_u surveyor_company_users%rowtype;
  v_ids uuid[];
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid();
  if not found or not v_u.is_office then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only office users can change this.');
  end if;
  if not exists (select 1 from surveyor_company_users where user_id = p_user_id and company_id = v_u.company_id) then
    return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Team member not found.');
  end if;
  select coalesce(array_agg(distinct x), '{}') into v_ids from unnest(coalesce(p_location_ids, '{}')) x;
  if cardinality(v_ids) = 0 then
    return jsonb_build_object('ok', false, 'code', 'none', 'message', 'Choose at least one location.');
  end if;
  if exists (select 1 from unnest(v_ids) x where not exists
             (select 1 from surveyor_company_locations l where l.id = x and l.company_id = v_u.company_id and l.archived_at is null)) then
    return jsonb_build_object('ok', false, 'code', 'bad_location', 'message', 'Unknown location.');
  end if;
  delete from surveyor_company_user_locations where user_id = p_user_id and not (location_id = any(v_ids));
  insert into surveyor_company_user_locations (user_id, location_id, company_id)
  select p_user_id, x, v_u.company_id from unnest(v_ids) x on conflict do nothing;
  return jsonb_build_object('ok', true, 'message', 'Saved.');
end $$;

-- Bedrijfsgegevens: nu met vestigingen en per teamlid de vestigingen
create or replace function public.sa_portal_company()
 returns jsonb language sql stable security definer set search_path to 'public' as $function$
  select jsonb_build_object('id', c.id, 'name', c.name, 'domain', c.domain, 'country', c.country, 'address', c.address,
     'zip_code', c.zip_code, 'city', c.city, 'vat_number', c.vat_number, 'office_email', c.office_email,
     'invoice_email', c.invoice_email, 'phone', c.phone, 'website', c.website, 'logo_path', c.logo_path,
     'region_code', c.region_code, 'status', c.status, 'verified_at', c.verified_at,
     'offered_types', to_jsonb(c.offered_types), 'can_issue_certificate', c.can_issue_certificate, 'ports_text', c.ports_text,
     'can_edit', u.is_office,
     'regions', (select jsonb_agg(jsonb_build_object('code', code, 'name', name) order by sort) from sa_regions),
     'locations', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'city', l.city, 'country', l.country,
                   'region_code', l.region_code, 'region_name', r.name, 'ports_text', l.ports_text, 'phone', l.phone, 'email', l.email,
                   'is_main', l.is_main,
                   'surveyors', (select count(*) from surveyor_company_user_locations ul join surveyor_company_users m on m.user_id = ul.user_id
                                 where ul.location_id = l.id and m.is_surveyor and m.status = 'active'))
                   order by l.is_main desc, l.name)
                 from surveyor_company_locations l left join sa_regions r on r.code = l.region_code
                 where l.company_id = c.id and l.archived_at is null), '[]'::jsonb),
     'team', (select jsonb_agg(jsonb_build_object('user_id', m.user_id, 'full_name', m.full_name, 'email', m.email, 'is_office', m.is_office,
                 'is_surveyor', m.is_surveyor, 'is_admin', m.is_admin, 'status', m.status,
                 'location_ids', coalesce((select jsonb_agg(ul.location_id) from surveyor_company_user_locations ul
                                   join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                                   where ul.user_id = m.user_id), '[]'::jsonb),
                 'location_names', coalesce((select string_agg(l.name, ', ' order by l.is_main desc, l.name) from surveyor_company_user_locations ul
                                   join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                                   where ul.user_id = m.user_id), ''))
                 order by m.created_at)
              from surveyor_company_users m where m.company_id = c.id))
  from surveyor_company_users u join surveyor_companies c on c.id = u.company_id
  where u.user_id = auth.uid()
$function$;

