create or replace function public.sa_job_visible(p_company uuid, p_assigned uuid, p_location uuid)
 returns boolean language sql stable security definer set search_path to 'public' as $$
  select exists (
    select 1 from surveyor_company_users u
    where u.user_id = auth.uid() and u.company_id = p_company and u.status = 'active'
      and (u.is_office
           or p_assigned = u.user_id
           or (p_location is not null and exists (select 1 from surveyor_company_user_locations ul
                where ul.user_id = u.user_id and ul.location_id = p_location and ul.is_manager))))
$$;
revoke all on function public.sa_job_visible(uuid, uuid, uuid) from public, anon;
