create or replace view public.sa_v_my_jobs as
 SELECT j.id, j.reference, j.status, j.on_hold_reason, j.survey_type, j.eta, j.etb, j.etc, j.client_reference,
    COALESCE(v.display_name, v.vessel_name, j.vessel_name) AS vessel_name,
    COALESCE(v.imo_number, j.imo_number) AS imo_number,
    COALESCE(h.naam, j.port_text) AS port, h.land_code, gbqs_haven_region(j.haven_id) AS region_code,
    sc.name AS client_name, s.name AS surveyor_name, j.credit_used, j.survey_id, j.created_at, j.updated_at,
    j.location_id, l.name AS location_name
   FROM surveyor_jobs j
     LEFT JOIN vessels v ON v.id = j.vessel_id
     LEFT JOIN havens h ON h.id = j.haven_id
     LEFT JOIN surveyor_clients sc ON sc.id = j.surveyor_client_id
     LEFT JOIN surveyors s ON s.id = j.assigned_surveyor_id
     LEFT JOIN surveyor_company_locations l ON l.id = j.location_id
  WHERE j.company_id = sa_my_company_id() AND sa_job_visible(j.company_id, j.assigned_user_id, j.location_id);

do $do$
declare d text; n text;
begin
  d := pg_get_functiondef('public.sa_portal_dashboard'::regproc);
  n := replace(d, '(v_u.is_office or j.assigned_user_id = v_u.user_id)', 'sa_job_visible(j.company_id, j.assigned_user_id, j.location_id)');
  n := replace(n, 'when v_u.is_office then ''Office'' else ''Surveyor'' end',
    'when v_u.is_office then ''Office'' when exists (select 1 from surveyor_company_user_locations x where x.user_id = v_u.user_id and x.is_manager) then ''Location manager'' else ''Surveyor'' end');
  if n = d or position('v_u.is_office or j.assigned_user_id' in n) > 0 or position('Location manager' in n) = 0 then
    raise exception 'sa_portal_dashboard patch did not apply';
  end if;
  execute n;
end $do$;

create or replace function public.sa_portal_me()
 returns jsonb language sql stable security definer set search_path to 'public' as $function$
  select jsonb_build_object(
    'kind', 'surveyor', 'user_id', u.user_id, 'email', u.email, 'full_name', u.full_name,
