                          from surveyor_company_user_locations ul join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                          where ul.user_id = u.user_id and ul.is_manager), '[]'::jsonb),
    'is_location_manager', exists (select 1 from surveyor_company_user_locations ul join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                          where ul.user_id = u.user_id and ul.is_manager))
