  end if;
  if exists (select 1 from unnest(v_ids) x where not exists
             (select 1 from surveyor_company_locations l where l.id = x and l.company_id = v_u.company_id and l.archived_at is null)) then
    return jsonb_build_object('ok', false, 'code', 'bad_location', 'message', 'Unknown location.');
  end if;
  select coalesce(array_agg(distinct x), '{}') into v_mgr from unnest(coalesce(p_manager_ids, '{}')) x;
  if exists (select 1 from unnest(v_mgr) x where not (x = any(v_ids))) then
    return jsonb_build_object('ok', false, 'code', 'bad_manager', 'message', 'A manager location must also be one of the selected locations.');
  end if;
  delete from surveyor_company_user_locations where user_id = p_user_id and not (location_id = any(v_ids));
  insert into surveyor_company_user_locations (user_id, location_id, company_id)
  select p_user_id, x, v_u.company_id from unnest(v_ids) x on conflict do nothing;
  update surveyor_company_user_locations set is_manager = (location_id = any(v_mgr)) where user_id = p_user_id;
  return jsonb_build_object('ok', true, 'message', 'Saved.');
end $$;
revoke all on function public.sa_portal_set_user_locations(uuid, uuid[], uuid[]) from public, anon;
grant execute on function public.sa_portal_set_user_locations(uuid, uuid[], uuid[]) to authenticated;

do $do$
declare d text; n text;
begin
  d := pg_get_functiondef('public.sa_portal_company'::regproc);
  n := replace(d, '''location_names'', coalesce(',
    '''manager_location_ids'', coalesce((select jsonb_agg(ul.location_id) from surveyor_company_user_locations ul
                                   join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                                   where ul.user_id = m.user_id and ul.is_manager), ''[]''::jsonb),
