                                   join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                                   where ul.user_id = m.user_id and ul.is_manager), ''''),
                 ''location_names'', coalesce(');
  if n = d then raise exception 'sa_portal_company patch did not apply'; end if;
  execute n;
end $do$;

-- Bedrijfsgegevens, logo, services, vestigingen en team: alleen de admin wijzigt (besluit Richard 06-11)
do $do$
declare r record; d text; n text;
begin
  for r in select p.oid, p.proname from pg_proc p where p.pronamespace = 'public'::regnamespace
           and p.proname in ('sa_portal_update_company','sa_portal_save_location','sa_portal_archive_location','sa_portal_set_user_locations','sa_portal_set_logo')
  loop
    d := pg_get_functiondef(r.oid);
    n := replace(d, 'not v_u.is_office', 'not v_u.is_admin');
    n := replace(n, 'Only office users can change company details.', 'Only the company admin can change company details.');
    n := replace(n, 'Only office users can change locations.', 'Only the company admin can change locations.');
    n := replace(n, 'Only office users can change this.', 'Only the company admin can change this.');
    n := replace(n, 'Only office users can change the logo.', 'Only the company admin can change the logo.');
    if n = d then raise exception 'patch did not apply to %', r.proname; end if;
    execute n;
  end loop;

  d := pg_get_functiondef('public.sa_is_office_of'::regproc);
  n := replace(d, 'and u.is_office and', 'and u.is_admin and');
  if n = d then raise exception 'patch did not apply to sa_is_office_of'; end if;
  execute n;

  d := pg_get_functiondef('public.sa_portal_company'::regproc);
  n := replace(d, '''can_edit'', u.is_office', '''can_edit'', u.is_admin, ''is_office'', u.is_office');
  if n = d then raise exception 'patch did not apply to sa_portal_company'; end if;
  execute n;
end $do$;

