create or replace function public.sa_can_manage_location(p_location uuid)
returns boolean language sql stable security definer set search_path to 'public' as $$
  select exists (
    select 1 from surveyor_company_users u
    join surveyor_company_locations l on l.id = p_location and l.company_id = u.company_id and l.archived_at is null
    where u.user_id = auth.uid() and u.status = 'active'
      and (u.is_admin or u.is_office
           or exists (select 1 from surveyor_company_user_locations ul
                      where ul.user_id = u.user_id and ul.location_id = p_location and ul.is_manager)))
$$;

create or replace function public.sa_can_create_jobs()
returns boolean language sql stable security definer set search_path to 'public' as $$
  select exists (
    select 1 from surveyor_company_users u
    where u.user_id = auth.uid() and u.status = 'active'
      and (u.is_admin or u.is_office
           or exists (select 1 from surveyor_company_user_locations ul where ul.user_id = u.user_id and ul.is_manager)))
$$;

create or replace function public.sa_portal_job_options()
returns jsonb language plpgsql stable security definer set search_path to 'public' as $$
declare v_u surveyor_company_users%rowtype; v_c surveyor_companies%rowtype; v_all boolean;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid() and status = 'active';
  if not found then return null; end if;
  select * into v_c from surveyor_companies where id = v_u.company_id;
  v_all := v_u.is_admin or v_u.is_office;
  return jsonb_build_object(
    'can_create', sa_can_create_jobs(),
    'company_status', v_c.status,
    'offered_types', to_jsonb(coalesce(v_c.offered_types, '{}'::text[])),
    'credits', sa_credit_balance(v_c.id),
    'clients', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'contact_name', c.contact_name,
                 'report_emails', to_jsonb(coalesce(c.report_emails, '{}'::text[]))) order by lower(c.name))
               from surveyor_clients c where c.company_id = v_c.id and c.archived_at is null), '[]'::jsonb),
    'locations', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'is_main', l.is_main) order by l.is_main desc, lower(l.name))
               from surveyor_company_locations l where l.company_id = v_c.id and l.archived_at is null
                 and (v_all or sa_can_manage_location(l.id))), '[]'::jsonb),
    'team', coalesce((select jsonb_agg(jsonb_build_object('user_id', u.user_id, 'name', coalesce(nullif(u.full_name,''), u.email),
                 'location_ids', coalesce((select jsonb_agg(ul.location_id) from surveyor_company_user_locations ul where ul.user_id = u.user_id), '[]'::jsonb))
                 order by lower(coalesce(nullif(u.full_name,''), u.email)))
               from surveyor_company_users u where u.company_id = v_c.id and u.status = 'active' and u.is_surveyor), '[]'::jsonb)
  );
end $$;

create or replace function public.sa_portal_port_search(p_q text)
returns jsonb language sql stable security definer set search_path to 'public' as $$
  select coalesce(jsonb_agg(x), '[]'::jsonb) from (
    select jsonb_build_object('id', h.id, 'name', h.naam, 'country', h.land_code, 'unlocode', h.unlocode) x
    from havens h
    where sa_my_company_id() is not null and length(trim(coalesce(p_q,''))) >= 2
      and (h.naam ilike '%' || trim(p_q) || '%' or h.unlocode ilike trim(p_q) || '%'
           or exists (select 1 from unnest(coalesce(h.alias, '{}'::text[])) a where a ilike '%' || trim(p_q) || '%'))
    order by (h.naam ilike trim(p_q) || '%') desc, length(h.naam), h.naam
    limit 20) s
$$;

create or replace function public.sa_imo_valid(p_imo text)
returns boolean language sql immutable as $$
  select p_imo ~ '^[0-9]{7}$' and (
    (substr(p_imo,1,1)::int*7 + substr(p_imo,2,1)::int*6 + substr(p_imo,3,1)::int*5 + substr(p_imo,4,1)::int*4
     + substr(p_imo,5,1)::int*3 + substr(p_imo,6,1)::int*2) % 10 = substr(p_imo,7,1)::int)
$$;

create or replace function public.sa_portal_vessel_lookup(p_imo text)
returns jsonb language plpgsql stable security definer set search_path to 'public' as $$
declare v_imo text := regexp_replace(coalesce(p_imo,''), '\D', '', 'g'); v_v vessels%rowtype;
begin
  if sa_my_company_id() is null then return null; end if;
  if not sa_imo_valid(v_imo) then return jsonb_build_object('ok', false, 'code', 'bad_imo', 'message', 'This is not a valid IMO number (7 digits with check digit).'); end if;
  select * into v_v from vessels where imo_number = v_imo limit 1;
  if found then return jsonb_build_object('ok', true, 'known', true, 'imo', v_imo, 'vessel_name', coalesce(v_v.display_name, v_v.vessel_name)); end if;
  return jsonb_build_object('ok', true, 'known', false, 'imo', v_imo,
    'vessel_name', (select j.vessel_name from surveyor_jobs j where j.company_id = sa_my_company_id() and j.imo_number = v_imo order by j.created_at desc limit 1));
end $$;

create or replace function public.sa_portal_save_client(p jsonb)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare v_u surveyor_company_users%rowtype; v_id uuid := nullif(p->>'id','')::uuid;
  v_name text := left(nullif(trim(p->>'name'),''), 120); v_emails text[]; v_c surveyor_clients%rowtype; e text;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid() and status = 'active';
  if not found or not sa_can_create_jobs() then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'You cannot add clients.');
  end if;
  if v_name is null then return jsonb_build_object('ok', false, 'code', 'no_name', 'message', 'Enter the client name.'); end if;
  select coalesce(array_agg(distinct lower(trim(x))) filter (where trim(x) <> ''), '{}') into v_emails
    from jsonb_array_elements_text(coalesce(p->'report_emails', '[]'::jsonb)) x;
  foreach e in array v_emails loop
    if e !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then
      return jsonb_build_object('ok', false, 'code', 'bad_email', 'message', 'Not a valid e-mail address: ' || e);
    end if;
  end loop;
  if cardinality(v_emails) = 0 then
    return jsonb_build_object('ok', false, 'code', 'no_email', 'message', 'Enter at least one e-mail address for the report.');
  end if;
  if v_id is null then
    insert into surveyor_clients (company_id, name, contact_name, report_emails, country, domain)
    values (v_u.company_id, v_name, left(nullif(trim(p->>'contact_name'),''),120), v_emails,
            left(nullif(trim(p->>'country'),''),80), split_part(v_emails[1], '@', 2))
    returning * into v_c;
  else
    update surveyor_clients set name = v_name, contact_name = left(nullif(trim(p->>'contact_name'),''),120),
      report_emails = v_emails, country = left(nullif(trim(p->>'country'),''),80), updated_at = now()
    where id = v_id and company_id = v_u.company_id returning * into v_c;
    if not found then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Client not found.'); end if;
  end if;
  return jsonb_build_object('ok', true, 'id', v_c.id, 'name', v_c.name, 'message', 'Client saved.');
end $$;

create or replace function public.sa_lt(p text)
returns timestamptz language sql immutable as $$
  select case when nullif(trim(coalesce(p,'')),'') is null then null
              else (left(trim(p), 16)::timestamp at time zone 'UTC') end
$$;

create or replace function public.sa_portal_create_job(p jsonb)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare
  v_u surveyor_company_users%rowtype; v_c surveyor_companies%rowtype;
  v_client uuid := nullif(p->>'client_id','')::uuid;
  v_loc uuid := nullif(p->>'location_id','')::uuid;
  v_user uuid := nullif(p->>'assigned_user_id','')::uuid;
  v_haven uuid := nullif(p->>'haven_id','')::uuid;
  v_type text := nullif(p->>'survey_type','');
  v_imo text := regexp_replace(coalesce(p->>'imo_number',''), '\D', '', 'g');
  v_vessel text := left(nullif(trim(p->>'vessel_name'),''), 120);
  v_port text := left(nullif(trim(p->>'port_text'),''), 120);
  v_eta timestamptz; v_etb timestamptz; v_etc timestamptz;
  v_vid uuid; v_ref text; v_id uuid; v_sid uuid;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid() and status = 'active';
  if not found or not sa_can_create_jobs() then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only the office or a location manager can create jobs.');
  end if;
  select * into v_c from surveyor_companies where id = v_u.company_id;
  if v_c.status in ('blocked','rejected','suspended') then
    return jsonb_build_object('ok', false, 'code', 'company_blocked', 'message', 'Your company account is not active. Please contact surveyors@globalbqs.com.');
  end if;
  if v_client is null or not exists (select 1 from surveyor_clients where id = v_client and company_id = v_c.id and archived_at is null) then
    return jsonb_build_object('ok', false, 'code', 'no_client', 'message', 'Choose the client.');
  end if;
  if v_type is null or not v_type = any(coalesce(v_c.offered_types, '{}')) then
    return jsonb_build_object('ok', false, 'code', 'bad_type', 'message', 'Choose a survey type you offer (see Services & locations).');
  end if;
  if not sa_imo_valid(v_imo) then
    return jsonb_build_object('ok', false, 'code', 'bad_imo', 'message', 'Enter a valid IMO number (7 digits).');
  end if;
  if v_vessel is null then return jsonb_build_object('ok', false, 'code', 'no_vessel', 'message', 'Enter the vessel name.'); end if;
  if v_haven is null and v_port is null then return jsonb_build_object('ok', false, 'code', 'no_port', 'message', 'Choose the port.'); end if;
  if v_haven is not null and not exists (select 1 from havens where id = v_haven) then
    return jsonb_build_object('ok', false, 'code', 'bad_port', 'message', 'Unknown port.');
  end if;
  begin
    v_eta := sa_lt(p->>'eta'); v_etb := sa_lt(p->>'etb'); v_etc := sa_lt(p->>'etc');
  exception when others then
    return jsonb_build_object('ok', false, 'code', 'bad_time', 'message', 'One of the dates is not valid.');
  end;
  if v_eta is null then return jsonb_build_object('ok', false, 'code', 'no_eta', 'message', 'Enter the ETA (local time).'); end if;
  if v_etc is not null and v_etc < v_eta then
    return jsonb_build_object('ok', false, 'code', 'bad_etc', 'message', 'ETC cannot be before the ETA.');
  end if;
  if v_loc is null then
    select id into v_loc from surveyor_company_locations where company_id = v_c.id and archived_at is null
      and sa_can_manage_location(id) order by is_main desc limit 1;
  end if;
  if v_loc is null or not sa_can_manage_location(v_loc) then
    return jsonb_build_object('ok', false, 'code', 'bad_location', 'message', 'Choose a location you manage.');
  end if;
  if v_user is null then return jsonb_build_object('ok', false, 'code', 'no_surveyor', 'message', 'Choose the attending surveyor.'); end if;
  if not exists (select 1 from surveyor_company_users x where x.user_id = v_user and x.company_id = v_c.id and x.status = 'active' and x.is_surveyor) then
    return jsonb_build_object('ok', false, 'code', 'bad_surveyor', 'message', 'This surveyor is not active in your company.');
  end if;
  if not (v_u.is_admin or v_u.is_office)
     and not exists (select 1 from surveyor_company_user_locations ul where ul.user_id = v_user and ul.location_id = v_loc) then
    return jsonb_build_object('ok', false, 'code', 'surveyor_not_at_location', 'message', 'This surveyor does not work at the chosen location.');
  end if;
  select id into v_vid from vessels where imo_number = v_imo limit 1;
  select surveyor_id into v_sid from surveyor_company_users where user_id = v_user;
  v_ref := sa_next_job_reference();
  insert into surveyor_jobs (company_id, reference, surveyor_client_id, vessel_id, vessel_name, imo_number, haven_id, port_text,
     berth_or_terminal, eta, etb, etc, survey_type, client_reference, assigned_surveyor_id, assigned_user_id, status, location_id, created_by)
  values (v_c.id, v_ref, v_client, v_vid, v_vessel, v_imo, v_haven, case when v_haven is null then v_port end,
     left(nullif(trim(p->>'berth_or_terminal'),''),120), v_eta, v_etb, v_etc, v_type, left(nullif(trim(p->>'client_reference'),''),80),
     v_sid, v_user, 'open', v_loc, auth.uid())
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'reference', v_ref, 'message', 'Job ' || v_ref || ' created.');
end $$;

create or replace function public.sa_portal_jobs(p_scope text default 'open')
returns jsonb language sql stable security definer set search_path to 'public' as $$
  select coalesce(jsonb_agg(x order by (x->>'sort_at') nulls last), '[]'::jsonb) from (
    select jsonb_build_object('id', j.id, 'reference', j.reference, 'status', j.status, 'on_hold_reason', j.on_hold_reason,
      'survey_type', j.survey_type, 'eta', j.eta, 'etb', j.etb, 'etc', j.etc, 'client_reference', j.client_reference,
      'vessel', coalesce(v.display_name, v.vessel_name, j.vessel_name), 'imo', j.imo_number,
      'port', coalesce(h.naam, j.port_text), 'country', h.land_code, 'berth', j.berth_or_terminal,
      'client', sc.name, 'location', l.name, 'location_id', j.location_id,
      'surveyor', coalesce(nullif(u.full_name,''), u.email), 'assigned_user_id', j.assigned_user_id,
      'is_mine', j.assigned_user_id = auth.uid(), 'credit_used', j.credit_used, 'source', case when j.gbqs_order_id is null then 'own' else 'gbqs' end,
      'can_cancel', j.status in ('draft','open') and sa_can_manage_location(j.location_id),
      'created_at', j.created_at, 'updated_at', j.updated_at,
      'sort_at', case when p_scope = 'done' then to_char(now() - j.updated_at, 'YYYYMMDDHH24MISS') else to_char(j.eta, 'YYYYMMDDHH24MI') end) x
    from surveyor_jobs j
    left join vessels v on v.id = j.vessel_id
    left join havens h on h.id = j.haven_id
    left join surveyor_clients sc on sc.id = j.surveyor_client_id
    left join surveyor_company_locations l on l.id = j.location_id
    left join surveyor_company_users u on u.user_id = j.assigned_user_id
    where j.company_id = sa_my_company_id() and sa_job_visible(j.company_id, j.assigned_user_id, j.location_id)
      and (p_scope = 'all'
           or (p_scope = 'open' and j.status in ('draft','open','in_progress','on_hold','submitted'))
           or (p_scope = 'done' and j.status in ('issued','cancelled','merged')))
    limit 300) s
$$;

create or replace function public.sa_portal_cancel_job(p_id uuid)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare v_j surveyor_jobs%rowtype;
begin
  select * into v_j from surveyor_jobs where id = p_id and company_id = sa_my_company_id();
  if not found then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Job not found.'); end if;
  if not sa_can_manage_location(v_j.location_id) then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only the office or the location manager can cancel this job.');
  end if;
  if v_j.status not in ('draft','open') then
    return jsonb_build_object('ok', false, 'code', 'not_open', 'message', 'This job has started and can no longer be cancelled here.');
  end if;
  update surveyor_jobs set status = 'cancelled', updated_at = now() where id = p_id;
  return jsonb_build_object('ok', true, 'message', 'Job ' || v_j.reference || ' cancelled.');
end $$;

revoke all on function public.sa_can_manage_location(uuid), public.sa_can_create_jobs(), public.sa_portal_job_options(),
  public.sa_portal_port_search(text), public.sa_portal_vessel_lookup(text), public.sa_portal_save_client(jsonb),
  public.sa_portal_create_job(jsonb), public.sa_portal_jobs(text), public.sa_portal_cancel_job(uuid) from public, anon;
grant execute on function public.sa_can_manage_location(uuid), public.sa_can_create_jobs(), public.sa_portal_job_options(),
  public.sa_portal_port_search(text), public.sa_portal_vessel_lookup(text), public.sa_portal_save_client(jsonb),
  public.sa_portal_create_job(jsonb), public.sa_portal_jobs(text), public.sa_portal_cancel_job(uuid) to authenticated, service_role;
grant execute on function public.sa_imo_valid(text), public.sa_lt(text) to authenticated, service_role;

