-- Havens van een vestiging zetten (alleen admin); regio en tekstveld volgen automatisch
create or replace function public.sa_portal_set_location_ports(p_location uuid, p_haven_ids uuid[])
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare v_u surveyor_company_users%rowtype; v_l surveyor_company_locations%rowtype; v_ids uuid[]; v_txt text; v_reg text;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid() and status = 'active';
  if not found or not v_u.is_admin then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only the company admin can change ports.');
  end if;
  select * into v_l from surveyor_company_locations where id = p_location and company_id = v_u.company_id and archived_at is null;
  if not found then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Location not found.'); end if;
  select coalesce(array_agg(distinct h.id), '{}') into v_ids from havens h where h.id = any(coalesce(p_haven_ids, '{}'));
  if cardinality(v_ids) > 200 then return jsonb_build_object('ok', false, 'code', 'too_many', 'message', 'Maximum 200 ports per location.'); end if;
  delete from surveyor_location_ports where location_id = v_l.id and not (haven_id = any(v_ids));
  insert into surveyor_location_ports (location_id, haven_id, company_id)
    select v_l.id, x, v_u.company_id from unnest(v_ids) x on conflict do nothing;
  select left(string_agg(h.naam, ', ' order by h.naam), 500) into v_txt from surveyor_location_ports p join havens h on h.id = p.haven_id where p.location_id = v_l.id;
  select r into v_reg from (select gbqs_haven_region(p.haven_id) r, count(*) n from surveyor_location_ports p where p.location_id = v_l.id group by 1 order by 2 desc limit 1) s where r is not null;
  update surveyor_company_locations set ports_text = v_txt, region_code = coalesce(v_reg, region_code), updated_at = now() where id = v_l.id;
  if v_l.is_main then
    update surveyor_companies set ports_text = v_txt, region_code = coalesce(v_reg, region_code), updated_at = now() where id = v_u.company_id;
  end if;
  return jsonb_build_object('ok', true, 'count', cardinality(v_ids), 'region_code', v_reg, 'message', 'Ports saved.');
end $$;

-- Havens zoeken; met vestiging eerst de havens van die vestiging (covered = true)
create or replace function public.sa_portal_port_search(p_q text, p_location uuid)
returns jsonb language sql stable security definer set search_path to 'public' as $$
  select coalesce(jsonb_agg(x), '[]'::jsonb) from (
    select jsonb_build_object('id', h.id, 'name', h.naam, 'country', h.land_code, 'unlocode', h.unlocode,
             'covered', exists (select 1 from surveyor_location_ports lp where lp.location_id = p_location and lp.haven_id = h.id)) x
    from havens h
    where sa_my_company_id() is not null and length(trim(coalesce(p_q,''))) >= 2
      and (h.naam ilike '%' || trim(p_q) || '%' or h.unlocode ilike trim(p_q) || '%'
           or exists (select 1 from unnest(coalesce(h.alias, '{}'::text[])) a where a ilike '%' || trim(p_q) || '%'))
    order by exists (select 1 from surveyor_location_ports lp where lp.location_id = p_location and lp.haven_id = h.id) desc,
             (h.naam ilike trim(p_q) || '%') desc, length(h.naam), h.naam
    limit 20) s
$$;

-- Haven ontbreekt: verzoek van surveyor of klant, mail aan ops@
create or replace function public.portal_request_port(p jsonb)
returns jsonb language plpgsql security definer set search_path to 'public', 'auth' as $$
declare v_name text := left(nullif(btrim(p->>'port_name'),''), 120); v_country text := upper(left(nullif(btrim(p->>'country'),''), 60));
  v_lo text := upper(regexp_replace(coalesce(p->>'unlocode',''), '\s', '', 'g')); v_note text := left(nullif(btrim(p->>'note'),''), 1000);
  v_src text; v_email text; v_person text; v_company text; v_sc uuid; v_cl uuid; n int; v_id uuid; v_html text;
  row_tpl text := '<tr><td style="padding:4px 12px 4px 0;color:#5c6b85;white-space:nowrap;vertical-align:top;">%s</td><td style="padding:4px 0;color:#10203d;">%s</td></tr>';
begin
  if auth.uid() is null then return jsonb_build_object('ok', false, 'message', 'Please sign in again.'); end if;
  if v_name is null then return jsonb_build_object('ok', false, 'message', 'Enter the name of the port.'); end if;
  if v_lo = '' then v_lo := null; end if;
  if v_lo is not null and v_lo !~ '^[A-Z]{2}[A-Z0-9]{3}$' then
    return jsonb_build_object('ok', false, 'message', 'A UN/LOCODE has 5 characters, e.g. NLRTM. Leave it empty if you do not know it.');
  end if;
  select count(*) into n from port_requests where user_id = auth.uid() and created_at > now() - interval '1 hour';
  if n >= 10 then return jsonb_build_object('ok', false, 'message', 'You have sent several requests in the last hour. Please try again later.'); end if;
  select au.email into v_email from auth.users au where au.id = auth.uid();
  select u.company_id, coalesce(nullif(u.full_name,''), u.email), c.name into v_sc, v_person, v_company
    from surveyor_company_users u join surveyor_companies c on c.id = u.company_id where u.user_id = auth.uid();
  if v_sc is not null then v_src := 'surveyor';
  else
    select cu.client_id, cu.full_name, cl.company into v_cl, v_person, v_company
      from client_users cu join clients cl on cl.id = cu.client_id where cu.user_id = auth.uid() limit 1;
    v_src := 'client';
  end if;
  insert into port_requests (source, user_id, email, requester_name, company_name, surveyor_company_id, client_id, port_name, country, unlocode, note)
  values (v_src, auth.uid(), v_email, v_person, v_company, v_sc, v_cl, v_name, v_country, v_lo, v_note) returning id into v_id;
  v_html := '<p style="margin:0 0 14px;">A ' || v_src || ' asks to add a port that is missing from the port list.</p>'
    || '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="font-size:13px;line-height:19px;">'
    || format(row_tpl, 'Port', gbqs_html_esc(v_name))
    || format(row_tpl, 'Country', coalesce(gbqs_html_esc(v_country), '–'))
    || format(row_tpl, 'UN/LOCODE', coalesce(gbqs_html_esc(v_lo), '–'))
    || format(row_tpl, 'Note', coalesce(gbqs_html_esc(v_note), '–'))
    || format(row_tpl, 'From', coalesce(gbqs_html_esc(v_person), '–') || ' · ' || coalesce(gbqs_html_esc(v_company), '–') || ' (' || v_src || ')')
    || format(row_tpl, 'E-mail', coalesce(gbqs_html_esc(v_email), '–'))
    || '</table><p style="margin:14px 0 0;color:#5c6b85;font-size:12px;">Add or link the port in the ops app (Port requests); the requester gets an e-mail when it is done.</p>';
  begin
    perform gbqs_send_mail_ext('ops@globalbqs.com', 'Port request: ' || v_name || coalesce(' (' || v_country || ')', '') || ' – ' || coalesce(v_company, v_email, ''),
      gbqs_mail_wrap('PORT REQUEST', v_html), null, v_email);
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'id', v_id, 'message', 'Thank you. We will add the port and let you know by e-mail, usually within one working day.');
end $$;

-- Ops: overzicht en afhandelen (alleen service_role, voor Retool)
create or replace view public.ops_port_requests as
  select r.*, h.naam as haven_name, h.land_code as haven_country, h.unlocode as haven_unlocode,
    (select h2.id from havens h2 where r.unlocode is not null and h2.unlocode = r.unlocode limit 1) as suggested_haven_id
  from port_requests r left join havens h on h.id = r.haven_id;
revoke all on public.ops_port_requests from public, anon, authenticated;
grant select on public.ops_port_requests to service_role;

create or replace function public.ops_port_request_resolve(p_id uuid, p_action text, p jsonb default '{}'::jsonb, p_by text default null)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare v_r port_requests%rowtype; v_h uuid; v_name text; v_html text; v_lo text;
begin
  select * into v_r from port_requests where id = p_id for update;
  if not found then return jsonb_build_object('ok', false, 'message', 'Verzoek niet gevonden.'); end if;
  if v_r.status <> 'new' then return jsonb_build_object('ok', false, 'message', 'Verzoek is al afgehandeld.'); end if;
  if p_action = 'add' then
    v_name := nullif(btrim(coalesce(p->>'naam', v_r.port_name)), '');
    v_lo := upper(nullif(btrim(coalesce(p->>'unlocode', v_r.unlocode)), ''));
    if v_name is null or nullif(btrim(coalesce(p->>'land_code','')), '') is null then
      return jsonb_build_object('ok', false, 'message', 'Naam en landcode (2 letters) zijn verplicht.');
    end if;
    if v_lo is not null and exists (select 1 from havens where unlocode = v_lo) then
      return jsonb_build_object('ok', false, 'message', 'Er bestaat al een haven met UN/LOCODE ' || v_lo || ' – kies Koppelen.');
    end if;
    insert into havens (naam, land_code, unlocode, latitude, longitude, alias)
    values (v_name, upper(left(btrim(p->>'land_code'), 2)), v_lo, nullif(p->>'latitude','')::numeric, nullif(p->>'longitude','')::numeric,
            case when lower(v_r.port_name) <> lower(v_name) then array[v_r.port_name] else null end)
    returning id into v_h;
    update port_requests set status = 'added', haven_id = v_h, resolved_by = p_by, resolved_at = now(), resolution_note = p->>'note' where id = p_id;
  elsif p_action = 'link' then
    v_h := nullif(p->>'haven_id','')::uuid;
    if v_h is null or not exists (select 1 from havens where id = v_h) then return jsonb_build_object('ok', false, 'message', 'Kies een bestaande haven.'); end if;
    if coalesce((p->>'add_alias')::boolean, true) then
      update havens set alias = case when alias is null then array[v_r.port_name]
                                     when not (v_r.port_name = any(alias)) then alias || v_r.port_name else alias end
       where id = v_h and lower(naam) <> lower(v_r.port_name);
    end if;
    update port_requests set status = 'linked', haven_id = v_h, resolved_by = p_by, resolved_at = now(), resolution_note = p->>'note' where id = p_id;
  elsif p_action = 'reject' then
    update port_requests set status = 'rejected', resolved_by = p_by, resolved_at = now(), resolution_note = p->>'note' where id = p_id;
  else
    return jsonb_build_object('ok', false, 'message', 'Onbekende actie.');
  end if;
  if v_r.email is not null then
    select naam into v_name from havens where id = v_h;
    v_html := case when p_action = 'reject'
      then '<p>Thank you for your request to add <strong>' || gbqs_html_esc(v_r.port_name) || '</strong>. We could not add this port'
           || coalesce(': ' || gbqs_html_esc(nullif(p->>'note_en','')), '.') || '</p><p>Questions? Reply to this e-mail.</p>'
      else '<p>Thank you for your request. <strong>' || gbqs_html_esc(v_name) || '</strong> is now available in the GlobalBQS port list'
           || case when p_action = 'link' then ' (it was already listed under this name; we added your spelling so it is easier to find)' else '' end
           || '. You can select it straight away.</p>' end;
    begin perform gbqs_send_mail(v_r.email, 'Port request: ' || v_r.port_name, gbqs_mail_wrap('PORT LIST', v_html)); exception when others then null; end;
  end if;
  return jsonb_build_object('ok', true, 'haven_id', v_h, 'message', 'Verzoek afgehandeld.');
end $$;

-- Vestigingen in sa_portal_company met havens (zelfde functie, uitgebreid)
create or replace function public.sa_portal_company()
 returns jsonb language sql stable security definer set search_path to 'public' as $function$
  select jsonb_build_object('id', c.id, 'name', c.name, 'domain', c.domain, 'country', c.country, 'address', c.address,
     'zip_code', c.zip_code, 'city', c.city, 'vat_number', c.vat_number, 'office_email', c.office_email,
     'invoice_email', c.invoice_email, 'phone', c.phone, 'website', c.website, 'logo_path', c.logo_path,
     'region_code', c.region_code, 'status', c.status, 'verified_at', c.verified_at,
     'offered_types', to_jsonb(c.offered_types), 'can_issue_certificate', c.can_issue_certificate, 'ports_text', c.ports_text,
     'can_edit', u.is_admin, 'is_office', u.is_office,
     'regions', (select jsonb_agg(jsonb_build_object('code', code, 'name', name) order by sort) from sa_regions),
     'locations', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'city', l.city, 'country', l.country,
                   'region_code', l.region_code, 'region_name', r.name, 'ports_text', l.ports_text, 'phone', l.phone, 'email', l.email,
                   'is_main', l.is_main,
                   'ports', coalesce((select jsonb_agg(jsonb_build_object('id', h.id, 'name', h.naam, 'country', h.land_code, 'unlocode', h.unlocode) order by h.naam)
                                      from surveyor_location_ports lp join havens h on h.id = lp.haven_id where lp.location_id = l.id), '[]'::jsonb),
                   'surveyors', (select count(*) from surveyor_company_user_locations ul join surveyor_company_users m on m.user_id = ul.user_id
                                 where ul.location_id = l.id and m.is_surveyor and m.status = 'active'))
                   order by l.is_main desc, l.name)
                 from surveyor_company_locations l left join sa_regions r on r.code = l.region_code
                 where l.company_id = c.id and l.archived_at is null), '[]'::jsonb),
     'team', (select jsonb_agg(jsonb_build_object('user_id', m.user_id, 'full_name', m.full_name, 'email', m.email, 'is_office', m.is_office,
                 'is_surveyor', m.is_surveyor, 'is_admin', m.is_admin, 'status', m.status,
                 'location_ids', coalesce((select jsonb_agg(ul.location_id) from surveyor_company_user_locations ul
                                   join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                                   where ul.user_id = m.user_id), '[]'::jsonb),
                 'manager_location_ids', coalesce((select jsonb_agg(ul.location_id) from surveyor_company_user_locations ul
                                   join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                                   where ul.user_id = m.user_id and ul.is_manager), '[]'::jsonb),
                 'manager_location_names', coalesce((select string_agg(l.name, ', ' order by l.name) from surveyor_company_user_locations ul
                                   join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                                   where ul.user_id = m.user_id and ul.is_manager), ''),
                 'location_names', coalesce((select string_agg(l.name, ', ' order by l.is_main desc, l.name) from surveyor_company_user_locations ul
                                   join surveyor_company_locations l on l.id = ul.location_id and l.archived_at is null
                                   where ul.user_id = m.user_id), ''))
                 order by m.created_at)
              from surveyor_company_users m where m.company_id = c.id))
  from surveyor_company_users u join surveyor_companies c on c.id = u.company_id
  where u.user_id = auth.uid()
$function$;

