create or replace function public.sa_ensure_surveyor_row(p_user uuid)
returns uuid language plpgsql security definer set search_path to 'public' as $$
declare u surveyor_company_users; c surveyor_companies; v_id uuid;
begin
  select * into u from surveyor_company_users where user_id = p_user for update;
  if u.user_id is null then return null; end if;
  if u.surveyor_id is not null and exists (select 1 from surveyors where id = u.surveyor_id) then return u.surveyor_id; end if;
  select * into c from surveyor_companies where id = u.company_id;
  select id into v_id from surveyors
   where lower(trim(email)) = lower(trim(u.email)) and (company_id is null or company_id = u.company_id)
   order by (company_id = u.company_id) desc nulls last, created_at limit 1;
  if v_id is null then
    insert into surveyors (name, company, email, company_id, trial_credits_remaining)
    values (coalesce(nullif(trim(u.full_name),''), u.email), c.name, lower(trim(u.email)), u.company_id, 0)
    returning id into v_id;
  else
    update surveyors set company_id = u.company_id, company = coalesce(company, c.name) where id = v_id and company_id is null;
  end if;
  update surveyor_company_users set surveyor_id = v_id, updated_at = now() where user_id = p_user;
  return v_id;
end $$;

create or replace function public.sa_job_survey_ensure(p_job uuid)
returns uuid language plpgsql security definer set search_path to 'public' as $$
declare j surveyor_jobs; v_sid uuid; v_svr uuid; v_name text; v_place text;
begin
  select * into j from surveyor_jobs where id = p_job for update;
  if j.id is null then return null; end if;
  if j.survey_id is not null and exists (select 1 from surveys where id = j.survey_id) then return j.survey_id; end if;
  v_svr := coalesce(j.assigned_surveyor_id, case when j.assigned_user_id is not null then sa_ensure_surveyor_row(j.assigned_user_id) end);
  if j.assigned_surveyor_id is distinct from v_svr then update surveyor_jobs set assigned_surveyor_id = v_svr where id = j.id; end if;
  select name into v_name from surveyors where id = v_svr;
  select concat_ws(', ', nullif(coalesce(h.naam, j.port_text),''), nullif(j.berth_or_terminal,'')) into v_place
    from (select 1) x left join havens h on h.id = j.haven_id;
  insert into surveys (gbqs_reference, order_id, survey_type, vessel_name, imo_number, place_of_survey, po_number_client_ref,
                       surveyor_id, bunker_surveyor, status, self_reported, surveyor_job_id)
  values (j.reference, null, j.survey_type, j.vessel_name, j.imo_number, nullif(v_place,''), j.client_reference,
          v_svr, v_name, 'dispatched', true, j.id)
  returning id into v_sid;
  update surveyor_jobs set survey_id = v_sid, updated_at = now() where id = j.id;
  return v_sid;
end $$;

create or replace function public.sa_job_send_link(p_job uuid, p_rotate boolean default false, p_by text default null)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare j surveyor_jobs; c surveyor_companies; sc surveyor_clients; v_sid uuid; r jsonb; fj form_jobs; v_port text;
begin
  select * into j from surveyor_jobs where id = p_job;
  if j.id is null then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Job not found.'); end if;
  if j.status not in ('draft','open','in_progress') then
    return jsonb_build_object('ok', false, 'code', 'job_closed', 'message', 'This job is no longer open.');
  end if;
  v_sid := sa_job_survey_ensure(j.id);
  r := gbqs_form_job_create(v_sid, 'surveyor', p_by, p_rotate);
  if not coalesce((r->>'ok')::boolean, false) then return r - 'token' - 'url'; end if;
  if r->>'token' is null then
    return (r - 'token' - 'url') || jsonb_build_object('mailed', false, 'code', 'job_exists', 'message', 'The link was already sent.');
  end if;
  select * into fj from form_jobs where id = (r->>'job_id')::uuid;
  if fj.surveyor_email is null then
    return (r - 'token' - 'url') || jsonb_build_object('ok', false, 'mailed', false, 'code', 'no_email', 'message', 'No e-mail address for this surveyor.');
  end if;
  select * into c from surveyor_companies where id = j.company_id;
  select * into sc from surveyor_clients where id = j.surveyor_client_id;
  select concat_ws(', ', nullif(coalesce(h.naam, j.port_text),''), nullif(j.berth_or_terminal,'')) into v_port
    from (select 1) x left join havens h on h.id = j.haven_id;
  begin
    perform gbqs_send_mail(fj.surveyor_email,
      'Survey form // ' || coalesce(j.vessel_name, '') || ' // ' || j.reference,
      gbqs_mail_wrap('SURVEY FORM',
        '<p style="margin:0 0 14px;">Dear surveyor,</p>'
        || '<p style="margin:0 0 14px;">' || gbqs_h(coalesce(c.name, 'Your office')) || ' has assigned you a survey. Use the button below to open the survey form in the GlobalBQS forms app.'
        || case when coalesce((r->>'rotated')::boolean, false) then ' <strong>This link replaces any earlier link for this job.</strong>' else '' end || '</p>'
        || '<table width="100%" cellpadding="0" cellspacing="0" style="background:#f5f8fc;border:1px solid #e2e7f2;border-radius:8px;padding:10px 18px;margin:0 0 20px;">'
        || gbqs_mail_row('JOB', '<span style="font-family:Courier New,monospace;color:#2a8fc4;">' || gbqs_h(j.reference) || '</span>')
        || gbqs_mail_row('CLIENT', gbqs_h(coalesce(sc.name, '-')))
        || gbqs_mail_row('VESSEL', gbqs_h(coalesce(j.vessel_name, '-') || coalesce(' (IMO ' || j.imo_number || ')', '')))
        || gbqs_mail_row('SURVEY', gbqs_h(coalesce((select description from survey_types_config where name = j.survey_type), j.survey_type)))
        || gbqs_mail_row('PORT', gbqs_h(coalesce(nullif(v_port,''), '-')))
        || gbqs_mail_row('ETA (LOCAL)', gbqs_h(coalesce(to_char(j.eta at time zone 'UTC', 'DD Mon YYYY HH24:MI'), '-')))
        || '</table>'
        || '<p style="margin:0 0 18px;">' || gbqs_mail_btn(r->>'url', 'Open survey form') || '</p>'
        || '<p style="margin:0 0 8px;"><strong>How it works</strong></p>'
        || '<ol style="margin:0 0 14px;padding-left:20px;">'
        || '<li>Open the link on the phone or tablet you will use on board and add the app to your home screen.</li>'
        || '<li>Sign in with the 6-digit code that we send to this e-mail address (once per device).</li>'
        || '<li>The form works offline; your entries are saved on the device and synchronised whenever you are online.</li>'
        || '<li>Submit when finished. Photos and signatures are uploaded automatically.</li></ol>'
        || '<p style="margin:0 0 14px;">You can also open the form from <strong>My jobs</strong> in the GlobalBQS portal.</p>'
        || '<p style="margin:0 0 14px;color:#5c6b85;font-size:12px;">This link is personal. Please do not forward it.</p>'));
  exception when others then
    return (r - 'token' - 'url') || jsonb_build_object('mailed', false, 'code', 'mail_failed', 'message', 'Link created, but the e-mail could not be sent.');
  end;
  return (r - 'token' - 'url') || jsonb_build_object('mailed', true, 'message', 'Link sent to ' || (r->>'surveyor_email_masked') || '.');
end $$;

create or replace function public.sa_portal_job_form_url(p_id uuid)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare j surveyor_jobs; v_sid uuid; v_fj uuid; v_url text; r jsonb;
begin
  select * into j from surveyor_jobs where id = p_id and company_id = sa_my_company_id();
  if j.id is null then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Job not found.'); end if;
  if j.assigned_user_id is distinct from auth.uid() then
    return jsonb_build_object('ok', false, 'code', 'not_assigned', 'message', 'Only the attending surveyor can open the form. Use "Resend link" to e-mail it.');
  end if;
  if j.status not in ('draft','open','in_progress') then
    return jsonb_build_object('ok', false, 'code', 'job_closed', 'message', 'This job is no longer open in the app.');
  end if;
  v_sid := sa_job_survey_ensure(j.id);
  select form_job_id into v_fj from surveys where id = v_sid;
  if v_fj is null or not exists (select 1 from form_jobs where id = v_fj and status in ('open','in_progress')) then
    r := gbqs_form_job_create(v_sid, 'surveyor', (select email from surveyor_company_users where user_id = auth.uid()), false);
    if not coalesce((r->>'ok')::boolean, false) then return r - 'token' - 'url'; end if;
    v_url := r->>'url';
    if v_url is null then v_url := gbqs_form_job_url((r->>'job_id')::uuid); end if;
  else
    v_url := gbqs_form_job_url(v_fj);
  end if;
  if v_url is null then return jsonb_build_object('ok', false, 'code', 'no_link', 'message', 'The link could not be created. Please try again.'); end if;
  return jsonb_build_object('ok', true, 'url', v_url);
end $$;

create or replace function public.sa_portal_job_resend_link(p_id uuid)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare j surveyor_jobs; v_has boolean;
begin
  select * into j from surveyor_jobs where id = p_id and company_id = sa_my_company_id();
  if j.id is null then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Job not found.'); end if;
  if not (j.assigned_user_id = auth.uid() or sa_can_manage_location(j.location_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'You cannot send the link for this job.');
  end if;
  select exists (select 1 from surveys s join form_jobs f on f.id = s.form_job_id
                  where s.id = j.survey_id and f.status in ('open','in_progress')) into v_has;
  return sa_job_send_link(j.id, v_has, (select email from surveyor_company_users where user_id = auth.uid()));
end $$;

do $do$
declare v_def text;
begin
  v_def := pg_get_functiondef('public.sa_portal_create_job(jsonb)'::regprocedure);
  if position('sa_job_send_link' in v_def) = 0 then
    v_def := replace(v_def,
      $a$  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'reference', v_ref, 'message', 'Job ' || v_ref || ' created.');$a$,
      $b$  returning id into v_id;
  begin
    v_link := sa_job_send_link(v_id, false, (select email from surveyor_company_users where user_id = auth.uid()));
  exception when others then
    v_link := jsonb_build_object('ok', false, 'mailed', false, 'message', 'The link could not be sent; use "Resend link" in My jobs.');
  end;
  return jsonb_build_object('ok', true, 'id', v_id, 'reference', v_ref, 'mailed', coalesce((v_link->>'mailed')::boolean, false),
    'message', 'Job ' || v_ref || ' created.' || case when coalesce((v_link->>'mailed')::boolean, false)
      then ' The survey form link was e-mailed to the surveyor.' else ' ' || coalesce(v_link->>'message', '') end);$b$);
    v_def := replace(v_def, 'v_vid uuid; v_ref text; v_id uuid; v_sid uuid;', 'v_vid uuid; v_ref text; v_id uuid; v_sid uuid; v_link jsonb;');
    if position('sa_job_send_link' in v_def) = 0 or position('v_link jsonb' in v_def) = 0 then
      raise exception 'sa_portal_create_job: patch niet toegepast';
    end if;
    execute v_def;
  end if;
end $do$;

create or replace function public.sa_portal_cancel_job(p_id uuid)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare v_j surveyor_jobs%rowtype; v_fj uuid;
begin
  select * into v_j from surveyor_jobs where id = p_id and company_id = sa_my_company_id();
  if not found then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Job not found.'); end if;
  if not sa_can_manage_location(v_j.location_id) then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only the office or the location manager can cancel this job.');
  end if;
  if v_j.status not in ('draft','open') then
    return jsonb_build_object('ok', false, 'code', 'not_open', 'message', 'This job has started and can no longer be cancelled here.');
  end if;
  update surveyor_jobs set status = 'cancelled', updated_at = now() where id = p_id;
  select form_job_id into v_fj from surveys where id = v_j.survey_id;
  if v_fj is not null then perform gbqs_form_job_cancel(v_fj, 'surveyor portal'); end if;
  return jsonb_build_object('ok', true, 'message', 'Job ' || v_j.reference || ' cancelled.');
end $$;

create or replace function public.sa_trg_form_job_status()
returns trigger language plpgsql security definer set search_path to 'public' as $$
begin
  if new.status = 'in_progress' and old.status is distinct from 'in_progress' then
    update surveyor_jobs sj set status = 'in_progress', updated_at = now()
      from surveys s where s.id = new.survey_id and sj.id = s.surveyor_job_id and sj.status = 'open';
  end if;
  return new;
end $$;
drop trigger if exists trg_sa_form_job_status on public.form_jobs;
create trigger trg_sa_form_job_status after update of status on public.form_jobs
  for each row execute function sa_trg_form_job_status();

create or replace function public.sa_trg_survey_status()
returns trigger language plpgsql security definer set search_path to 'public' as $$
begin
  if new.surveyor_job_id is null then return new; end if;
  if new.status = 'submitted' and old.status is distinct from 'submitted' then
    update surveyor_jobs set status = 'submitted', updated_at = now()
     where id = new.surveyor_job_id and status in ('draft','open','in_progress');
    begin perform sa_credit_use(new.surveyor_job_id, 'forms app');
    exception when others then raise warning 'sa_credit_use failed for job %: %', new.surveyor_job_id, sqlerrm; end;
  elsif new.status in ('issued','invoiced','closed') and old.status not in ('issued','invoiced','closed') then
    update surveyor_jobs set status = 'issued', updated_at = now() where id = new.surveyor_job_id and status <> 'issued';
  end if;
  return new;
end $$;
drop trigger if exists trg_sa_survey_status on public.surveys;
create trigger trg_sa_survey_status after update of status on public.surveys
  for each row execute function sa_trg_survey_status();

do $do$ begin
  if to_regprocedure('public.gbqs_form_prefill_core(uuid)') is null then
    alter function public.gbqs_form_prefill(uuid) rename to gbqs_form_prefill_core;
  end if;
  if to_regprocedure('public.gbqs_form_job_open_core(text,text)') is null then
    alter function public.gbqs_form_job_open(text, text) rename to gbqs_form_job_open_core;
  end if;
end $do$;

create or replace function public.sa_form_job_extra(p_survey_id uuid)
returns jsonb language sql stable security definer set search_path to 'public' as $$
  select case when j.id is null then null else jsonb_build_object(
    'reference', j.reference, 'company', c.name, 'client', sc.name, 'client_reference', j.client_reference,
    'port_name', coalesce(h.naam, j.port_text), 'berth', j.berth_or_terminal, 'haven_id', h.id, 'unlocode', h.unlocode, 'country_code', h.land_code,
    'eta', j.eta, 'etb', j.etb, 'etc', j.etc) end
  from surveys s
  left join surveyor_jobs j on j.id = s.surveyor_job_id
  left join surveyor_companies c on c.id = j.company_id
  left join surveyor_clients sc on sc.id = j.surveyor_client_id
  left join havens h on h.id = j.haven_id
  where s.id = p_survey_id
$$;

create or replace function public.gbqs_form_prefill(p_job_id uuid)
returns jsonb language plpgsql stable security definer set search_path to 'public' as $$
declare r jsonb; x jsonb; v_place text;
begin
  r := gbqs_form_prefill_core(p_job_id);
  if r is null then return r; end if;
  x := sa_form_job_extra((r #>> '{survey,survey_id}')::uuid);
  if x is null then return r; end if;
  v_place := concat_ws(', ', nullif(x->>'port_name',''), nullif(x->>'berth',''));
  return r
    || jsonb_build_object('client', coalesce(r->'client', '{}'::jsonb) || jsonb_build_object('name', x->>'client'))
    || jsonb_build_object('survey', coalesce(r->'survey', '{}'::jsonb) || jsonb_build_object('po_number', coalesce(r #>> '{survey,po_number}', x->>'client_reference'), 'self_reported', true, 'issued_by', x->>'company'))
    || jsonb_build_object('port', coalesce(r->'port', '{}'::jsonb) || jsonb_build_object('name', x->>'port_name', 'berth', x->>'berth', 'place', v_place,
                                   'haven_id', x->>'haven_id', 'unlocode', x->>'unlocode', 'country_code', x->>'country_code'))
    || jsonb_build_object('schedule', jsonb_build_object(
         'eta', case when x->>'eta' is null then null else gbqs_fmt_dt(x->>'eta') end,
         'etb', case when x->>'etb' is null then null else gbqs_fmt_dt(x->>'etb') end,
         'etc', case when x->>'etc' is null then null else gbqs_fmt_dt(x->>'etc') end,
         'eta_local', to_char((x->>'eta')::timestamptz at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI'),
         'etb_local', to_char((x->>'etb')::timestamptz at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI'),
         'etc_local', to_char((x->>'etc')::timestamptz at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI')))
    || jsonb_build_object('surveyor', coalesce(r->'surveyor', '{}'::jsonb) || jsonb_build_object('company', coalesce(r #>> '{surveyor,company}', x->>'company')));
end $$;

create or replace function public.gbqs_form_job_open(p_token text, p_session_token text default null)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare r jsonb; x jsonb;
begin
  r := gbqs_form_job_open_core(p_token, p_session_token);
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  x := sa_form_job_extra((select survey_id from form_jobs where id = (r #>> '{job,id}')::uuid));
  if x is null then return r; end if;
  return r || jsonb_build_object('summary', coalesce(r->'summary', '{}'::jsonb) || jsonb_build_object(
    'port', concat_ws(', ', nullif(x->>'port_name',''), nullif(x->>'berth','')),
    'eta', case when x->>'eta' is null then null else to_char((x->>'eta')::timestamptz at time zone 'UTC', 'DD Mon YYYY HH24:MI') || ' LT' end,
    'client', x->>'client', 'issued_by', x->>'company'));
end $$;

create or replace function public.sa_portal_jobs(p_scope text default 'open')
returns jsonb language sql stable security definer set search_path to 'public' as $$
  select coalesce(jsonb_agg(x order by (x->>'sort_at') nulls last), '[]'::jsonb) from (
    select jsonb_build_object('id', j.id, 'reference', j.reference, 'status', j.status, 'on_hold_reason', j.on_hold_reason,
      'survey_type', j.survey_type, 'eta', j.eta, 'etb', j.etb, 'etc', j.etc, 'client_reference', j.client_reference,
      'vessel', coalesce(v.display_name, v.vessel_name, j.vessel_name), 'imo', j.imo_number,
      'port', coalesce(h.naam, j.port_text), 'country', h.land_code, 'berth', j.berth_or_terminal,
      'client', sc.name, 'location', l.name, 'location_id', j.location_id,
      'surveyor', coalesce(nullif(u.full_name,''), u.email), 'assigned_user_id', j.assigned_user_id,
      'is_mine', j.assigned_user_id = auth.uid(), 'credit_used', j.credit_used, 'source', case when j.gbqs_order_id is null then 'own' else 'gbqs' end,
      'can_cancel', j.status in ('draft','open') and sa_can_manage_location(j.location_id),
      'can_open_form', j.status in ('draft','open','in_progress') and j.assigned_user_id = auth.uid(),
      'can_resend_link', j.status in ('draft','open','in_progress') and (j.assigned_user_id = auth.uid() or sa_can_manage_location(j.location_id)),
      'form_status', fj.status, 'form_last_sync_at', fj.last_sync_at,
      'created_at', j.created_at, 'updated_at', j.updated_at,
      'sort_at', case when p_scope = 'done' then to_char(now() - j.updated_at, 'YYYYMMDDHH24MISS') else to_char(j.eta, 'YYYYMMDDHH24MI') end) x
    from surveyor_jobs j
    left join vessels v on v.id = j.vessel_id
    left join havens h on h.id = j.haven_id
    left join surveyor_clients sc on sc.id = j.surveyor_client_id
    left join surveyor_company_locations l on l.id = j.location_id
    left join surveyor_company_users u on u.user_id = j.assigned_user_id
    left join surveys s on s.id = j.survey_id
    left join form_jobs fj on fj.id = s.form_job_id
    where j.company_id = sa_my_company_id() and sa_job_visible(j.company_id, j.assigned_user_id, j.location_id)
      and (p_scope = 'all'
           or (p_scope = 'open' and j.status in ('draft','open','in_progress','on_hold','submitted'))
           or (p_scope = 'done' and j.status in ('issued','cancelled','merged')))
    limit 300) s
$$;

