grant execute on function public.sa_ensure_surveyor_row(uuid), public.sa_job_survey_ensure(uuid),
  public.sa_job_send_link(uuid, boolean, text), public.sa_form_job_extra(uuid),
  public.gbqs_form_prefill(uuid), public.gbqs_form_prefill_core(uuid),
