-- surveyor_access_15_own_report (A5, 09-11-2026) - DEMO first, production at go-live 1.1.0
-- Own job of a surveyor company: draft to the surveyor (approve in the portal, My jobs),
-- report with the surveyor's branding, mail to the surveyor's client with a view link.

-- 1. view links for the report mail (token -> always a fresh short-lived signed URL via edge function sa-report)
create table if not exists public.sa_report_links (
  id uuid primary key default gen_random_uuid(),
  token text not null unique default encode(extensions.gen_random_bytes(18), 'hex'),
  survey_id uuid not null references public.surveys(id) on delete cascade,
  job_id uuid references public.surveyor_jobs(id) on delete set null,
  company_id uuid references public.surveyor_companies(id) on delete set null,
  report_path text not null,
  revision int,
  created_at timestamptz not null default now(),
  open_count int not null default 0,
  first_opened_at timestamptz,
  last_opened_at timestamptz,
  revoked_at timestamptz
);
create index if not exists sa_report_links_survey_idx on public.sa_report_links(survey_id);
alter table public.sa_report_links enable row level security;
revoke all on public.sa_report_links from anon, authenticated;

-- 2. log of the mails to the surveyor's client (also the only record on the demo, where mail is not sent)
create table if not exists public.sa_report_mails (
  id uuid primary key default gen_random_uuid(),
  survey_id uuid not null references public.surveys(id) on delete cascade,
  job_id uuid,
  link_id uuid references public.sa_report_links(id) on delete set null,
  mail_to text, mail_cc text, reply_to text, subject text, html text,
  status text not null default 'queued', error text,
  created_at timestamptz not null default now()
);
create index if not exists sa_report_mails_survey_idx on public.sa_report_mails(survey_id);
alter table public.sa_report_mails enable row level security;
revoke all on public.sa_report_mails from anon, authenticated;

