-- 3. e-mail address of the attending surveyor of an own job
create or replace function public.sa_job_surveyor_email(p_job uuid)
returns text language sql stable security definer set search_path to 'public' as $$
  select coalesce(
    (select nullif(trim(u.email),'') from surveyor_jobs j join surveyor_company_users u on u.user_id = j.assigned_user_id where j.id = p_job limit 1),
    (select nullif(trim(fj.surveyor_email),'') from surveyor_jobs j join surveys s on s.id = j.survey_id join form_jobs fj on fj.id = s.form_job_id where j.id = p_job),
    (select nullif(trim(sv.email),'') from surveyor_jobs j join surveyors sv on sv.id = j.assigned_surveyor_id where j.id = p_job))
$$;

-- 4. draft start: own jobs have no survey_assignment; on hold (no credits) = no draft yet
create or replace function public.gbqs_draft_start(p_survey_id uuid)
 returns uuid language plpgsql security definer set search_path to 'public' as $function$
declare a survey_assignments; v_id uuid; v_job surveyor_jobs; v_to text;
begin
  if coalesce((select value from system_settings where key = 'draft_flow_enabled'), 'false') <> 'true' then return null; end if;
  select j.* into v_job from surveys s join surveyor_jobs j on j.id = s.surveyor_job_id where s.id = p_survey_id;
  if v_job.id is not null then
    -- A5: own job of a surveyor company
    if v_job.status <> 'submitted' or not coalesce(v_job.credit_used, false) then return null; end if;
    v_to := sa_job_surveyor_email(v_job.id);
    if v_to is null then return null; end if;
    update survey_drafts set status = 'superseded' where survey_id = p_survey_id and status = 'pending';
    insert into survey_drafts(survey_id, assignment_id, send_to) values (p_survey_id, null, v_to) returning id into v_id;
    update surveys set draft_state = 'awaiting_surveyor' where id = p_survey_id;
    perform gbqs_invoke_edge('survey-draft', jsonb_build_object('action', 'send', 'draft_id', v_id));
    return v_id;
  end if;
  a := gbqs_survey_assignment(p_survey_id);
  if a.id is null then return null; end if;
  update survey_drafts set status = 'superseded' where survey_id = p_survey_id and status = 'pending';
  insert into survey_drafts(survey_id, assignment_id, send_to)
  values (p_survey_id, a.id, coalesce(a.attending_email, a.surveyor_email)) returning id into v_id;
  update surveys set draft_state = 'awaiting_surveyor' where id = p_survey_id;
  perform gbqs_invoke_edge('survey-draft', jsonb_build_object('action', 'send', 'draft_id', v_id));
  return v_id;
end $function$;

-- 5. draft mail: own job -> mail to the surveyor, approve in the portal (My jobs)
create or replace function public.sa_draft_mail(p_draft_id uuid, p_url text)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare d survey_drafts; s surveys; j surveyor_jobs; c surveyor_companies; sc surveyor_clients; lbl text; v_port text; v_portal text;
begin
  select * into d from survey_drafts where id = p_draft_id;
  select * into s from surveys where id = d.survey_id;
  select * into j from surveyor_jobs where id = s.surveyor_job_id;
  select * into c from surveyor_companies where id = j.company_id;
  select * into sc from surveyor_clients where id = j.surveyor_client_id;
  select coalesce(description, s.survey_type) into lbl from survey_types_config where name = s.survey_type;
  select concat_ws(', ', nullif(coalesce(h.naam, j.port_text),''), nullif(j.berth_or_terminal,'')) into v_port
    from (select 1) x left join havens h on h.id = j.haven_id;
  v_portal := rtrim(coalesce((select value from system_settings where key = 'portal_url'), 'https://portal.globalbqs.com'), '/') || '/surveyor/jobs';
  perform gbqs_send_mail(d.send_to,
    'DRAFT report - please check // ' || coalesce(lbl,'') || ' // ' || coalesce(j.vessel_name, s.vessel_name, '') || ' // ' || j.reference,
    gbqs_mail_wrap('DRAFT REPORT',
      '<p style="margin:0 0 6px;font-size:18px;font-weight:bold;">Please check the draft report</p>'
    ||'<p style="margin:0 0 18px;">Your survey form has been received. Please check the draft report, preferably while you are still on board, so that any correction can still be signed by the Master / Chief Engineer.</p>'
    ||'<table width="100%" cellpadding="0" cellspacing="0" style="background:#f5f8fc;border:1px solid #e2e7f2;border-radius:8px;padding:10px 18px;margin:0 0 20px;">'
    || gbqs_mail_row('JOB', '<span style="font-family:Courier New,monospace;color:#2a8fc4;">' || gbqs_h(j.reference) || '</span>')
    || gbqs_mail_row('CLIENT', gbqs_h(coalesce(sc.name, '-')))
    || gbqs_mail_row('VESSEL', gbqs_h(coalesce(j.vessel_name, '-') || coalesce(' (IMO ' || j.imo_number || ')', '')))
    || gbqs_mail_row('SURVEY', gbqs_h(coalesce(lbl, '-')))
    || gbqs_mail_row('PORT', gbqs_h(coalesce(nullif(v_port,''), '-')))
    ||'</table>'
    ||'<p style="margin:0 0 18px;">'||gbqs_mail_btn(p_url, 'View draft report (PDF)', 'secondary')||gbqs_mail_btn(v_portal, 'Approve in My jobs', 'primary')||'</p>'
    ||'<p style="margin:0 0 10px;">In <strong>My jobs</strong> you can <strong>approve</strong> the report – it is then issued and e-mailed to '||gbqs_h(coalesce(sc.name, 'your client'))||' – or <strong>request a correction</strong>: the form opens again in the app, you complete it again in full and have the Master / Chief Engineer sign again.</p>'
    ||'<p style="margin:0;color:#5c6b85;font-size:12px;line-height:18px;">The draft link is valid for 7 days. Please do not forward this e-mail.</p>'));
  return jsonb_build_object('ok', true, 'own_job', true);
end $function$;

create or replace function public.gbqs_draft_mail(p_draft_id uuid, p_url text, p_path text)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare d survey_drafts; a survey_assignments; s surveys; lbl text;
begin
  select * into d from survey_drafts where id = p_draft_id;
  if d.id is null or d.status <> 'pending' then return jsonb_build_object('ok', false, 'message', 'draft not pending'); end if;
  select * into s from surveys where id = d.survey_id;
  if s.surveyor_job_id is not null then
    update survey_drafts set pdf_path = p_path, sent_at = now() where id = d.id;
    return sa_draft_mail(d.id, p_url);
  end if;
  select * into a from survey_assignments where id = d.assignment_id;
  select coalesce(description, s.survey_type) into lbl from survey_types_config where name = s.survey_type;
  update survey_drafts set pdf_path = p_path, sent_at = now() where id = d.id;
  perform gbqs_send_mail(d.send_to, 'GlobalBQS: DRAFT report - please check // ' || coalesce(lbl,'') || ' // ' || coalesce(a.payload->>'vessel_name', s.vessel_name, '') || ' // ' || s.gbqs_reference,
    gbqs_mail_wrap('DRAFT REPORT',
      '<p style="margin:0 0 6px;font-size:18px;font-weight:bold;">Please check the draft report</p>'
    ||'<p style="margin:0 0 18px;">We have received the survey form for the survey below. Please check the draft report while you are still on board, so that any correction can still be signed by the Master / Chief Engineer.</p>'
    ||gbqs_assignment_details(a)
    ||'<p style="margin:0 0 18px;">'||gbqs_mail_btn(p_url, 'View draft report (PDF)', 'secondary')||'</p>'
    ||'<p style="margin:0 0 6px;font-weight:bold;">Is everything correct?</p>'
    ||'<p style="margin:0 0 18px;">'||gbqs_mail_btn(gbqs_draft_link(d.token,'d_approve'), 'Approve and issue report', 'primary')||'</p>'
    ||'<p style="margin:0 0 6px;font-weight:bold;">Does something need to be changed?</p>'
    ||'<p style="margin:0 0 6px;">'||gbqs_mail_btn(gbqs_draft_link(d.token,'d_correct'), 'Request correction', 'danger')||'</p>'
    ||'<p style="margin:0 0 18px;color:#5c6b85;font-size:12px;line-height:18px;">You will then complete the survey form again in full and have the Master / Chief Engineer sign again. The new submission replaces this draft.</p>'
    ||'<p style="margin:0 0 10px;color:#5c6b85;font-size:12px;line-height:18px;">Your confirmation is required before the report can be issued. If we have not received your response within 6 hours, we will send you a reminder; after that, GlobalBQS operations may issue the report after their own check. The draft link is valid for 7 days. Please do not forward this e-mail.</p>'
    ||'<p style="margin:0;">Please quote reference <strong>'||gbqs_h(s.gbqs_reference)||'</strong> in all correspondence.</p>'));
  return jsonb_build_object('ok', true);
end $function$;

-- 6. reminders (GBQS route) skip own jobs: they mention GlobalBQS operations
do $$ declare v text;
begin
  v := pg_get_functiondef('public.gbqs_draft_reminders'::regproc);
  if position('sv.surveyor_job_id is null' in v) = 0 then
