-- 7. credits bought for a job on hold -> start the draft now
create or replace function public.sa_trg_job_released()
 returns trigger language plpgsql security definer set search_path to 'public' as $function$
begin
  if new.status = 'submitted' and old.status = 'on_hold' and new.survey_id is not null
     and exists (select 1 from surveys where id = new.survey_id and status = 'submitted')
     and not gbqs_draft_pending(new.survey_id) then
    perform gbqs_draft_start(new.survey_id);
  end if;
  return new;
exception when others then
  raise warning 'sa_trg_job_released: %', sqlerrm;
  return new;
end $function$;
drop trigger if exists trg_sa_job_released on public.surveyor_jobs;
create trigger trg_sa_job_released after update of status on public.surveyor_jobs
  for each row execute function public.sa_trg_job_released();

-- 8. portal: approve the draft / request a correction (attending surveyor or office of that location)
create or replace function public.sa_portal_job_draft_decide(p_id uuid, p_action text, p_note text default null)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare j surveyor_jobs; s surveys; d survey_drafts; v_me text;
begin
  select * into j from surveyor_jobs where id = p_id and company_id = sa_my_company_id();
  if j.id is null then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Job not found.'); end if;
  if not (j.assigned_user_id = auth.uid() or sa_can_manage_location(j.location_id)) then
    return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'Only the attending surveyor or the office can decide on the draft.');
  end if;
  select * into s from surveys where id = j.survey_id;
  select * into d from survey_drafts where survey_id = s.id order by created_at desc limit 1;
  if d.id is null or d.status <> 'pending' or d.sent_at is null or s.status <> 'submitted' then
    return jsonb_build_object('ok', false, 'code', 'no_draft', 'message', 'There is no draft waiting for approval.');
  end if;
  v_me := (select email from surveyor_company_users where user_id = auth.uid() limit 1);
  if p_action = 'approve' then
    update survey_drafts set status = 'approved', decided_at = now(), override_by = v_me where id = d.id;
    update surveys set draft_state = 'surveyor_approved' where id = s.id;
    perform gbqs_invoke_edge('survey-draft', jsonb_build_object('action', 'issue', 'draft_id', d.id));
    return jsonb_build_object('ok', true, 'message', 'Approved. The report is being issued and e-mailed to your client.');
  elsif p_action = 'correct' then
    update survey_drafts set status = 'correction_requested', correction_type = 'full', decided_at = now(),
           correction_note = nullif(left(trim(coalesce(p_note,'')), 1000), ''), override_by = v_me where id = d.id;
    update surveys set status = 'confirmed', submitted_at = null, draft_state = 'correction_requested', correction_count = coalesce(correction_count, 0) + 1
     where id = s.id and status = 'submitted';
    update surveyor_jobs set status = 'in_progress', updated_at = now() where id = j.id and status = 'submitted';
    return jsonb_build_object('ok', true, 'message', 'Correction requested. The form is open again in the app: complete it in full and have the Master / Chief Engineer sign again.');
  end if;
  return jsonb_build_object('ok', false, 'code', 'bad_action', 'message', 'Unknown action.');
end $function$;
revoke all on function public.sa_portal_job_draft_decide(uuid, text, text) from public, anon;
grant execute on function public.sa_portal_job_draft_decide(uuid, text, text) to authenticated;

-- 9. portal: which file may this user open (used by edge function sa-report with the user's JWT)
create or replace function public.sa_portal_job_file(p_id uuid, p_kind text)
 returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare j surveyor_jobs; v_path text; v_name text;
begin
  select * into j from surveyor_jobs where id = p_id and company_id = sa_my_company_id()
     and sa_job_visible(company_id, assigned_user_id, location_id);
  if j.id is null or j.survey_id is null then return jsonb_build_object('ok', false, 'message', 'Job not found.'); end if;
  if p_kind = 'draft' then
    select pdf_path into v_path from survey_drafts where survey_id = j.survey_id and pdf_path is not null order by created_at desc limit 1;
    v_name := j.reference || '_draft.pdf';
  elsif p_kind = 'report' then
    select file_id, file_name into v_path, v_name from survey_documents where survey_id = j.survey_id and section = 'report' order by uploaded_at desc limit 1;
  end if;
  if v_path is null then return jsonb_build_object('ok', false, 'message', 'File not available yet.'); end if;
  return jsonb_build_object('ok', true, 'path', v_path, 'file_name', coalesce(v_name, j.reference || '.pdf'));
end $function$;
revoke all on function public.sa_portal_job_file(uuid, text) from public, anon;
grant execute on function public.sa_portal_job_file(uuid, text) to authenticated;

