create or replace function public.sa_report_issued(p_survey_id uuid, p_path text, p_revision int default null)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare s surveys; j surveyor_jobs; c surveyor_companies; sc surveyor_clients; l sa_report_links; lbl text; v_port text;
  v_base text; v_view text; v_logo text; v_to text; v_cc text[]; v_cc_txt text; v_subject text; v_html text; v_mail uuid; v_err text;
begin
  select * into s from surveys where id = p_survey_id;
  select * into j from surveyor_jobs where id = s.surveyor_job_id;
  if j.id is null then return jsonb_build_object('ok', false, 'message', 'not an own job'); end if;
  select * into c from surveyor_companies where id = j.company_id;
  select * into sc from surveyor_clients where id = j.surveyor_client_id;
  select coalesce(description, s.survey_type) into lbl from survey_types_config where name = s.survey_type;
  select concat_ws(', ', nullif(coalesce(h.naam, j.port_text),''), nullif(j.berth_or_terminal,'')) into v_port
    from (select 1) x left join havens h on h.id = j.haven_id;

  update sa_report_links set revoked_at = now() where survey_id = s.id and revoked_at is null;
  insert into sa_report_links(survey_id, job_id, company_id, report_path, revision)
  values (s.id, j.id, j.company_id, p_path, p_revision) returning * into l;

  v_base := coalesce((select value from system_settings where key = 'sa_report_link_base'), '');
  v_view := v_base || '?t=' || l.token;
  v_logo := case when c.logo_path is not null then v_base || '?logo=' || l.token end;

  select array_agg(distinct lower(trim(e))) into v_cc
    from unnest(coalesce(sc.report_emails, '{}'::text[])) e where trim(e) like '%@%';
  v_to := v_cc[1];
  v_cc := v_cc[2:];
  if nullif(trim(c.office_email),'') is not null and not (lower(trim(c.office_email)) = any(coalesce(v_cc, '{}') || coalesce(v_to,''))) then
    v_cc := coalesce(v_cc, '{}') || lower(trim(c.office_email));
  end if;
  if v_to is null then v_to := nullif(lower(trim(c.office_email)),''); v_cc := array_remove(v_cc, v_to); end if;
  v_cc_txt := array_to_string(v_cc, ',');

  v_subject := case when p_revision is not null then 'Amended report (Revision ' || p_revision || ') - ' else '' end
    || coalesce(lbl, 'Survey') || ' report // ' || coalesce(j.vessel_name, s.vessel_name, '') || ' // ' || j.reference
    || coalesce(' // ' || nullif(j.client_reference,''), '');
  v_html := sa_report_mail_html(c, v_logo,
      '<p style="margin:0 0 14px;">Dear ' || gbqs_h(coalesce(nullif(sc.contact_name,''), 'Sir / Madam')) || ',</p>'
    ||'<p style="margin:0 0 14px;">' || case when p_revision is not null then 'Please find the amended report (Revision ' || p_revision || ')' else 'Please find the report' end
    || ' of the survey below, carried out by ' || gbqs_h(c.name) || ' on your behalf.</p>'
    ||'<table width="100%" cellpadding="0" cellspacing="0" style="background:#f5f8fc;border:1px solid #e2e7f2;border-radius:8px;padding:10px 18px;margin:0 0 20px;">'
    || gbqs_mail_row('VESSEL', gbqs_h(coalesce(j.vessel_name, s.vessel_name, '-') || coalesce(' (IMO ' || coalesce(j.imo_number, s.imo_number) || ')', '')))
    || gbqs_mail_row('SURVEY', gbqs_h(coalesce(lbl, '-')))
    || gbqs_mail_row('PORT', gbqs_h(coalesce(nullif(v_port,''), s.place_of_survey, '-')))
    || gbqs_mail_row('DATE', gbqs_h(coalesce(to_char(s.date_of_survey, 'DD Mon YYYY'), '-')))
    || gbqs_mail_row('REPORT', '<span style="font-family:Courier New,monospace;color:#2a8fc4;">' || gbqs_h(coalesce(s.report_number, j.reference)) || '</span>')
    || case when nullif(j.client_reference,'') is not null then gbqs_mail_row('YOUR REFERENCE', gbqs_h(j.client_reference)) else '' end
    ||'</table>'
    ||'<p style="margin:0 0 18px;">'||gbqs_mail_btn(v_view, 'View this report in GlobalBQS', 'primary')||'</p>'
    ||'<p style="margin:0 0 14px;">Questions about this survey? Simply reply to this e-mail – your reply goes to ' || gbqs_h(c.name) || '.</p>'
    ||'<p style="margin:0 0 4px;">Best regards,</p><p style="margin:0;"><strong>' || gbqs_h(c.name) || '</strong>'
    || coalesce('<br><span style="color:#5c6b85;font-size:12px;">' || gbqs_h(nullif(concat_ws(' · ', nullif(c.phone,''), nullif(c.office_email,''), nullif(c.website,'')),'')) || '</span>', '') || '</p>');

  insert into sa_report_mails(survey_id, job_id, link_id, mail_to, mail_cc, reply_to, subject, html, status)
  values (s.id, j.id, l.id, v_to, v_cc_txt, c.office_email, v_subject, v_html, case when v_to is null then 'no_recipient' else 'queued' end)
  returning id into v_mail;
  if v_to is null then
    return jsonb_build_object('ok', false, 'message', 'No e-mail address for the client or the office.', 'mail_id', v_mail, 'link', v_view);
  end if;
  begin
    perform gbqs_send_mail_ext(v_to, v_subject, v_html, v_cc_txt, coalesce(nullif(trim(c.office_email),''), 'ops@globalbqs.com'));
    update sa_report_mails set status = 'sent' where id = v_mail;
  exception when others then
    v_err := sqlerrm;
    update sa_report_mails set status = 'failed', error = left(v_err, 500) where id = v_mail;
  end;
  return jsonb_build_object('ok', v_err is null, 'mail_id', v_mail, 'to', v_to, 'cc', v_cc_txt, 'link', v_view);
end $function$;
revoke all on function public.sa_report_issued(uuid, text, int) from public, anon, authenticated;
revoke all on function public.sa_report_mail_html(surveyor_companies, text, text) from public, anon, authenticated;

-- 11. view link opened (called by edge function sa-report, service role)
create or replace function public.sa_report_link_open(p_token text, p_kind text default 'report')
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare l sa_report_links; c surveyor_companies; s surveys;
begin
  select * into l from sa_report_links where token = p_token;
  if l.id is null then return jsonb_build_object('ok', false, 'message', 'This link is not valid.'); end if;
  if p_kind = 'logo' then
    select * into c from surveyor_companies where id = l.company_id;
    return jsonb_build_object('ok', c.logo_path is not null, 'bucket', 'surveyor-logos', 'path', c.logo_path);
  end if;
  if l.revoked_at is not null then
    -- a newer version exists: send the viewer to the latest one
    select * into l from sa_report_links where survey_id = l.survey_id and revoked_at is null order by created_at desc limit 1;
    if l.id is null then return jsonb_build_object('ok', false, 'message', 'This report is no longer available.'); end if;
  end if;
  update sa_report_links set open_count = open_count + 1, first_opened_at = coalesce(first_opened_at, now()), last_opened_at = now() where id = l.id;
  select * into s from surveys where id = l.survey_id;
  return jsonb_build_object('ok', true, 'bucket', 'survey-documents', 'path', l.report_path, 'file_name', coalesce(s.report_number, s.gbqs_reference) || '.pdf');
end $function$;
revoke all on function public.sa_report_link_open(text, text) from public, anon, authenticated;

-- 12. My jobs: draft/report info
do $$ declare v text;
begin
  v := pg_get_functiondef('public.sa_portal_jobs'::regproc);
  if position('''draft_status''' in v) = 0 then
    if position('''form_status'', fj.status,' in v) = 0 then raise exception 'sa_portal_jobs: anchor not found'; end if;
    v := replace(v, '''form_status'', fj.status,',
      '''form_status'', fj.status, ''draft_status'', ld.status, ''draft_sent_at'', ld.sent_at, ''draft_state'', s.draft_state,'
      ||' ''can_review_draft'', ld.status = ''pending'' and ld.sent_at is not null and s.status = ''submitted'' and (j.assigned_user_id = auth.uid() or sa_can_manage_location(j.location_id)),'
      ||' ''has_report'', exists (select 1 from survey_documents sd where sd.survey_id = s.id and sd.section = ''report''),'
      ||' ''report_opened_at'', (select max(rl.last_opened_at) from sa_report_links rl where rl.survey_id = s.id),'
      ||' ''report_sent_to'', (select rm.mail_to from sa_report_mails rm where rm.survey_id = s.id order by rm.created_at desc limit 1),');
    v := replace(v, 'left join form_jobs fj on fj.id = s.form_job_id',
      'left join form_jobs fj on fj.id = s.form_job_id'
      ||' left join lateral (select d.status, d.sent_at from survey_drafts d where d.survey_id = s.id order by d.created_at desc limit 1) ld on true');
    execute v;
  end if;
end $$;

