-- surveyor_access_15d_draft_without_credit (09-11, besluit Richard):
-- zonder tegoed gaat het concept tóch direct naar de surveyor (controle aan boord);
-- alleen uitgeven + mail aan de klant wachten op tegoed. Goedgekeurd zonder tegoed -> automatisch uitgeven na aanvullen.
do $$ declare v text;
begin
  -- 1. draft start: own job also when on hold (no credits)
  v := pg_get_functiondef('public.gbqs_draft_start(uuid)'::regprocedure);
  if position('if v_job.status <> ''submitted'' or not coalesce(v_job.credit_used, false) then return null; end if;' in v) = 0 then
    raise exception 'gbqs_draft_start: anchor not found';
  end if;
  v := replace(v, 'if v_job.status <> ''submitted'' or not coalesce(v_job.credit_used, false) then return null; end if;',
                  'if v_job.status not in (''submitted'', ''on_hold'') then return null; end if;');
  execute v;

  -- 2. decide: approve without credits = approved, issued after credits; correction also from on_hold
  v := pg_get_functiondef('public.sa_portal_job_draft_decide(uuid,text,text)'::regprocedure);
  if position('    perform gbqs_invoke_edge(''survey-draft'', jsonb_build_object(''action'', ''issue'', ''draft_id'', d.id));' in v) = 0 then
    raise exception 'sa_portal_job_draft_decide: anchor 1 not found';
  end if;
  v := replace(v, '    perform gbqs_invoke_edge(''survey-draft'', jsonb_build_object(''action'', ''issue'', ''draft_id'', d.id));',
    '    if j.status = ''on_hold'' or not coalesce(j.credit_used, false) then' || chr(10) ||
    '      return jsonb_build_object(''ok'', true, ''waiting_credit'', true, ''message'', ''Approved. No credits left: the report will be issued and e-mailed to your client as soon as credits are added.'');' || chr(10) ||
    '    end if;' || chr(10) ||
    '    perform gbqs_invoke_edge(''survey-draft'', jsonb_build_object(''action'', ''issue'', ''draft_id'', d.id));');
  if position('where id = j.id and status = ''submitted'';' in v) = 0 then raise exception 'sa_portal_job_draft_decide: anchor 2 not found'; end if;
  v := replace(v, 'where id = j.id and status = ''submitted'';', 'where id = j.id and status in (''submitted'', ''on_hold'');');
  execute v;
end $$;

-- 3. credits added: approved draft -> issue now; no draft yet -> start it
create or replace function public.sa_trg_job_released()
 returns trigger language plpgsql security definer set search_path to 'public' as $function$
declare d survey_drafts;
begin
  if new.status = 'submitted' and old.status = 'on_hold' and new.survey_id is not null
     and exists (select 1 from surveys where id = new.survey_id and status = 'submitted') then
    select * into d from survey_drafts where survey_id = new.survey_id
     order by (status in ('pending','approved')) desc, created_at desc limit 1;
    if d.status = 'approved' then
      perform gbqs_invoke_edge('survey-draft', jsonb_build_object('action', 'issue', 'draft_id', d.id));
    elsif d.id is null or d.status not in ('pending') then
      perform gbqs_draft_start(new.survey_id);
    end if;
  end if;
  return new;
exception when others then
  raise warning 'sa_trg_job_released: %', sqlerrm;
  return new;
end $function$;

-- 4. draft mail: note when there are no credits
do $$ declare v text;
begin
  v := pg_get_functiondef('public.sa_draft_mail(uuid,text)'::regprocedure);
  if position('no_credit_note' in v) = 0 then
    if position('||''<p style="margin:0;color:#5c6b85;font-size:12px;line-height:18px;">The draft link is valid for 7 days.' in v) = 0 then
      raise exception 'sa_draft_mail: anchor not found';
    end if;
    v := replace(v, '||''<p style="margin:0;color:#5c6b85;font-size:12px;line-height:18px;">The draft link is valid for 7 days.',
      '||case when j.status = ''on_hold'' then ''<p style="margin:0 0 14px;padding:10px 14px;background:#FFF6DD;border-left:4px solid #B47116;"><!--no_credit_note--><strong>No credits left.</strong> You can check and approve the draft now; the report is issued and e-mailed to your client as soon as credits are added (Credits &amp; invoices in the portal).</p>'' else '''' end'
      || chr(10) || '    ||''<p style="margin:0;color:#5c6b85;font-size:12px;line-height:18px;">The draft link is valid for 7 days.');
    execute v;
  end if;
end $$;

-- 5. My jobs: flag approved-waiting-for-credits
do $$ declare v text;
begin
  v := pg_get_functiondef('public.sa_portal_jobs'::regproc);
  if position('''waiting_credit''' in v) = 0 then
    if position('''draft_status'', ld.status,' in v) = 0 then raise exception 'sa_portal_jobs: anchor not found'; end if;
    v := replace(v, '''draft_status'', ld.status,',
      '''draft_status'', ld.status, ''waiting_credit'', j.status = ''on_hold'' and ld.status = ''approved'', ''no_credit'', j.status = ''on_hold'',');
    execute v;
  end if;
end $$;

-- surveyor_access_16_portal_pages (A12, 09-11): Reports, My clients, Rating + GCS-voortgang
create or replace function public.sa_portal_reports(p_search text default null)
 returns jsonb language sql stable security definer set search_path to 'public' as $$
  select coalesce(jsonb_agg(x order by x->>'issued_at' desc nulls last), '[]'::jsonb) from (
    select jsonb_build_object(
      'job_id', j.id, 'reference', j.reference, 'report_number', coalesce(s.report_number, j.reference),
      'survey_type', j.survey_type, 'survey_label', coalesce(t.description, j.survey_type),
      'vessel', coalesce(v.display_name, v.vessel_name, j.vessel_name), 'imo', j.imo_number,
      'port', coalesce(h.naam, j.port_text), 'client', sc.name, 'client_reference', j.client_reference,
      'surveyor', coalesce(nullif(u.full_name,''), u.email), 'location', l.name,
      'date_of_survey', s.date_of_survey, 'issued_at', s.issued_at,
      'revision', (select max(r.rev_no) from survey_revisions r where r.survey_id = s.id and r.issued_at is not null),
      'sent_to', m.mail_to, 'sent_cc', m.mail_cc, 'mail_status', m.status, 'sent_at', m.created_at,
      'opened', coalesce((select sum(rl.open_count) from sa_report_links rl where rl.survey_id = s.id), 0),
      'last_opened_at', (select max(rl.last_opened_at) from sa_report_links rl where rl.survey_id = s.id)) x
    from surveyor_jobs j
    join surveys s on s.id = j.survey_id
    left join survey_types_config t on t.name = j.survey_type
    left join vessels v on v.id = j.vessel_id
    left join havens h on h.id = j.haven_id
    left join surveyor_clients sc on sc.id = j.surveyor_client_id
    left join surveyor_company_locations l on l.id = j.location_id
    left join surveyor_company_users u on u.user_id = j.assigned_user_id
    left join lateral (select rm.* from sa_report_mails rm where rm.survey_id = s.id order by rm.created_at desc limit 1) m on true
    where j.company_id = sa_my_company_id() and sa_job_visible(j.company_id, j.assigned_user_id, j.location_id)
      and exists (select 1 from survey_documents sd where sd.survey_id = s.id and sd.section = 'report')
      and (coalesce(trim(p_search),'') = '' or concat_ws(' ', j.reference, s.report_number, j.vessel_name, j.imo_number, sc.name, j.client_reference, h.naam, j.port_text)
           ilike '%' || trim(p_search) || '%')
    limit 500) q
$$;
revoke all on function public.sa_portal_reports(text) from public, anon;
grant execute on function public.sa_portal_reports(text) to authenticated;

