create or replace function public.sa_portal_archive_client(p_id uuid, p_archive boolean default true)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare c surveyor_clients;
begin
  if not sa_can_create_jobs() then return jsonb_build_object('ok', false, 'code', 'not_allowed', 'message', 'You cannot change clients.'); end if;
  select * into c from surveyor_clients where id = p_id and company_id = sa_my_company_id();
  if c.id is null then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Client not found.'); end if;
  if p_archive and exists (select 1 from surveyor_jobs j where j.surveyor_client_id = c.id and j.status in ('draft','open','in_progress','submitted','on_hold')) then
    return jsonb_build_object('ok', false, 'code', 'open_jobs', 'message', 'This client still has open jobs.');
  end if;
  update surveyor_clients set archived_at = case when p_archive then now() else null end, updated_at = now() where id = c.id;
  return jsonb_build_object('ok', true, 'message', case when p_archive then 'Client archived.' else 'Client restored.' end);
end $function$;
revoke all on function public.sa_portal_archive_client(uuid, boolean) from public, anon;
grant execute on function public.sa_portal_archive_client(uuid, boolean) to authenticated;

