create or replace function public.sa_portal_rating()
 returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare v_u surveyor_company_users; v_sc jsonb; v_crit jsonb; v_list jsonb; v_net numeric; v_net_n int; v_ids uuid[];
  v_min_s int; v_min_v int; v_min_score numeric; v_months int; v_min_scored int;
begin
  select * into v_u from surveyor_company_users where user_id = auth.uid() and status = 'active';
  if v_u.user_id is null then return jsonb_build_object('ok', false, 'message', 'No access.'); end if;
  v_crit := coalesce((select value::jsonb from system_settings where key = 'gcs_criteria'), '{}'::jsonb);
  v_min_s := coalesce((v_crit->>'min_surveys')::int, 10);
  v_min_v := coalesce((v_crit->>'min_vessels')::int, 3);
  v_min_score := coalesce((v_crit->>'min_score')::numeric, 4.0);
  v_months := coalesce((v_crit->>'period_months')::int, 12);
  v_min_scored := coalesce((v_crit->>'min_scored_surveys')::int, 5);
  v_sc := gbqs_scorecards((select array_agg(id) from clients), (current_date - make_interval(months => v_months))::date, current_date);
  select avg((x->>'score')::numeric), count(*) into v_net, v_net_n
    from jsonb_array_elements(coalesce(v_sc->'surveyors','[]'::jsonb)) x where (x->>'score') is not null;
  select array_agg(sv.id) into v_ids
    from surveyors sv
   where sv.company_id = v_u.company_id
     and (v_u.is_office or v_u.is_admin
          or sv.id = v_u.surveyor_id
          or exists (select 1 from surveyor_company_users cu join surveyor_company_user_locations ul on ul.user_id = cu.user_id
                      where cu.surveyor_id = sv.id and cu.company_id = v_u.company_id
                        and exists (select 1 from surveyor_company_user_locations m where m.user_id = v_u.user_id and m.is_manager and m.location_id = ul.location_id)));
  select coalesce(jsonb_agg(jsonb_build_object(
      'surveyor_id', sv.id, 'name', sv.name, 'is_me', sv.id = v_u.surveyor_id,
      'score', (sc->>'score')::numeric, 'class', sc->>'class', 'surveys', coalesce((sc->>'surveys')::int, 0),
      'components', coalesce(sc->'components', '[]'::jsonb), 'ports', coalesce(sc->'ports', '[]'::jsonb),
      'short_caught', coalesce((sc->>'short_caught')::int, 0), 'discrepancies', coalesce((sc->>'discrepancies')::int, 0),
      'gcs', jsonb_build_object(
        'status', coalesce(sv.gcs_status, 'candidate'),
        'surveys', g.n, 'vessels', g.vessels, 'score', (sc->>'score')::numeric,
        'need_surveys', greatest(v_min_s - g.n, 0), 'need_vessels', greatest(v_min_v - g.vessels, 0),
        'score_ok', coalesce((sc->>'score')::numeric >= v_min_score, false),
        'eligible', g.n >= v_min_s and g.vessels >= v_min_v and coalesce((sc->>'score')::numeric >= v_min_score, false))
    ) order by (sv.id = v_u.surveyor_id) desc, (sc->>'score')::numeric desc nulls last, sv.name), '[]'::jsonb)
    into v_list
    from surveyors sv
    left join lateral (select x as sc from jsonb_array_elements(coalesce(v_sc->'surveyors','[]'::jsonb)) x where x->>'id' = sv.id::text limit 1) s1 on true
    left join lateral (
      select count(*)::int as n, count(distinct coalesce(nullif(su.imo_number,''), su.vessel_name))::int as vessels
        from surveys su
       where su.surveyor_id = sv.id and su.status in ('issued','invoiced','completed','closed')
         and coalesce(su.issued_at, su.created_at) >= now() - make_interval(months => v_months)) g on true
   where sv.id = any(coalesce(v_ids, '{}'));
  return jsonb_build_object('ok', true,
    'network', jsonb_build_object('average', round(v_net, 2), 'rated_surveyors', v_net_n),
    'criteria', jsonb_build_object('min_surveys', v_min_s, 'min_vessels', v_min_v, 'min_score', v_min_score, 'period_months', v_months, 'min_scored_surveys', v_min_scored),
    'can_see_team', v_u.is_office or v_u.is_admin,
    'surveyors', v_list);
end $function$;
revoke all on function public.sa_portal_rating() from public, anon;
grant execute on function public.sa_portal_rating() to authenticated;

do $$ declare v text;
begin
  v := pg_get_functiondef('public.sa_portal_rating()'::regprocedure);
  if position('''status'', coalesce(sv.gcs_status, ''candidate''),' in v) = 0 then raise exception 'anchor not found'; end if;
  -- surveyors.gcs_status has a legacy default 'conditional'; until C1 only 'certified' counts as a real status
  v := replace(v, '''status'', coalesce(sv.gcs_status, ''candidate''),', '''status'', case when sv.gcs_status = ''certified'' then ''certified'' else ''candidate'' end,');
  execute v;
end $$;

-- surveyor_access_17_ops (A8, 09-11): Retool – surveybedrijven, bedrijfscontrole, tegoed corrigeren, vroege aanmelders
