create or replace view public.ops_surveyor_companies as
select c.id, c.name, c.domain, c.country, c.city, c.website, c.office_email, c.phone, c.vat_number,
       c.region_code, c.status, c.early_bird, c.verified_at, c.verified_by, c.created_at, c.updated_at,
       c.logo_path is not null as has_logo, c.terms_version, c.terms_accepted_at, c.notes,
       (c.domain is null) as free_email_domain,
       adm.full_name as admin_name, adm.email as admin_email,
       (select count(*) from surveyor_company_users u where u.company_id = c.id and u.status = 'active')::int as users,
       (select count(*) from surveyor_company_locations l where l.company_id = c.id and l.archived_at is null)::int as locations,
       sa_credit_balance(c.id) as credits,
       (select coalesce(sum(-m.delta), 0) from sa_credit_moves m where m.company_id = c.id and m.kind = 'use')::int as credits_used,
       (select count(*) from surveyor_jobs j where j.company_id = c.id and j.status <> 'cancelled')::int as jobs,
       (select count(*) from surveyor_jobs j where j.company_id = c.id and j.status in ('draft','open','in_progress','submitted','on_hold'))::int as open_jobs,
       (select count(*) from surveyor_jobs j where j.company_id = c.id and j.status = 'on_hold')::int as on_hold_jobs,
       (select count(*) from surveyor_jobs j join survey_documents sd on sd.survey_id = j.survey_id and sd.section = 'report' where j.company_id = c.id)::int as reports,
       (select max(j.updated_at) from surveyor_jobs j where j.company_id = c.id) as last_job_at
  from surveyor_companies c
  left join lateral (select u.full_name, u.email from surveyor_company_users u
                      where u.company_id = c.id and u.is_admin and u.status = 'active'
                      order by u.created_at limit 1) adm on true;
revoke all on public.ops_surveyor_companies from public, anon, authenticated;
grant select on public.ops_surveyor_companies to service_role;

