                   'job_reference', j.reference) m
                   from sa_credit_moves m left join surveyor_jobs j on j.id = m.job_id
                  where m.company_id = p_id order by m.created_at desc limit 100) q), '[]'::jsonb),
    'jobs', coalesce((select jsonb_agg(q.j order by q.created_at desc) from (
                 select j.created_at, jsonb_build_object('reference', j.reference, 'status', j.status, 'vessel', j.vessel_name, 'imo', j.imo_number,
                   'port', coalesce(h.naam, j.port_text), 'eta', j.eta, 'survey_type', j.survey_type, 'client', sc.name,
                   'credit_used', j.credit_used, 'created_at', j.created_at) j
                   from surveyor_jobs j left join havens h on h.id = j.haven_id left join surveyor_clients sc on sc.id = j.surveyor_client_id
                  where j.company_id = p_id order by j.created_at desc limit 50) q), '[]'::jsonb)
  ) end
$$;
