create or replace function public.ops_sa_set_company_status(p_id uuid, p_status text, p_by text, p_note text default null, p_mail boolean default true)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare v_old text; r jsonb; c surveyor_companies; v_to text; v_url text; v_body text; v_credits int;
begin
  select status into v_old from surveyor_companies where id = p_id;
  if v_old is null then return jsonb_build_object('ok', false, 'message', 'Bedrijf niet gevonden.'); end if;
  if p_status in ('suspended','blocked') and coalesce(trim(p_note), '') = '' then
    return jsonb_build_object('ok', false, 'message', 'Geef een reden op bij schorsen of blokkeren.');
  end if;
  r := sa_ops_set_company_status(p_id, p_status, p_by, nullif(trim(coalesce(p_note, '')), ''));
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  if p_status = 'approved' and v_old <> 'approved' and p_mail then
    select * into c from surveyor_companies where id = p_id;
    select string_agg(distinct u.email, ',') into v_to from surveyor_company_users u where u.company_id = p_id and u.is_admin and u.status = 'active';
    v_url := coalesce(nullif((select value from system_settings where key = 'portal_url'), ''), 'https://portal.globalbqs.com');
    v_credits := sa_credit_balance(p_id);
    if v_to is not null then
      v_body := '<p style="margin:0 0 12px;">Good news: we have checked <strong>' || replace(replace(c.name, '<', '&lt;'), '>', '&gt;')
        || '</strong> and your company is now approved on GlobalBQS.</p>'
        || '<p style="margin:0 0 12px;">You can create jobs, issue reports with your own logo and buy credits in the portal.'
        || case when v_credits > 0 then ' You have <strong>' || v_credits || ' credit' || case when v_credits = 1 then '' else 's' end || '</strong> available.' else '' end
        || ' Your rating starts to build up from your issued surveys.</p>'
        || '<p style="margin:0 0 16px;">' || gbqs_mail_btn(v_url || '/surveyor', 'Open the portal', 'primary') || '</p>'
        || '<p style="margin:0;color:#5c6b85;font-size:12px;line-height:18px;">Questions? Reply to this e-mail or call us at +31 10 340 0240.</p>';
      perform gbqs_send_mail_ext(v_to, 'Your company is approved on GlobalBQS', gbqs_mail_wrap('SURVEYOR ACCESS', v_body),
                                 nullif(c.office_email, ''), 'surveyors@globalbqs.com');
      r := r || jsonb_build_object('mailed_to', v_to);
    end if;
  end if;
  return r || jsonb_build_object('message', case p_status when 'approved' then 'Bedrijf goedgekeurd.' when 'suspended' then 'Bedrijf geschorst.'
                                  when 'blocked' then 'Bedrijf geblokkeerd.' else 'Status teruggezet naar Te controleren.' end);
end $function$;
revoke all on function public.ops_sa_set_company_status(uuid, text, text, text, boolean) from public, anon, authenticated;
grant execute on function public.ops_sa_set_company_status(uuid, text, text, text, boolean) to service_role;

create or replace function public.ops_sa_credit_adjust(p_id uuid, p_delta int, p_note text, p_by text)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare v_left int; t record; v_take int;
begin
  if not exists (select 1 from surveyor_companies where id = p_id) then return jsonb_build_object('ok', false, 'message', 'Bedrijf niet gevonden.'); end if;
  if coalesce(trim(p_note), '') = '' then return jsonb_build_object('ok', false, 'message', 'Een reden is verplicht.'); end if;
  if p_delta is null or p_delta = 0 or abs(p_delta) > 500 then return jsonb_build_object('ok', false, 'message', 'Aantal tussen -500 en 500, niet 0.'); end if;
  if p_delta > 0 then
    return sa_credit_grant(p_id, 'adjust', p_delta, 0, trim(p_note), p_by) || jsonb_build_object('message', 'Tegoed verhoogd met ' || p_delta || '.');
  end if;
  if sa_credit_balance(p_id) < -p_delta then
    return jsonb_build_object('ok', false, 'message', 'Saldo is ' || sa_credit_balance(p_id) || '; je kunt niet meer afboeken dan het saldo.');
  end if;
  v_left := -p_delta;
  for t in select id, remaining from sa_credit_lots where company_id = p_id and remaining > 0 and expires_at > now()
            order by expires_at, created_at for update loop
    exit when v_left = 0;
    v_take := least(t.remaining, v_left);
    update sa_credit_lots set remaining = remaining - v_take where id = t.id;
    insert into sa_credit_moves(company_id, lot_id, kind, delta, note, created_by) values (p_id, t.id, 'adjust', -v_take, trim(p_note), p_by);
    v_left := v_left - v_take;
  end loop;
  return jsonb_build_object('ok', true, 'balance', sa_credit_balance(p_id), 'message', 'Tegoed verlaagd met ' || -p_delta || '.');
end $function$;
revoke all on function public.ops_sa_credit_adjust(uuid, int, text, text) from public, anon, authenticated;
grant execute on function public.ops_sa_credit_adjust(uuid, int, text, text) to service_role;

