-- surveyor_access_18_rating_gcs (A7 + C1 + C2 + C3, 09-11)
do $$ declare v text;
begin
  v := pg_get_viewdef('public.sc_survey_facts'::regclass);
  if position('self_reported' in v) > 0 then return; end if;
  if position('FROM ((((((((surveys s' in v) = 0 or position('JOIN orders o ON ((o.id = s.order_id)))' in v) = 0
     or position('LEFT JOIN vessels v ON ((v.id = o.vessel_id)))' in v) = 0
     or position('    o.vessel_id,' in v) = 0
     or position('(o.created_at)::date) AS survey_date' in v) = 0
     or position('(NOT COALESCE(s.is_external, false)));' in v) = 0
     or position('END AS report_h' in v) = 0 then
    raise exception 'sc_survey_facts: anchor not found';
  end if;
  v := replace(v, 'FROM ((((((((surveys s', 'FROM (((((((((surveys s');
  v := replace(v, 'JOIN orders o ON ((o.id = s.order_id)))',
                  'LEFT JOIN orders o ON ((o.id = s.order_id)))' || chr(10) || '     LEFT JOIN surveyor_jobs sj ON ((sj.id = s.surveyor_job_id)))');
  v := replace(v, 'LEFT JOIN vessels v ON ((v.id = o.vessel_id)))', 'LEFT JOIN vessels v ON ((v.id = COALESCE(o.vessel_id, sj.vessel_id))))');
  v := replace(v, '    o.vessel_id,', '    COALESCE(o.vessel_id, sj.vessel_id) AS vessel_id,');
  v := replace(v, '(o.created_at)::date) AS survey_date', '(o.created_at)::date, (sj.created_at)::date) AS survey_date');
  v := replace(v, '(NOT COALESCE(s.is_external, false)));',
                  '(NOT COALESCE(s.is_external, false)) AND ((s.order_id IS NOT NULL) OR (s.surveyor_job_id IS NOT NULL)));');
  v := replace(v, 'END AS report_h', 'END AS report_h,' || chr(10) || '    (s.surveyor_job_id IS NOT NULL) AS self_reported');
  execute 'create or replace view public.sc_survey_facts as ' || v;
end $$;

do $$ declare v text;
begin
  v := pg_get_functiondef('public.gbqs_scorecards(uuid[],date,date)'::regprocedure);
  if position('not self_reported' in v) > 0 then return; end if;
  if position('where survey_date between p_from and p_to and pump_rate > 0;' in v) = 0
     or position('select * from fa where own),' in v) = 0
     or position('where coalesce(x.bdn,0) > 0 and coalesce(trim(x.sup),'''') <> ''''),' in v) = 0 then
    raise exception 'gbqs_scorecards: anchor not found';
  end if;
  v := replace(v, 'where survey_date between p_from and p_to and pump_rate > 0;', 'where survey_date between p_from and p_to and pump_rate > 0 and not self_reported;');
  v := replace(v, 'select * from fa where own),', 'select * from fa where own and not self_reported),');
  v := replace(v, 'where coalesce(x.bdn,0) > 0 and coalesce(trim(x.sup),'''') <> ''''),',
                  'where not fa.self_reported and coalesce(x.bdn,0) > 0 and coalesce(trim(x.sup),'''') <> ''''),');
  execute v;
end $$;

create or replace view public.ops_sa_rating_signals as
with f as (
  select x.*, (exists (select 1 from survey_phases p where p.survey_id = x.survey_id
                         and coalesce(p.lsfo_total,0) + coalesce(p.hsfo_total,0) + coalesce(p.lsmgo_total,0) + coalesce(p.mdo_total,0) > 0)
               and not exists (select 1 from survey_phases p where p.survey_id = x.survey_id
                         and (coalesce(p.lsfo_verschil,0) <> 0 or coalesce(p.hsfo_verschil,0) <> 0 or coalesce(p.lsmgo_verschil,0) <> 0 or coalesce(p.mdo_verschil,0) <> 0))) as rob_zero,
         (coalesce(x.bdn_total,0) > 0 and coalesce(x.worst_svb_pct,0) = 0
          and not exists (select 1 from survey_bdn b where b.survey_id = x.survey_id
                           and (coalesce(b.lsfo_ship_vs_bdn,0) <> 0 or coalesce(b.hsfo_ship_vs_bdn,0) <> 0 or coalesce(b.lsmgo_ship_vs_bdn,0) <> 0 or coalesce(b.mdo_ship_vs_bdn,0) <> 0))) as bdn_zero
    from sc_survey_facts x
   where x.self_reported and x.surveyor_id is not null and x.survey_date >= current_date - 365),
agg as (
  select surveyor_id, count(*)::int n,
         count(distinct coalesce(vessel_id::text, upper(vessel_name)))::int vessels,
         (select max(c) from (select count(*) c from f f2 where f2.surveyor_id = f.surveyor_id group by coalesce(f2.vessel_id::text, upper(f2.vessel_name))) q)::int top_vessel_n,
         count(*) filter (where not photos_ok)::int no_photos,
         count(*) filter (where rob_zero or bdn_zero)::int zero_diff,
         count(*) filter (where not sig_ok)::int no_signatures,
         max(survey_date) last_survey
    from f group by surveyor_id)
select a.surveyor_id, sv.name, sc.name as company_name, sv.company_id, a.n as self_reported_surveys, a.vessels, a.top_vessel_n,
       round(100.0 * a.top_vessel_n / a.n) as top_vessel_pct,
       a.no_photos, round(100.0 * a.no_photos / a.n) as no_photos_pct,
       a.zero_diff, round(100.0 * a.zero_diff / a.n) as zero_diff_pct,
       a.no_signatures, a.last_survey,
       array_remove(array[
         case when a.n >= 5 and a.top_vessel_n * 2 >= a.n then 'Vaak hetzelfde schip' end,
         case when a.n >= 5 and a.no_photos * 2 >= a.n then 'Vaak zonder foto''s' end,
         case when a.n >= 5 and a.zero_diff * 2 >= a.n then 'Vaak precies 0,00% verschil' end,
         case when a.no_signatures > 0 then 'Handtekening ontbreekt (' || a.no_signatures || '×)' end], null) as signals
  from agg a join surveyors sv on sv.id = a.surveyor_id left join surveyor_companies sc on sc.id = sv.company_id;
revoke all on public.ops_sa_rating_signals from public, anon, authenticated;
grant select on public.ops_sa_rating_signals to service_role;

