create or replace function public.gbqs_gcs_facts(p_scorecards jsonb default null)
 returns table(surveyor_id uuid, name text, email text, company_id uuid, surveys int, vessels int, score numeric,
               active boolean, company_ok boolean, blocked boolean, watch boolean, eligible boolean, missing text[])
 language plpgsql stable security definer set search_path to 'public' as $function$
#variable_conflict use_column
declare c jsonb := coalesce((select value::jsonb from system_settings where key = 'gcs_criteria'), '{}'::jsonb);
  v_min_s int := coalesce((c->>'min_surveys')::int, 10); v_min_v int := coalesce((c->>'min_vessels')::int, 3);
  v_min_score numeric := coalesce((c->>'min_score')::numeric, 4.0); v_months int := coalesce((c->>'period_months')::int, 12);
  v_sc jsonb;
begin
  v_sc := coalesce(p_scorecards, gbqs_scorecards(null, (current_date - make_interval(months => v_months))::date, current_date));
  return query
  with g as (
    select su.surveyor_id sid, count(*)::int n,
           count(distinct coalesce(nullif(su.imo_number, ''), upper(su.vessel_name)))::int nv
      from surveys su
     where su.surveyor_id is not null and su.status in ('issued','invoiced','completed','closed')
       and not coalesce(su.is_external, false)
       and coalesce(su.issued_at, su.created_at) >= now() - make_interval(months => v_months)
     group by su.surveyor_id),
  s as (select (x->>'id')::uuid sid, (x->>'score')::numeric sc from jsonb_array_elements(coalesce(v_sc->'surveyors','[]'::jsonb)) x)
  select sv.id, sv.name, sv.email, sv.company_id, coalesce(g.n, 0), coalesce(g.nv, 0), s.sc,
         coalesce(sv.deploy_status, 'active') = 'active',
         (sv.company_id is null or co.status = 'approved'),
         (coalesce(sv.deploy_status, 'active') in ('blocked','suspended') or co.status in ('blocked','suspended')),
         coalesce(sv.deploy_status, 'active') = 'watch',
         coalesce(g.n, 0) >= v_min_s and coalesce(g.nv, 0) >= v_min_v and coalesce(s.sc >= v_min_score, false)
           and coalesce(sv.deploy_status, 'active') = 'active' and (sv.company_id is null or co.status = 'approved'),
         array_remove(array[
           case when coalesce(g.n, 0) < v_min_s then 'surveys' end,
           case when coalesce(g.nv, 0) < v_min_v then 'vessels' end,
           case when not coalesce(s.sc >= v_min_score, false) then 'score' end,
           case when coalesce(sv.deploy_status, 'active') <> 'active' then 'deployment' end,
           case when not (sv.company_id is null or co.status = 'approved') then 'company_check' end], null)
    from surveyors sv
    left join surveyor_companies co on co.id = sv.company_id
    left join g on g.sid = sv.id
    left join s on s.sid = sv.id;
end $function$;
revoke all on function public.gbqs_gcs_facts(jsonb) from public, anon, authenticated;
grant execute on function public.gbqs_gcs_facts(jsonb) to service_role;

create or replace function public.gbqs_gcs_mail(p_surveyor_id uuid, p_kind text, p_reason text default null)
 returns text language plpgsql security definer set search_path to 'public' as $function$
declare sv surveyors; c surveyor_certifications; co surveyor_companies; v_to text; v_cc text; v_url text; v_body text; v_subj text;
  cr jsonb := coalesce((select value::jsonb from system_settings where key = 'gcs_criteria'), '{}'::jsonb);
  esc text;
begin
  select * into sv from surveyors where id = p_surveyor_id;
  select * into c from surveyor_certifications where surveyor_id = p_surveyor_id;
  if sv.id is null then return null; end if;
  if sv.company_id is not null then select * into co from surveyor_companies where id = sv.company_id; end if;
  v_to := coalesce(nullif(trim(sv.email), ''),
                   (select string_agg(distinct u.email, ',') from surveyor_company_users u where u.surveyor_id = sv.id and u.status = 'active'));
  if v_to is null then return null; end if;
  v_cc := concat_ws(',', nullif(co.office_email, ''), coalesce(nullif((select value from system_settings where key = 'notify_email'), ''), 'reports@globalbqs.com'));
  v_url := coalesce(nullif((select value from system_settings where key = 'portal_url'), ''), 'https://portal.globalbqs.com');
  esc := replace(replace(coalesce(sv.name, 'Surveyor'), '<', '&lt;'), '>', '&gt;');
  if p_kind = 'certified' then
    v_subj := 'You are a GlobalBQS Certified Surveyor';
    v_body := '<p style="margin:0 0 12px;">Dear ' || esc || ',</p>'
      || '<p style="margin:0 0 12px;">Congratulations: based on your survey data you are now a <strong>GlobalBQS Certified Surveyor</strong>.</p>'
      || gbqs_mail_row('Certificate number', c.cert_number) || gbqs_mail_row('Valid until', to_char(c.valid_until, 'DD Mon YYYY'))
      || gbqs_mail_row('Rating at award', coalesce(to_char(c.score_at_award, 'FM0.0'), '–')) || gbqs_mail_row('Surveys / vessels', coalesce(c.surveys_at_award, 0) || ' / ' || coalesce(c.vessels_at_award, 0))
      || '<p style="margin:14px 0 12px;">The certification is free and renews automatically every month as long as you meet the criteria. Clients see the badge next to your name. '
      || 'You can download the badge for your e-mail signature and LinkedIn in the portal.</p>'
      || '<p style="margin:0 0 16px;">' || gbqs_mail_btn(v_url || '/surveyor/rating', 'Download your badge', 'primary') || '</p>';
  elsif p_kind = 'conditional' then
    v_subj := 'Your GlobalBQS certification is conditional';
    v_body := '<p style="margin:0 0 12px;">Dear ' || esc || ',</p>'
      || '<p style="margin:0 0 12px;">At the monthly evaluation your certification <strong>' || coalesce(c.cert_number, '') || '</strong> no longer met all criteria'
      || coalesce(' (' || replace(replace(p_reason, '<', '&lt;'), '>', '&gt;') || ')', '') || '. It is now <strong>conditional</strong>.</p>'
      || '<p style="margin:0 0 12px;">You keep the badge until <strong>' || to_char(c.conditional_deadline, 'DD Mon YYYY') || '</strong>. '
      || 'If you meet the criteria again by then (at least ' || coalesce(cr->>'min_surveys', '10') || ' surveys on ' || coalesce(cr->>'min_vessels', '3')
      || ' or more vessels in the last ' || coalesce(cr->>'period_months', '12') || ' months and a rating of ' || coalesce(cr->>'min_score', '4.0')
      || ' or higher), the certification is restored automatically. Otherwise it is revoked.</p>'
      || '<p style="margin:0 0 16px;">' || gbqs_mail_btn(v_url || '/surveyor/rating', 'See your rating', 'primary') || '</p>';
  elsif p_kind = 'restored' then
    v_subj := 'Your GlobalBQS certification is restored';
    v_body := '<p style="margin:0 0 12px;">Dear ' || esc || ',</p>'
      || '<p style="margin:0 0 12px;">Good news: you meet all criteria again. Your certification <strong>' || coalesce(c.cert_number, '')
      || '</strong> is fully valid again until ' || to_char(c.valid_until, 'DD Mon YYYY') || '.</p>'
      || '<p style="margin:0 0 16px;">' || gbqs_mail_btn(v_url || '/surveyor/rating', 'See your rating', 'primary') || '</p>';
  elsif p_kind = 'revoked' then
    v_subj := 'Your GlobalBQS certification has been revoked';
    v_body := '<p style="margin:0 0 12px;">Dear ' || esc || ',</p>'
      || '<p style="margin:0 0 12px;">Your certification <strong>' || coalesce(c.cert_number, '') || '</strong> has been revoked'
      || coalesce(': ' || replace(replace(p_reason, '<', '&lt;'), '>', '&gt;'), '') || '. Please remove the badge from your e-mail signature, website and social media.</p>'
      || '<p style="margin:0 0 12px;">You can earn the certification again: we evaluate on the first day of every month.</p>'
      || '<p style="margin:0 0 16px;">' || gbqs_mail_btn(v_url || '/surveyor/rating', 'See your rating', 'primary') || '</p>';
  else
    return null;
  end if;
  v_body := v_body || '<p style="margin:0;color:#5c6b85;font-size:12px;line-height:18px;">Questions? Reply to this e-mail or call us at +31 10 340 0240.</p>';
  perform gbqs_send_mail_ext(v_to, v_subj, gbqs_mail_wrap('GLOBALBQS CERTIFIED SURVEYOR', v_body), nullif(v_cc, ''), 'surveyors@globalbqs.com');
  return v_to;
exception when others then
  raise warning 'gbqs_gcs_mail: %', sqlerrm;
  return null;
end $function$;
revoke all on function public.gbqs_gcs_mail(uuid, text, text) from public, anon, authenticated;
grant execute on function public.gbqs_gcs_mail(uuid, text, text) to service_role;

create or replace function public.gbqs_gcs_set(p_surveyor_id uuid, p_to text, p_reason text, p_by text,
                                               p_score numeric default null, p_surveys int default null, p_vessels int default null, p_mail boolean default true)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare c surveyor_certifications; v_from text; v_num text; v_grace int; v_mail text; v_kind text;
begin
  insert into surveyor_certifications(surveyor_id) values (p_surveyor_id) on conflict (surveyor_id) do nothing;
  select * into c from surveyor_certifications where surveyor_id = p_surveyor_id for update;
  v_from := c.status;
  if v_from = p_to then return jsonb_build_object('ok', true, 'changed', false, 'status', v_from); end if;
  v_grace := coalesce((select (value::jsonb->>'grace_days')::int from system_settings where key = 'gcs_criteria'), 90);
  if p_to = 'certified' then
    v_num := c.cert_number;
    if v_num is null then
      perform pg_advisory_xact_lock(hashtext('gcs_cert_number'));
      select 'GCS-' || to_char(now(), 'YYYY') || '-' || lpad((coalesce(max(substring(cert_number from 10)::int), 0) + 1)::text, 4, '0')
        into v_num from surveyor_certifications where cert_number like 'GCS-' || to_char(now(), 'YYYY') || '-%';
    end if;
    v_kind := case when v_from = 'conditional' then 'restored' else 'certified' end;
    update surveyor_certifications set status = 'certified', cert_number = v_num,
           certified_since = case when v_from = 'conditional' then certified_since else now() end,
           valid_until = now() + interval '12 months', conditional_since = null, conditional_deadline = null, revoked_at = null,
           reason = p_reason,
           score_at_award = case when v_from = 'conditional' then score_at_award else p_score end,
           surveys_at_award = case when v_from = 'conditional' then surveys_at_award else p_surveys end,
           vessels_at_award = case when v_from = 'conditional' then vessels_at_award else p_vessels end,
           updated_at = now()
     where surveyor_id = p_surveyor_id;
  elsif p_to = 'conditional' then
    if v_from <> 'certified' then return jsonb_build_object('ok', false, 'message', 'Alleen een gecertificeerde surveyor kan conditional worden.'); end if;
    v_kind := 'conditional';
    update surveyor_certifications set status = 'conditional', conditional_since = now(),
           conditional_deadline = now() + make_interval(days => v_grace), reason = p_reason, updated_at = now()
     where surveyor_id = p_surveyor_id;
  elsif p_to = 'revoked' then
    if v_from not in ('certified', 'conditional') then return jsonb_build_object('ok', false, 'message', 'Er is geen certificering om in te trekken.'); end if;
    v_kind := 'revoked';
    update surveyor_certifications set status = 'revoked', revoked_at = now(), valid_until = least(valid_until, now()),
           conditional_since = null, conditional_deadline = null, reason = p_reason, updated_at = now()
     where surveyor_id = p_surveyor_id;
  else
    return jsonb_build_object('ok', false, 'message', 'Onbekende status.');
  end if;
  if p_mail then v_mail := gbqs_gcs_mail(p_surveyor_id, v_kind, p_reason); end if;
  select * into c from surveyor_certifications where surveyor_id = p_surveyor_id;
  insert into surveyor_certification_events(surveyor_id, from_status, to_status, reason, score, surveys, vessels, cert_number, created_by, mailed_to)
  values (p_surveyor_id, v_from, p_to, p_reason, p_score, p_surveys, p_vessels, c.cert_number, p_by, v_mail);
  return jsonb_build_object('ok', true, 'changed', true, 'from', v_from, 'status', p_to, 'cert_number', c.cert_number, 'mailed_to', v_mail);
end $function$;
revoke all on function public.gbqs_gcs_set(uuid, text, text, text, numeric, int, int, boolean) from public, anon, authenticated;
grant execute on function public.gbqs_gcs_set(uuid, text, text, text, numeric, int, int, boolean) to service_role;

create or replace function public.gbqs_gcs_evaluate(p_by text default 'monthly', p_mail boolean default true)
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare f record; c surveyor_certifications; r jsonb; v_out jsonb := '[]'::jsonb; v_n int := 0; v_reason text;
begin
  if p_by = 'monthly' and coalesce((select value from system_settings where key = 'gcs_evaluation_enabled'), 'false') <> 'true' then
    return jsonb_build_object('ok', true, 'skipped', 'gcs_evaluation_enabled is not true');
  end if;
  for f in select * from gbqs_gcs_facts() loop
    v_n := v_n + 1;
    select * into c from surveyor_certifications where surveyor_id = f.surveyor_id;
    v_reason := case when array_length(f.missing, 1) is null then null else
      array_to_string(array(select case m when 'surveys' then 'too few surveys' when 'vessels' then 'too few different vessels'
                                         when 'score' then 'rating below the minimum' when 'deployment' then 'not active'
                                         when 'company_check' then 'company not checked' else m end
                              from unnest(f.missing) m), ', ') end;
    r := null;
    if c.status in ('certified', 'conditional') and f.blocked then
      r := gbqs_gcs_set(f.surveyor_id, 'revoked', 'suspended or blocked', p_by, f.score, f.surveys, f.vessels, p_mail);
    elsif coalesce(c.status, 'candidate') in ('candidate', 'revoked') and f.eligible then
      r := gbqs_gcs_set(f.surveyor_id, 'certified', 'criteria met', p_by, f.score, f.surveys, f.vessels, p_mail);
    elsif c.status = 'certified' and not f.eligible then
      r := gbqs_gcs_set(f.surveyor_id, 'conditional', v_reason, p_by, f.score, f.surveys, f.vessels, p_mail);
    elsif c.status = 'certified' and f.eligible then
      update surveyor_certifications set valid_until = now() + interval '12 months', updated_at = now() where surveyor_id = f.surveyor_id;
    elsif c.status = 'conditional' and f.eligible and not f.watch then
      r := gbqs_gcs_set(f.surveyor_id, 'certified', 'criteria met again', p_by, f.score, f.surveys, f.vessels, p_mail);
    elsif c.status = 'conditional' and now() >= c.conditional_deadline then
      r := gbqs_gcs_set(f.surveyor_id, 'revoked', coalesce(v_reason, 'not restored within the grace period'), p_by, f.score, f.surveys, f.vessels, p_mail);
    end if;
    if c.surveyor_id is not null or f.surveys > 0 then
      insert into surveyor_certifications(surveyor_id) values (f.surveyor_id) on conflict (surveyor_id) do nothing;
      update surveyor_certifications set last_evaluated_at = now(), last_score = f.score, last_surveys = f.surveys, last_vessels = f.vessels
       where surveyor_id = f.surveyor_id;
    end if;
    if r is not null and coalesce((r->>'changed')::boolean, false) then
      v_out := v_out || jsonb_build_object('surveyor', f.name, 'from', r->>'from', 'to', r->>'status', 'cert_number', r->>'cert_number');
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'evaluated', v_n, 'changes', v_out);
end $function$;
revoke all on function public.gbqs_gcs_evaluate(text, boolean) from public, anon, authenticated;
grant execute on function public.gbqs_gcs_evaluate(text, boolean) to service_role;

create or replace function public.gbqs_gcs_trg_surveyor()
 returns trigger language plpgsql security definer set search_path to 'public' as $function$
declare c surveyor_certifications;
begin
  select * into c from surveyor_certifications where surveyor_id = new.id;
  if c.status in ('certified','conditional') and new.deploy_status in ('blocked','suspended') then
    perform gbqs_gcs_set(new.id, 'revoked', 'suspended or blocked', 'system');
  elsif c.status = 'certified' and new.deploy_status = 'watch' then
    perform gbqs_gcs_set(new.id, 'conditional', 'under review', 'system');
  end if;
  return new;
exception when others then
  raise warning 'gbqs_gcs_trg_surveyor: %', sqlerrm;
  return new;
end $function$;
