create trigger trg_gcs_surveyor_status after update of deploy_status on public.surveyors
  for each row when (old.deploy_status is distinct from new.deploy_status) execute function public.gbqs_gcs_trg_surveyor();

create or replace function public.gbqs_gcs_trg_company()
 returns trigger language plpgsql security definer set search_path to 'public' as $function$
declare s record;
begin
  if new.status in ('blocked','suspended') then
    for s in select c.surveyor_id from surveyor_certifications c join surveyors sv on sv.id = c.surveyor_id
              where sv.company_id = new.id and c.status in ('certified','conditional') loop
      perform gbqs_gcs_set(s.surveyor_id, 'revoked', 'company suspended or blocked', 'system');
    end loop;
  end if;
  return new;
exception when others then
  raise warning 'gbqs_gcs_trg_company: %', sqlerrm;
  return new;
end $function$;
