create or replace function public.sa_trg_merged_report()
 returns trigger language plpgsql security definer set search_path to 'public' as $function$
declare j record;
begin
  if new.section <> 'report' or new.survey_id is null then return new; end if;
  for j in select id from surveyor_jobs where gbqs_survey_id = new.survey_id and status in ('merged') loop
    begin
