create or replace view public.ops_sa_overlaps as
select j.id as job_id, j.reference, co.name as company_name, j.vessel_name, j.imo_number, coalesce(h.naam, j.port_text) as port,
       j.eta, j.survey_type, j.status as job_status, ov->>'gbqs_reference' as gbqs_reference, (ov->>'order_id')::uuid as order_id,
       ov->>'surveyor' as gbqs_surveyor
  from surveyor_jobs j
  join surveyor_companies co on co.id = j.company_id
  left join havens h on h.id = j.haven_id
  cross join lateral (select sa_find_gbqs_overlap(j.company_id, j.imo_number, j.haven_id, j.survey_type, j.eta) ov) x
 where j.status not in ('cancelled', 'merged') and ov is not null;
revoke all on public.ops_sa_overlaps from public, anon, authenticated;
grant select on public.ops_sa_overlaps to service_role;

