create or replace function public.gbqs_rating_access(p_clients uuid[])
 returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare cr jsonb := coalesce((select value::jsonb from system_settings where key = 'rating_access_criteria'), '{}'::jsonb);
  v_min int := coalesce((cr->>'min_surveys')::int, 3); v_days int := coalesce((cr->>'days')::int, 90);
  v_grace int := coalesce((cr->>'grace_days')::int, 30); v_new int := coalesce((cr->>'new_client_days')::int, 90);
  v_dates date[]; v_n int; v_a date; v_c date; v_until date; v_new_client boolean;
begin
  select array_agg(d order by d desc) into v_dates from (
    select coalesce(s.date_of_survey, s.issued_at::date) d
      from surveys s join orders o on o.id = s.order_id
     where o.client_id = any(p_clients) and lower(coalesce(o.service_level, 'logbook')) = 'logbook'
       and s.status in ('issued','invoiced','closed') and not coalesce(s.is_external, false)
     order by 1 desc limit 50) x;
  v_n := (select count(*) from unnest(coalesce(v_dates, '{}')) d where d > current_date - v_days);
  v_new_client := exists (select 1 from clients c where c.id = any(p_clients) and coalesce(c.onboarded_at, c.created_at) > now() - make_interval(days => v_new));
  if v_n >= v_min or (v_new_client and v_n >= 1) then
    return jsonb_build_object('level', 'full', 'surveys_window', v_n, 'min_surveys', v_min, 'days', v_days);
  end if;
  if coalesce(array_length(v_dates, 1), 0) >= v_min then
    v_a := v_dates[1]; v_c := v_dates[v_min];
    v_until := v_c + v_days - 1 + v_grace;
    if v_until >= current_date then
      return jsonb_build_object('level', 'grace', 'until', v_until, 'surveys_window', v_n, 'min_surveys', v_min, 'days', v_days);
    end if;
  end if;
  return jsonb_build_object('level', 'basic', 'surveys_window', v_n, 'min_surveys', v_min, 'days', v_days);
end $function$;
revoke all on function public.gbqs_rating_access(uuid[]) from public, anon, authenticated;
grant execute on function public.gbqs_rating_access(uuid[]) to service_role;

create or replace function public.portal_scorecards(p_from date default (current_date - 365), p_to date default current_date)
 returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare v_ids uuid[]; v_sc jsonb; v_acc jsonb; v_list jsonb;
begin
  if auth.uid() is null then return null; end if;
  v_ids := array(select portal_my_client_ids());
  if coalesce(array_length(v_ids,1),0) = 0 then return null; end if;
  v_sc := gbqs_scorecards(v_ids, p_from, p_to);
  v_acc := gbqs_rating_access(v_ids);
  select coalesce(jsonb_agg(
           case when v_acc->>'level' = 'basic'
                then (x - 'score' - 'components' - 'ports' - 'short_caught' - 'discrepancies')
                     || jsonb_build_object('score', null, 'components', '[]'::jsonb, 'ports', '[]'::jsonb, 'restricted', true)
                else x end
           || jsonb_build_object('gcs_certified', coalesce(c.status = 'certified', false), 'gcs_number', case when c.status = 'certified' then c.cert_number end)
         order by ord), '[]'::jsonb)
    into v_list
    from jsonb_array_elements(coalesce(v_sc->'surveyors', '[]'::jsonb)) with ordinality t(x, ord)
    left join surveyor_certifications c on c.surveyor_id::text = t.x->>'id';
  v_sc := jsonb_set(v_sc, '{surveyors}', v_list);
  if v_acc->>'level' = 'basic' then
    v_sc := jsonb_set(v_sc, '{network,surveyors}', coalesce(v_sc->'network'->'surveyors', '{}'::jsonb) || jsonb_build_object('score', null));
  end if;
  return v_sc || jsonb_build_object('rating_access', v_acc);
end $function$;

