create or replace function public.sa_report_link_open(p_token text, p_kind text default 'report')
 returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare l sa_report_links; c surveyor_companies; s surveys; j surveyor_jobs; v_newer boolean := false;
begin
  select * into l from sa_report_links where token = p_token;
  if l.id is null then return jsonb_build_object('ok', false, 'message', 'This link is not valid.'); end if;
  if p_kind = 'logo' then
    select * into c from surveyor_companies where id = l.company_id;
    return jsonb_build_object('ok', c.logo_path is not null, 'bucket', 'surveyor-logos', 'path', c.logo_path);
  end if;
  if l.revoked_at is not null then
    -- a newer version exists: send the viewer to the latest one
    select * into l from sa_report_links where survey_id = l.survey_id and revoked_at is null order by created_at desc limit 1;
    if l.id is null then return jsonb_build_object('ok', false, 'message', 'This report is no longer available.'); end if;
    v_newer := true;
  end if;
  update sa_report_links set open_count = open_count + 1, first_opened_at = coalesce(first_opened_at, now()), last_opened_at = now() where id = l.id;
  select * into s from surveys where id = l.survey_id;
  select * into c from surveyor_companies where id = l.company_id;
  if l.job_id is not null then select * into j from surveyor_jobs where id = l.job_id; end if;
  return jsonb_build_object('ok', true, 'bucket', 'survey-documents', 'path', l.report_path,
    'file_name', coalesce(s.report_number, s.gbqs_reference) || '.pdf',
    'report_number', coalesce(s.report_number, s.gbqs_reference),
    'revision', l.revision, 'newer_version', v_newer,
    'vessel', coalesce(j.vessel_name, s.vessel_name, ''), 'imo', coalesce(j.imo_number, s.imo_number), 'port', j.port_text,
    'survey_type', j.survey_type, 'survey_date', coalesce(s.date_of_survey, s.issued_at::date),
    'company', c.name, 'company_website', c.website, 'company_country', c.country,
    'has_logo', c.logo_path is not null,
    'book_demo_url', (select value from system_settings where key = 'sa_book_demo_url'));
end $function$;
revoke all on function public.sa_report_link_open(text, text) from public, anon, authenticated;
grant execute on function public.sa_report_link_open(text, text) to service_role;

