-- 'Open in app' vanuit het portaal: surveyor is al ingelogd (evt. met 2FA) -> eenmalige code (5 min) in het hash-deel van de link,
-- de formulierenapp (>= 1.1.21) logt daarmee direct in zonder mailcode. Oudere app: gewone route (code per mail) blijft werken.
create or replace function public.sa_portal_job_form_url(p_id uuid)
 returns jsonb language plpgsql security definer set search_path to 'public'
as $function$
declare j surveyor_jobs; v_sid uuid; v_fj uuid; v_url text; r jsonb; fj form_jobs; v_code text;
begin
  select * into j from surveyor_jobs where id = p_id and company_id = sa_my_company_id();
  if j.id is null then return jsonb_build_object('ok', false, 'code', 'not_found', 'message', 'Job not found.'); end if;
  if j.assigned_user_id is distinct from auth.uid() then
    return jsonb_build_object('ok', false, 'code', 'not_assigned', 'message', 'Only the attending surveyor can open the form. Use "Resend link" to e-mail it.');
  end if;
  if j.status not in ('draft','open','in_progress') then
    return jsonb_build_object('ok', false, 'code', 'job_closed', 'message', 'This job is no longer open in the app.');
  end if;
  v_sid := sa_job_survey_ensure(j.id);
  select form_job_id into v_fj from surveys where id = v_sid;
  if v_fj is null or not exists (select 1 from form_jobs where id = v_fj and status in ('open','in_progress')) then
    r := gbqs_form_job_create(v_sid, 'surveyor', (select email from surveyor_company_users where user_id = auth.uid()), false);
    if not coalesce((r->>'ok')::boolean, false) then return r - 'token' - 'url'; end if;
    v_url := r->>'url';
    if v_url is null then v_url := gbqs_form_job_url((r->>'job_id')::uuid); end if;
    v_fj := coalesce((r->>'job_id')::uuid, (select form_job_id from surveys where id = v_sid));
  else
    v_url := gbqs_form_job_url(v_fj);
  end if;
  if v_url is null then return jsonb_build_object('ok', false, 'code', 'no_link', 'message', 'The link could not be created. Please try again.'); end if;

  -- eenmalige portaalcode (niet gemaild), 5 minuten geldig
  select * into fj from form_jobs where id = v_fj;
  if fj.id is not null and fj.surveyor_email is not null then
    v_code := lpad((('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint % 1000000)::text, 6, '0');
    insert into form_job_codes(job_id, email, code_hash, device_label, expires_at)
    values (fj.id, fj.surveyor_email, gbqs_form_hash(fj.id::text || ':' || v_code), 'Opened from the GlobalBQS portal', now() + interval '5 minutes');
    v_url := regexp_replace(v_url, '/j/([0-9a-f]{64})$', '/#/j/\1/pc/' || v_code);
  end if;
  return jsonb_build_object('ok', true, 'url', v_url);
end $function$;

