-- Own jobs of surveyors (surveys without an order) do not belong in GlobalBQS ops tiles or the hire-certificate queue.
do $mig$
declare d text; n int;
begin
  d := pg_get_functiondef('public.ops_dashboard_data(integer)'::regprocedure);
  d := replace(d, $q$(select count(*) from surveys where status = 'dispatched')$q$, $q$(select count(*) from surveys where status = 'dispatched' and order_id is not null)$q$);
  d := replace(d, $q$(select count(*) from surveys where status = 'confirmed')$q$, $q$(select count(*) from surveys where status = 'confirmed' and order_id is not null)$q$);
  d := replace(d, $q$(select count(*) from surveys where status = 'submitted')$q$, $q$(select count(*) from surveys where status = 'submitted' and order_id is not null)$q$);
  if (length(d) - length(replace(d, 'and order_id is not null', ''))) / length('and order_id is not null') <> 3 then
    raise exception 'ops_dashboard_data: expected 3 replacements';
  end if;
  execute d;

  d := pg_get_functiondef('public.hire_cert_ensure_case(uuid)'::regprocedure);
  if position('if s.order_id is null then return null; end if;' in d) = 0 then
    d := replace(d, $q$then return null; end if;
  select id into cid from hire_cert_cases$q$, $q$then return null; end if;
  if s.order_id is null then return null; end if;  -- own jobs of surveyors: no GlobalBQS certificate case
  select id into cid from hire_cert_cases$q$);
    if position('if s.order_id is null then return null; end if;' in d) = 0 then
      raise exception 'hire_cert_ensure_case: patch point not found';
    end if;
    execute d;
  end if;
end $mig$;

