-- portal: start a card purchase (office/admin of an approved company); the edge function then opens Stripe Checkout
create or replace function public.sa_checkout_prepare(p_bundle_code text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company uuid := sa_my_company_id(); c surveyor_companies; u surveyor_company_users; pr jsonb; v_id uuid; n int;
begin
  if v_company is null then return jsonb_build_object('ok', false, 'message', 'No surveyor company found for this account.'); end if;
  select * into c from surveyor_companies where id = v_company;
  select * into u from surveyor_company_users where company_id = v_company and user_id = auth.uid() and status = 'active';
  if u.user_id is null or not (coalesce(u.is_office, false) or coalesce(u.is_admin, false)) then
    return jsonb_build_object('ok', false, 'message', 'Only the office or the company admin can buy credits.');
  end if;
  if c.status <> 'approved' then
    return jsonb_build_object('ok', false, 'message', 'Buying credits opens as soon as our company check is done.');
  end if;
  pr := sa_bundle_price(v_company, p_bundle_code);
  if pr is null then return jsonb_build_object('ok', false, 'message', 'Unknown bundle.'); end if;
  select count(*) into n from sa_purchases where company_id = v_company and created_at > now() - interval '1 hour';
  if n >= 10 then return jsonb_build_object('ok', false, 'message', 'Too many attempts. Please try again in an hour.'); end if;
  insert into sa_purchases(company_id, bundle_code, credits, unit_usd, discount_pct, amount_usd, buyer_user_id, buyer_email)
  values (v_company, p_bundle_code, (pr->>'credits')::int, (pr->>'unit_usd')::numeric, (pr->>'discount_pct')::numeric,
          (pr->>'total_usd')::numeric, auth.uid(), coalesce(nullif(u.email, ''), (select email from auth.users where id = auth.uid())))
  returning id into v_id;
  return jsonb_build_object('ok', true, 'purchase_id', v_id, 'company_id', v_company, 'company_name', c.name,
    'bundle', p_bundle_code, 'label', (select label from sa_credit_bundles where code = p_bundle_code),
    'credits', (pr->>'credits')::int, 'unit_usd', (pr->>'unit_usd')::numeric, 'discount_pct', (pr->>'discount_pct')::numeric,
    'amount_cents', round((pr->>'total_usd')::numeric * 100)::int,
    'email', coalesce(nullif(u.email, ''), (select email from auth.users where id = auth.uid())),
    'portal_url', (select value from system_settings where key = 'portal_url'));
end $$;
revoke all on function public.sa_checkout_prepare(text) from public, anon;
grant execute on function public.sa_checkout_prepare(text) to authenticated, service_role;

-- edge function (service_role): Stripe session created
