$$;

-- webhook (service_role): paid → credits, exactly once; amount must match
create or replace function public.sa_purchase_paid(p_session text, p_payment_intent text, p_amount_cents integer, p_currency text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare p sa_purchases; g jsonb;
begin
  select * into p from sa_purchases where stripe_session_id = p_session for update;
  if p.id is null then return jsonb_build_object('ok', false, 'message', 'unknown session'); end if;
  if p.status = 'paid' then return jsonb_build_object('ok', true, 'duplicate', true, 'lot_id', p.lot_id); end if;
  if p_amount_cents is distinct from round(p.amount_usd * 100)::int or lower(coalesce(p_currency, '')) <> p.currency then
    update sa_purchases set status = 'failed', error = format('amount/currency mismatch: %s %s', p_amount_cents, p_currency), updated_at = now() where id = p.id;
    return jsonb_build_object('ok', false, 'message', 'amount mismatch');
  end if;
  g := sa_credit_grant(p.company_id, 'purchase', p.credits, p.unit_usd,
         format('Card payment – %s', (select label from sa_credit_bundles where code = p.bundle_code)),
         coalesce(p.buyer_email, 'stripe'), p.bundle_code, p_session);
  update sa_purchases set status = 'paid', paid_at = now(), stripe_payment_intent = p_payment_intent,
         lot_id = (g->>'lot_id')::uuid, error = null, updated_at = now() where id = p.id;
  return jsonb_build_object('ok', true, 'lot_id', g->>'lot_id', 'balance', g->'balance');
end $$;

create or replace function public.sa_purchase_set_status(p_session text, p_status text, p_error text default null)
returns void language sql security definer set search_path = public as $$
  update sa_purchases set status = p_status, error = coalesce(p_error, error), updated_at = now()
   where stripe_session_id = p_session and status = 'pending' and p_status in ('failed','expired','cancelled');
$$;

