-- VAT for a surveyor company (B2B): NL 21 % · EU with VAT number 0 % reverse charge · EU without VAT number 21 % · outside EU 0 % outside scope
create or replace function public.sa_vat_for_company(p_company uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare c surveyor_companies; v_cc text; v_nl numeric := coalesce(nullif((select value from system_settings where key = 'sa_vat_rate_nl'), '')::numeric, 21);
  v_eu text[] := array['AT','BE','BG','HR','CY','CZ','DK','EE','FI','FR','DE','GR','EL','HU','IE','IT','LV','LT','LU','MT','PL','PT','RO','SK','SI','ES','SE'];
begin
  if coalesce((select value from system_settings where key = 'sa_vat_mode'), 'off') <> 'by_country' then
    return jsonb_build_object('rate', 0, 'note', null, 'mode', 'off');
  end if;
  select * into c from surveyor_companies where id = p_company;
  v_cc := upper(trim(coalesce(c.country, '')));
  if v_cc in ('NL', 'NETHERLANDS', 'THE NETHERLANDS', 'NEDERLAND') then
    return jsonb_build_object('rate', v_nl, 'note', null, 'mode', 'nl');
  elsif v_cc = any(v_eu) then
    if nullif(trim(coalesce(c.vat_number, '')), '') is not null then
      return jsonb_build_object('rate', 0, 'note', 'VAT reverse charged (Article 196 EU VAT Directive). Customer VAT number: ' || trim(c.vat_number), 'mode', 'eu_reverse');
    end if;
    return jsonb_build_object('rate', v_nl, 'note', null, 'mode', 'eu_no_vat_number');
  elsif v_cc = '' then
    return jsonb_build_object('rate', v_nl, 'note', null, 'mode', 'unknown_country');
  end if;
  return jsonb_build_object('rate', 0, 'note', 'Outside the scope of Dutch VAT (service supplied to a business established outside the EU).', 'mode', 'non_eu');
end $$;
revoke all on function public.sa_vat_for_company(uuid) from public, anon;
grant execute on function public.sa_vat_for_company(uuid) to authenticated, service_role;

-- totals: VAT-aware (vat_rate null = no VAT, exactly as before)
create or replace function public.gbqs_recalc_invoice_total(p_invoice uuid)
returns void language sql security definer set search_path = public as $$
  update invoices i set
    net_amount = x.net,
    vat_amount = case when i.vat_rate is null then null else round(x.net * i.vat_rate / 100, 2) end,
    total_amount = x.net + case when i.vat_rate is null then 0 else round(x.net * i.vat_rate / 100, 2) end
  from (select coalesce((select sum(amount) from invoice_lines where invoice_id = p_invoice), 0)
             + coalesce((select sum(amount) from invoice_extra_lines where invoice_id = p_invoice), 0) as net) x
  where i.id = p_invoice;
$$;

-- checkout: price incl. VAT
create or replace function public.sa_checkout_prepare(p_bundle_code text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_company uuid := sa_my_company_id(); c surveyor_companies; u surveyor_company_users; pr jsonb; v_id uuid; n int;
  vat jsonb; v_net numeric; v_vat numeric; v_email text;
begin
  if v_company is null then return jsonb_build_object('ok', false, 'message', 'No surveyor company found for this account.'); end if;
  select * into c from surveyor_companies where id = v_company;
  select * into u from surveyor_company_users where company_id = v_company and user_id = auth.uid() and status = 'active';
  if u.user_id is null or not (coalesce(u.is_office, false) or coalesce(u.is_admin, false)) then
    return jsonb_build_object('ok', false, 'message', 'Only the office or the company admin can buy credits.');
  end if;
  if c.status <> 'approved' then
    return jsonb_build_object('ok', false, 'message', 'Buying credits opens as soon as our company check is done.');
  end if;
  pr := sa_bundle_price(v_company, p_bundle_code);
  if pr is null then return jsonb_build_object('ok', false, 'message', 'Unknown bundle.'); end if;
  select count(*) into n from sa_purchases where company_id = v_company and created_at > now() - interval '1 hour';
  if n >= 10 then return jsonb_build_object('ok', false, 'message', 'Too many attempts. Please try again in an hour.'); end if;
  vat := sa_vat_for_company(v_company);
  v_net := (pr->>'total_usd')::numeric;
  v_vat := round(v_net * (vat->>'rate')::numeric / 100, 2);
  v_email := coalesce(nullif(u.email, ''), (select email from auth.users where id = auth.uid()));
  insert into sa_purchases(company_id, bundle_code, credits, unit_usd, discount_pct, amount_usd, net_usd, vat_rate, vat_usd, vat_note, buyer_user_id, buyer_email)
  values (v_company, p_bundle_code, (pr->>'credits')::int, (pr->>'unit_usd')::numeric, (pr->>'discount_pct')::numeric,
          v_net + v_vat, v_net, (vat->>'rate')::numeric, v_vat, vat->>'note', auth.uid(), v_email)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'purchase_id', v_id, 'company_id', v_company, 'company_name', c.name,
    'bundle', p_bundle_code, 'label', (select label from sa_credit_bundles where code = p_bundle_code),
    'credits', (pr->>'credits')::int, 'unit_usd', (pr->>'unit_usd')::numeric, 'discount_pct', (pr->>'discount_pct')::numeric,
    'net_usd', v_net, 'vat_rate', (vat->>'rate')::numeric, 'vat_usd', v_vat,
    'amount_cents', round((v_net + v_vat) * 100)::int,
    'email', v_email,
    'portal_url', (select value from system_settings where key = 'portal_url'));
end $$;
revoke all on function public.sa_checkout_prepare(text) from public, anon;
grant execute on function public.sa_checkout_prepare(text) to authenticated, service_role;

-- invoice for a paid purchase (same INV-YYYY-NNNN series and lock as ops_create_invoice), then PDF + mail via generate-invoice-pdf
create or replace function public.sa_invoice_for_purchase(p_purchase uuid)
returns jsonb language plpgsql security definer set search_path = public, vault as $$
declare p sa_purchases; v_inv uuid; v_nr text; v_year text := to_char(now(), 'YYYY'); v_n int; tok text; v_label text;
begin
  select * into p from sa_purchases where id = p_purchase for update;
  if p.id is null or p.status <> 'paid' then return jsonb_build_object('ok', false, 'message', 'purchase not paid'); end if;
  if p.invoice_id is not null then return jsonb_build_object('ok', true, 'duplicate', true, 'invoice_id', p.invoice_id); end if;
  perform pg_advisory_xact_lock(hashtext('gbqs_invoice_number'));
  select coalesce(max(substring(invoice_number from '\d+$')::int), 0) + 1 into v_n from invoices where invoice_number like 'INV-' || v_year || '-%';
  v_nr := 'INV-' || v_year || '-' || lpad(v_n::text, 4, '0');
  select label into v_label from sa_credit_bundles where code = p.bundle_code;
  insert into invoices(invoice_number, client_id, surveyor_company_id, total_amount, vat_rate, vat_note, paid_at, payment_method, payment_ref, notes)
  values (v_nr, null, p.company_id, 0, coalesce(p.vat_rate, 0), p.vat_note, coalesce(p.paid_at, now()), 'card', p.stripe_session_id,
          'Surveyor credits paid by card (Stripe)')
  returning id into v_inv;
  insert into invoice_extra_lines(invoice_id, description, amount)
  values (v_inv, format('Survey credits - %s (%s x USD %s%s), valid 12 months', v_label, p.credits, to_char(p.unit_usd, 'FM999990.00'),
                        case when p.discount_pct > 0 then format(', %s%% agreed discount', trim(to_char(p.discount_pct, 'FM990.##'))) else '' end),
          coalesce(p.net_usd, p.amount_usd));
  perform gbqs_recalc_invoice_total(v_inv);
  update sa_purchases set invoice_id = v_inv, updated_at = now() where id = p.id;
  -- PDF + mail (Make invoice scenario, same as client invoices; on the demo the Make secret is absent → PDF only)
  begin
    select decrypted_secret into tok from vault.decrypted_secrets where name = 'gbqs_internal_invoke_token';
    perform net.http_post(
      url := (select coalesce(nullif(value, ''), '') from system_settings where key = 'supabase_functions_base') ,
      headers := jsonb_build_object('content-type', 'application/json'), body := '{}'::jsonb, timeout_milliseconds := 1000)
      where false;  -- placeholder never executed
    perform net.http_post(
      url := regexp_replace(current_setting('app.settings.functions_url', true), '/$', '') || '/generate-invoice-pdf',
      headers := jsonb_build_object('content-type', 'application/json', 'x-gbqs-token', tok),
      body := jsonb_build_object('invoice_id', v_inv, 'send', true), timeout_milliseconds := 20000)
      where current_setting('app.settings.functions_url', true) is not null;
  exception when others then null;
  end;
  return jsonb_build_object('ok', true, 'invoice_id', v_inv, 'invoice_number', v_nr);
end $$;
revoke all on function public.sa_invoice_for_purchase(uuid) from public, anon, authenticated;
grant execute on function public.sa_invoice_for_purchase(uuid) to service_role;

