-- Bundles of 25/100 by invoice (bank transfer): request in the portal -> unpaid surveyor invoice, mailed;
-- ops marks it paid in Retool -> credits granted automatically. Backwards compatible: card flow unchanged.
insert into system_settings(key, value) values ('sa_invoice_term_days', '14') on conflict (key) do nothing;

-- invoice for a purchase: card (paid) as before, or invoice method (pending, unpaid)
create or replace function public.sa_invoice_for_purchase(p_purchase uuid)
 returns jsonb language plpgsql security definer set search_path to 'public', 'vault'
as $function$
declare p sa_purchases; v_inv uuid; v_nr text; v_year text := to_char(now(), 'YYYY'); v_n int; tok text; v_label text; v_base text;
begin
  select * into p from sa_purchases where id = p_purchase for update;
  if p.id is null then return jsonb_build_object('ok', false, 'message', 'unknown purchase'); end if;
  if not (p.status = 'paid' or (p.method = 'invoice' and p.status = 'pending')) then
    return jsonb_build_object('ok', false, 'message', 'purchase not paid');
  end if;
  if p.invoice_id is not null then return jsonb_build_object('ok', true, 'duplicate', true, 'invoice_id', p.invoice_id); end if;
  perform pg_advisory_xact_lock(hashtext('gbqs_invoice_number'));
  select coalesce(max(substring(invoice_number from '\d+$')::int), 0) + 1 into v_n from invoices where invoice_number like 'INV-' || v_year || '-%';
  v_nr := 'INV-' || v_year || '-' || lpad(v_n::text, 4, '0');
  select label into v_label from sa_credit_bundles where code = p.bundle_code;
  insert into invoices(invoice_number, client_id, surveyor_company_id, total_amount, vat_rate, vat_note, paid_at, payment_method, payment_ref, notes)
  values (v_nr, null, p.company_id, 0, coalesce(p.vat_rate, 0), p.vat_note,
          case when p.method = 'card' then coalesce(p.paid_at, now()) end,
          p.method, case when p.method = 'card' then p.stripe_session_id end,
          case when p.method = 'card' then 'Surveyor credits paid by card (Stripe)'
               else 'Surveyor credits - payment by bank transfer; credits are added automatically when marked paid' end)
  returning id into v_inv;
  insert into invoice_extra_lines(invoice_id, description, amount)
  values (v_inv, format('Survey credits - %s (%s x USD %s%s), valid 12 months', v_label, p.credits, to_char(p.unit_usd, 'FM999990.00'),
                        case when p.discount_pct > 0 then format(', %s%% agreed discount', trim(to_char(p.discount_pct, 'FM990.##'))) else '' end),
          coalesce(p.net_usd, p.amount_usd));
  perform gbqs_recalc_invoice_total(v_inv);
  update sa_purchases set invoice_id = v_inv, updated_at = now() where id = p.id;
  v_base := gbqs_functions_base();
  if v_base is not null then
    begin
      select decrypted_secret into tok from vault.decrypted_secrets where name = 'gbqs_internal_invoke_token';
      perform net.http_post(url := v_base || '/generate-invoice-pdf',
        headers := jsonb_build_object('content-type', 'application/json', 'x-gbqs-token', tok),
        body := jsonb_build_object('invoice_id', v_inv, 'send', true), timeout_milliseconds := 20000);
    exception when others then null;
    end;
  end if;
  return jsonb_build_object('ok', true, 'invoice_id', v_inv, 'invoice_number', v_nr);
end $function$;

-- portal: request an invoice for a bundle that allows it (25 / 100)
create or replace function public.sa_invoice_request(p_bundle_code text)
 returns jsonb language plpgsql security definer set search_path to 'public'
as $function$
declare v_company uuid := sa_my_company_id(); c surveyor_companies; u surveyor_company_users; pr jsonb; v_id uuid; n int;
  vat jsonb; v_net numeric; v_vat numeric; v_email text; inv jsonb; v_open text;
begin
  if v_company is null then return jsonb_build_object('ok', false, 'message', 'No surveyor company found for this account.'); end if;
  select * into c from surveyor_companies where id = v_company;
  select * into u from surveyor_company_users where company_id = v_company and user_id = auth.uid() and status = 'active';
  if u.user_id is null or not (coalesce(u.is_office, false) or coalesce(u.is_admin, false)) then
    return jsonb_build_object('ok', false, 'message', 'Only the office or the company admin can buy credits.');
  end if;
  if c.status <> 'approved' then
    return jsonb_build_object('ok', false, 'message', 'Buying credits opens as soon as our company check is done.');
  end if;
  pr := sa_bundle_price(v_company, p_bundle_code);
  if pr is null then return jsonb_build_object('ok', false, 'message', 'Unknown bundle.'); end if;
  if not coalesce((pr->>'invoice_allowed')::boolean, false) then
    return jsonb_build_object('ok', false, 'message', 'This bundle can only be paid by card.');
  end if;
  select i.invoice_number into v_open from sa_purchases p join invoices i on i.id = p.invoice_id
   where p.company_id = v_company and p.method = 'invoice' and p.status = 'pending' and i.paid_at is null
   order by p.created_at desc limit 1;
  if v_open is not null then
    return jsonb_build_object('ok', false, 'message',
      format('Invoice %s is still open. As soon as it is paid, the credits are added and you can request a new one.', v_open));
  end if;
  select count(*) into n from sa_purchases where company_id = v_company and created_at > now() - interval '1 hour';
  if n >= 10 then return jsonb_build_object('ok', false, 'message', 'Too many attempts. Please try again in an hour.'); end if;
  vat := sa_vat_for_company(v_company);
  v_net := (pr->>'total_usd')::numeric;
  v_vat := round(v_net * (vat->>'rate')::numeric / 100, 2);
  v_email := coalesce(nullif(u.email, ''), (select email from auth.users where id = auth.uid()));
  insert into sa_purchases(company_id, bundle_code, credits, unit_usd, discount_pct, amount_usd, net_usd, vat_rate, vat_usd, vat_note,
                           buyer_user_id, buyer_email, method, status)
  values (v_company, p_bundle_code, (pr->>'credits')::int, (pr->>'unit_usd')::numeric, (pr->>'discount_pct')::numeric,
          v_net + v_vat, v_net, (vat->>'rate')::numeric, v_vat, vat->>'note', auth.uid(), v_email, 'invoice', 'pending')
  returning id into v_id;
  inv := sa_invoice_for_purchase(v_id);
  if not coalesce((inv->>'ok')::boolean, false) then
    raise exception 'invoice could not be created: %', inv->>'message';
  end if;
  return jsonb_build_object('ok', true, 'purchase_id', v_id, 'invoice_id', inv->>'invoice_id', 'invoice_number', inv->>'invoice_number',
    'credits', (pr->>'credits')::int, 'total_usd', v_net + v_vat,
    'mailed_to', coalesce(nullif(trim(c.invoice_email), ''), nullif(trim(c.office_email), '')),
    'term_days', sa_setting_int('sa_invoice_term_days', 14));
end $function$;
revoke all on function public.sa_invoice_request(text) from public, anon;
grant execute on function public.sa_invoice_request(text) to authenticated;

-- ops marks a surveyor invoice paid -> credits granted; a paid surveyor invoice cannot be set back to unpaid
create or replace function public.sa_invoice_paid_trg()
 returns trigger language plpgsql security definer set search_path to 'public'
as $function$
declare p sa_purchases; g jsonb;
begin
  if new.surveyor_company_id is null then return new; end if;
  if tg_op = 'UPDATE' and old.paid_at is not null and new.paid_at is null then
    raise exception 'A paid surveyor credit invoice cannot be set back to unpaid: the credits have already been added. Correct it with a credit adjustment instead.';
  end if;
  if old.paid_at is null and new.paid_at is not null then
    for p in select * from sa_purchases where invoice_id = new.id and method = 'invoice' and status = 'pending' for update loop
      g := sa_credit_grant(p.company_id, 'purchase', p.credits, p.unit_usd,
             format('Invoice %s paid – %s', new.invoice_number, (select label from sa_credit_bundles where code = p.bundle_code)),
             coalesce(current_setting('request.jwt.claims', true)::jsonb->>'email', 'ops'), p.bundle_code, new.invoice_number);
      update sa_purchases set status = 'paid', paid_at = new.paid_at, lot_id = (g->>'lot_id')::uuid, error = null, updated_at = now()
       where id = p.id;
    end loop;
  end if;
  return new;
end $function$;
drop trigger if exists trg_sa_invoice_paid on public.invoices;
create trigger trg_sa_invoice_paid before update of paid_at on public.invoices
  for each row execute function public.sa_invoice_paid_trg();

