create or replace function public.ops_sa_set_company_status(p_id uuid, p_status text, p_by text, p_note text DEFAULT NULL::text, p_mail boolean DEFAULT true)
 returns jsonb language plpgsql security definer set search_path to 'public'
as $function$
declare v_old text; r jsonb; c surveyor_companies; v_to text; v_url text; v_body text; v_credits int;
begin
  select status into v_old from surveyor_companies where id = p_id;
  if v_old is null then return jsonb_build_object('ok', false, 'message', 'Bedrijf niet gevonden.'); end if;
  if p_status in ('suspended','blocked') and coalesce(trim(p_note), '') = '' then
    return jsonb_build_object('ok', false, 'message', 'Geef een reden op bij schorsen of blokkeren.');
  end if;
  r := sa_ops_set_company_status(p_id, p_status, p_by, nullif(trim(coalesce(p_note, '')), ''));
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  if p_status = 'approved' and v_old <> 'approved' and p_mail then
    select * into c from surveyor_companies where id = p_id;
    select string_agg(distinct u.email, ',') into v_to from surveyor_company_users u where u.company_id = p_id and u.is_admin and u.status = 'active';
    v_url := coalesce(nullif((select value from system_settings where key = 'portal_url'), ''), 'https://portal.globalbqs.com');
    v_credits := sa_credit_balance(p_id);
    if v_to is not null then
      v_body := '<p style="margin:0 0 12px;">Good news: we have checked <strong>' || replace(replace(c.name, '<', '&lt;'), '>', '&gt;')
        || '</strong> and your company is now approved on GlobalBQS.</p>'
        || '<p style="margin:0 0 12px;">You can create jobs, issue reports with your own logo and buy credits in the portal.'
        || case when v_credits > 0 then ' You have <strong>' || v_credits || ' credit' || case when v_credits = 1 then '' else 's' end || '</strong> available.' else '' end
        || ' Your rating starts to build up from your issued surveys.</p>'
        || '<p style="margin:0 0 16px;">' || gbqs_mail_btn(v_url || '/surveyor', 'Open the portal', 'primary') || '</p>'
        || sa_legal_links_html()
        || '<p style="margin:0;color:#5c6b85;font-size:12px;line-height:18px;">Questions? Reply to this e-mail or call us at +31 10 340 0240.</p>';
      perform gbqs_send_mail_ext(v_to, 'Your company is approved on GlobalBQS', gbqs_mail_wrap('SURVEYOR ACCESS', v_body),
                                 nullif(c.office_email, ''), 'surveyors@globalbqs.com');
      r := r || jsonb_build_object('mailed_to', v_to);
    end if;
  end if;
  return r || jsonb_build_object('message', case p_status when 'approved' then 'Bedrijf goedgekeurd.' when 'suspended' then 'Bedrijf geschorst.'
                                  when 'blocked' then 'Bedrijf geblokkeerd.' else 'Status teruggezet naar Te controleren.' end);
end $function$;

-- GCS: monthly evaluation no longer takes conditional/revoked decisions itself (art. 22 GDPR, decision 09-11):
-- it creates a proposal that ops confirms or rejects in Retool. Awarding, restoring and extending stay automatic;
-- revocation after suspension/blocking by ops stays immediate (that is already a human decision).
create table if not exists public.surveyor_certification_proposals (
  id uuid primary key default gen_random_uuid(),
  surveyor_id uuid not null references public.surveyors(id) on delete cascade,
  from_status text not null,
  to_status text not null check (to_status in ('conditional','revoked')),
  reason text,
  score numeric, surveys int, vessels int,
  status text not null default 'open' check (status in ('open','approved','rejected','superseded')),
  created_at timestamptz not null default now(),
  created_by text,
  decided_at timestamptz, decided_by text, decision_note text,
  updated_at timestamptz not null default now()
);
create unique index if not exists surveyor_cert_proposals_one_open on public.surveyor_certification_proposals(surveyor_id) where status = 'open';
alter table public.surveyor_certification_proposals enable row level security;
revoke all on public.surveyor_certification_proposals from public, anon, authenticated;
grant select, insert, update, delete on public.surveyor_certification_proposals to service_role;

-- open (or refresh) a proposal; returns true when a new one was created
create or replace function public.gbqs_gcs_propose(p_surveyor_id uuid, p_from text, p_to text, p_reason text, p_by text,
                                                   p_score numeric, p_surveys int, p_vessels int)
 returns boolean language plpgsql security definer set search_path to 'public'
as $function$
declare p surveyor_certification_proposals;
begin
  select * into p from surveyor_certification_proposals where surveyor_id = p_surveyor_id and status = 'open' for update;
  if p.id is not null then
    if p.to_status = p_to then
      update surveyor_certification_proposals set reason = p_reason, score = p_score, surveys = p_surveys, vessels = p_vessels, updated_at = now()
       where id = p.id;
      return false;
    end if;
    update surveyor_certification_proposals set status = 'superseded', decided_at = now(), decided_by = p_by,
           decision_note = 'replaced by a new proposal', updated_at = now() where id = p.id;
  end if;
  insert into surveyor_certification_proposals(surveyor_id, from_status, to_status, reason, score, surveys, vessels, created_by)
  values (p_surveyor_id, p_from, p_to, p_reason, p_score, p_surveys, p_vessels, p_by);
  return true;
end $function$;

create or replace function public.gbqs_gcs_close_proposals(p_surveyor_id uuid, p_note text, p_by text)
 returns void language sql security definer set search_path to 'public'
as $function$
  update surveyor_certification_proposals set status = 'superseded', decided_at = now(), decided_by = p_by,
         decision_note = p_note, updated_at = now()
   where surveyor_id = p_surveyor_id and status = 'open';
$function$;

create or replace function public.gbqs_gcs_evaluate(p_by text DEFAULT 'monthly'::text, p_mail boolean DEFAULT true)
 returns jsonb language plpgsql security definer set search_path to 'public'
as $function$
declare f record; c surveyor_certifications; r jsonb; v_out jsonb := '[]'::jsonb; v_props jsonb := '[]'::jsonb; v_n int := 0; v_reason text;
  v_to text; v_html text;
begin
  if p_by = 'monthly' and coalesce((select value from system_settings where key = 'gcs_evaluation_enabled'), 'false') <> 'true' then
    return jsonb_build_object('ok', true, 'skipped', 'gcs_evaluation_enabled is not true');
  end if;
  for f in select * from gbqs_gcs_facts() loop
    v_n := v_n + 1;
    select * into c from surveyor_certifications where surveyor_id = f.surveyor_id;
    v_reason := case when array_length(f.missing, 1) is null then null else
      array_to_string(array(select case m when 'surveys' then 'too few surveys' when 'vessels' then 'too few different vessels'
                                         when 'score' then 'rating below the minimum' when 'deployment' then 'not active'
                                         when 'company_check' then 'company not checked' else m end
                              from unnest(f.missing) m), ', ') end;
    r := null;
    if c.status in ('certified', 'conditional') and f.blocked then
      -- suspended/blocked by ops = human decision: revoke at once (normally already done by the trigger)
      r := gbqs_gcs_set(f.surveyor_id, 'revoked', 'suspended or blocked', p_by, f.score, f.surveys, f.vessels, p_mail);
      perform gbqs_gcs_close_proposals(f.surveyor_id, 'revoked after suspension/blocking', p_by);
    elsif coalesce(c.status, 'candidate') in ('candidate', 'revoked') and f.eligible then
      r := gbqs_gcs_set(f.surveyor_id, 'certified', 'criteria met', p_by, f.score, f.surveys, f.vessels, p_mail);
    elsif c.status = 'certified' and not f.eligible then
      if gbqs_gcs_propose(f.surveyor_id, 'certified', 'conditional', v_reason, p_by, f.score, f.surveys, f.vessels) then
        v_props := v_props || jsonb_build_object('surveyor', f.name, 'to', 'conditional', 'reason', v_reason);
      end if;
    elsif c.status = 'certified' and f.eligible then
      update surveyor_certifications set valid_until = now() + interval '12 months', updated_at = now() where surveyor_id = f.surveyor_id;
      perform gbqs_gcs_close_proposals(f.surveyor_id, 'criteria met again before a decision', p_by);
    elsif c.status = 'conditional' and f.eligible and not f.watch then
      r := gbqs_gcs_set(f.surveyor_id, 'certified', 'criteria met again', p_by, f.score, f.surveys, f.vessels, p_mail);
      perform gbqs_gcs_close_proposals(f.surveyor_id, 'criteria met again before a decision', p_by);
    elsif c.status = 'conditional' and now() >= c.conditional_deadline then
      if gbqs_gcs_propose(f.surveyor_id, 'conditional', 'revoked', coalesce(v_reason, 'not restored within the grace period'), p_by, f.score, f.surveys, f.vessels) then
        v_props := v_props || jsonb_build_object('surveyor', f.name, 'to', 'revoked', 'reason', coalesce(v_reason, 'not restored within the grace period'));
      end if;
    end if;
    if c.surveyor_id is not null or f.surveys > 0 then
      insert into surveyor_certifications(surveyor_id) values (f.surveyor_id) on conflict (surveyor_id) do nothing;
      update surveyor_certifications set last_evaluated_at = now(), last_score = f.score, last_surveys = f.surveys, last_vessels = f.vessels
       where surveyor_id = f.surveyor_id;
    end if;
    if r is not null and coalesce((r->>'changed')::boolean, false) then
      v_out := v_out || jsonb_build_object('surveyor', f.name, 'from', r->>'from', 'to', r->>'status', 'cert_number', r->>'cert_number');
    end if;
  end loop;
  -- one notice to ops for new proposals
  if jsonb_array_length(v_props) > 0 and p_mail then
    begin
      v_to := coalesce(nullif((select value from system_settings where key = 'notify_email'), ''), 'reports@globalbqs.com');
      select string_agg('<li>' || gbqs_h(x->>'surveyor') || ' &rarr; <strong>' || (x->>'to') || '</strong> (' || gbqs_h(coalesce(x->>'reason','-')) || ')</li>', '')
        into v_html from jsonb_array_elements(v_props) x;
      perform gbqs_send_mail(v_to, 'ACTION: GCS proposals to confirm (' || jsonb_array_length(v_props) || ')',
        gbqs_mail_wrap('GCS EVALUATION', '<p style="margin:0 0 12px;">The monthly GCS evaluation proposes the following status changes. Nothing has been changed or mailed to the surveyors yet.</p><ul>' || v_html
          || '</ul><p style="margin:0;">Confirm or reject each proposal in the ops app (Surveyors &rsaquo; Certifications).</p>'));
    exception when others then null;
    end;
  end if;
  return jsonb_build_object('ok', true, 'evaluated', v_n, 'changes', v_out, 'proposals', v_props);
end $function$;

-- ops decides on a proposal
create or replace function public.ops_gcs_proposal_decide(p_id uuid, p_approve boolean, p_note text, p_by text)
 returns jsonb language plpgsql security definer set search_path to 'public'
as $function$
declare p surveyor_certification_proposals; c surveyor_certifications; r jsonb; v_reason text;
begin
  select * into p from surveyor_certification_proposals where id = p_id for update;
  if p.id is null then return jsonb_build_object('ok', false, 'message', 'Voorstel niet gevonden.'); end if;
  if p.status <> 'open' then return jsonb_build_object('ok', false, 'message', 'Dit voorstel is al afgehandeld.'); end if;
  select * into c from surveyor_certifications where surveyor_id = p.surveyor_id;
  if not p_approve then
    if coalesce(trim(p_note), '') = '' then return jsonb_build_object('ok', false, 'message', 'Geef een reden op bij afwijzen (intern).'); end if;
    update surveyor_certification_proposals set status = 'rejected', decided_at = now(), decided_by = p_by, decision_note = trim(p_note), updated_at = now()
     where id = p.id;
    insert into surveyor_certification_events(surveyor_id, from_status, to_status, reason, score, surveys, vessels, cert_number, created_by)
    values (p.surveyor_id, c.status, c.status, 'proposal ' || p.to_status || ' rejected: ' || trim(p_note), p.score, p.surveys, p.vessels, c.cert_number, p_by);
    return jsonb_build_object('ok', true, 'message', 'Voorstel afgewezen; status blijft ' || coalesce(c.status, 'candidate') || '.');
  end if;
  if coalesce(c.status, 'candidate') <> p.from_status then
    update surveyor_certification_proposals set status = 'superseded', decided_at = now(), decided_by = p_by,
           decision_note = 'status changed in the meantime', updated_at = now() where id = p.id;
    return jsonb_build_object('ok', false, 'message', 'De status is intussen gewijzigd (' || coalesce(c.status, 'candidate') || '); voorstel vervallen.');
  end if;
  v_reason := coalesce(nullif(trim(p_note), ''), p.reason);
  r := gbqs_gcs_set(p.surveyor_id, p.to_status, v_reason, p_by, p.score, p.surveys, p.vessels, true);
  if not coalesce((r->>'ok')::boolean, false) then return r; end if;
  update surveyor_certification_proposals set status = 'approved', decided_at = now(), decided_by = p_by, decision_note = nullif(trim(p_note), ''), updated_at = now()
   where id = p.id;
  return r || jsonb_build_object('message', 'Bevestigd: status ' || p.to_status || '; de surveyor is gemaild.');
end $function$;
revoke all on function public.ops_gcs_proposal_decide(uuid, boolean, text, text) from public, anon, authenticated;
revoke all on function public.gbqs_gcs_propose(uuid, text, text, text, text, numeric, int, int) from public, anon, authenticated;
revoke all on function public.gbqs_gcs_close_proposals(uuid, text, text) from public, anon, authenticated;

create or replace view public.ops_gcs_proposals as
  select p.id, p.surveyor_id, s.name, s.email, co.name as company_name, p.from_status, p.to_status, p.reason,
         p.score, p.surveys, p.vessels, p.status, p.created_at, p.created_by, p.decided_at, p.decided_by, p.decision_note,
         c.cert_number, c.conditional_deadline
    from surveyor_certification_proposals p
    join surveyors s on s.id = p.surveyor_id
    left join surveyor_companies co on co.id = s.company_id
    left join surveyor_certifications c on c.surveyor_id = p.surveyor_id;
revoke all on public.ops_gcs_proposals from public, anon, authenticated;
grant select on public.ops_gcs_proposals to service_role;

-- certifications overview: open proposal appended (backwards compatible)
create or replace view public.ops_surveyor_certifications as
 SELECT f.surveyor_id, f.name, f.company_id, co.name AS company_name, COALESCE(c.status, 'candidate'::text) AS status,
    c.cert_number, c.certified_since, c.valid_until, c.conditional_deadline, c.revoked_at, c.reason,
    f.surveys, f.vessels, f.score, f.eligible, f.missing, c.last_evaluated_at,
    p.id AS proposal_id, p.to_status AS proposal_to, p.reason AS proposal_reason, p.created_at AS proposal_created_at
   FROM gbqs_gcs_facts() f(surveyor_id, name, email, company_id, surveys, vessels, score, active, company_ok, blocked, watch, eligible, missing)
     LEFT JOIN surveyor_certifications c ON c.surveyor_id = f.surveyor_id
     LEFT JOIN surveyor_companies co ON co.id = f.company_id
     LEFT JOIN surveyor_certification_proposals p ON p.surveyor_id = f.surveyor_id AND p.status = 'open';

create table if not exists public.sa_proposal_grants (
  id uuid primary key default gen_random_uuid(),
  proposal_id uuid references public.crm_proposals(id) on delete set null,
  proposal_number text,
  crm_company_id uuid,
  email text not null,
  domain text,
  company_name text,
  discount_pct numeric check (discount_pct is null or (discount_pct > 0 and discount_pct <= 15)),
  valid_until date,
  preapproved boolean not null default true,
  invite_sent_at timestamptz,
  applied_company_id uuid references public.surveyor_companies(id) on delete set null,
  applied_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);
alter table public.sa_proposal_grants enable row level security;
revoke all on public.sa_proposal_grants from anon, authenticated;
grant select, insert, update, delete on public.sa_proposal_grants to service_role;
comment on table public.sa_proposal_grants is 'A15: afspraken uit getekende voorstellen Surveyor access, toegepast bij (of na) aanmelden van het surveybedrijf.';

create or replace function public.sa_proposal_grant_find(p_email text, p_domain text)
returns public.sa_proposal_grants language sql stable security definer set search_path to 'public' as $$
  select g.* from sa_proposal_grants g
   where g.applied_at is null and g.revoked_at is null
     and (g.email = lower(trim(coalesce(p_email,'')))
          or (g.domain is not null and g.domain = lower(trim(coalesce(p_domain,'')))))
   order by g.created_at desc limit 1
$$;

create or replace function public.sa_proposal_grant_apply(p_grant uuid, p_company uuid)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare g sa_proposal_grants; c surveyor_companies; v_by text; r jsonb := '{}'::jsonb;
begin
  select * into g from sa_proposal_grants where id = p_grant for update;
  select * into c from surveyor_companies where id = p_company;
  if g.id is null or c.id is null then return jsonb_build_object('ok', false, 'message', 'Afspraak of bedrijf niet gevonden.'); end if;
  if g.applied_at is not null then return jsonb_build_object('ok', true, 'already', true); end if;
  v_by := 'Voorstel ' || coalesce(g.proposal_number, '?');
  if g.discount_pct is not null and (g.valid_until is null or g.valid_until >= current_date) then
    update sa_price_agreements set revoked_at = now() where company_id = c.id and revoked_at is null;
    insert into sa_price_agreements(company_id, discount_pct, valid_until, source, proposal_id, created_by)
    values (c.id, g.discount_pct, g.valid_until, 'proposal', g.proposal_id, v_by);
    r := r || jsonb_build_object('discount_pct', g.discount_pct, 'valid_until', g.valid_until);
  end if;
  if not c.early_bird then update surveyor_companies set early_bird = true, updated_at = now() where id = c.id; end if;
  if g.preapproved and c.status = 'pending' then
    r := r || jsonb_build_object('approved', sa_ops_set_company_status(c.id, 'approved', v_by, v_by || ' getekend – vooraf goedgekeurd'));
  end if;
  update sa_proposal_grants set applied_company_id = c.id, applied_at = now() where id = g.id;
  if g.crm_company_id is not null then
    insert into crm_activities(company_id, type, title, summary, created_by)
    values (g.crm_company_id, 'proposal', 'Surveyor access gekoppeld aan ' || c.name,
            coalesce('Korting ' || g.discount_pct || '%' || coalesce(' t/m ' || to_char(g.valid_until, 'DD-MM-YYYY'), ''), 'Geen korting')
            || case when g.preapproved then ' · bedrijf goedgekeurd' else '' end, v_by);
  end if;
  return jsonb_build_object('ok', true, 'company_id', c.id) || r;
end $$;

create or replace function public.sa_proposal_grant_invite(p_grant uuid)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare g sa_proposal_grants; v_url text; v_body text; v_name text;
begin
  select * into g from sa_proposal_grants where id = p_grant;
  if g.id is null then return jsonb_build_object('ok', false); end if;
  if coalesce((select value from system_settings where key = 'sa_signup_open'), 'false') <> 'true' then
    return jsonb_build_object('ok', false, 'code', 'signup_closed');
  end if;
  v_url := coalesce(nullif((select value from system_settings where key = 'portal_url'), ''), 'https://portal.globalbqs.com');
  v_name := replace(replace(coalesce(g.company_name, 'your company'), '<', '&lt;'), '>', '&gt;');
  v_body := '<p style="margin:0 0 12px;">Thank you for signing our proposal' || coalesce(' <strong>' || g.proposal_number || '</strong>', '')
    || '. Welcome to GlobalBQS!</p>'
    || '<p style="margin:0 0 12px;">You can now create the account for <strong>' || v_name || '</strong>. '
    || 'Please sign up with <strong>' || g.email || '</strong>' || case when g.domain is not null then ' (or another address @' || g.domain || ')' else '' end
    || ', so the terms we agreed are applied automatically:</p>'
    || '<ul style="margin:0 0 12px;padding-left:20px;">'
    || '<li>your company is approved straight away – no waiting for our company check</li>'
    || '<li>three free surveys to start with</li>'
    || coalesce('<li>' || trim(to_char(g.discount_pct, 'FM990.##')) || '% discount on credit bundles'
                || coalesce(' until ' || to_char(g.valid_until, 'DD Mon YYYY'), '') || '</li>', '')
    || '</ul>'
    || '<p style="margin:0 0 16px;">' || gbqs_mail_btn(v_url || '/surveyor-signup', 'Create your account', 'primary') || '</p>'
    || sa_legal_links_html()
    || '<p style="margin:0;color:#5c6b85;font-size:12px;line-height:18px;">Questions? Reply to this e-mail or call us at +31 10 340 0240.</p>';
  perform gbqs_send_mail_ext(g.email, 'Create your GlobalBQS surveyor account', gbqs_mail_wrap('SURVEYOR ACCESS', v_body),
                             null, 'surveyors@globalbqs.com');
  update sa_proposal_grants set invite_sent_at = now() where id = g.id;
  return jsonb_build_object('ok', true, 'mailed_to', g.email);
end $$;

create or replace function public.sa_proposal_grant_on_accept(p_proposal uuid)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare pr crm_proposals; v crm_proposal_versions; d jsonb; v_email text; v_dom text; v_free boolean;
        v_pct numeric; g sa_proposal_grants; v_co uuid; r jsonb;
begin
  select * into pr from crm_proposals where id = p_proposal;
  if pr.id is null or pr.audience <> 'surveyor' then return jsonb_build_object('ok', false, 'code', 'not_surveyor'); end if;
  if exists (select 1 from sa_proposal_grants where proposal_id = pr.id) then return jsonb_build_object('ok', true, 'already', true); end if;
  select * into v from crm_proposal_versions where proposal_id = pr.id and version = coalesce(pr.accepted_version, pr.current_version);
  d := coalesce(v.data, '{}'::jsonb);
  v_email := lower(trim(coalesce(nullif(v.signer_email, ''), (select email from crm_contacts where id = pr.contact_id))));
  if coalesce(v_email, '') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then return jsonb_build_object('ok', false, 'code', 'no_email'); end if;
  v_dom := split_part(v_email, '@', 2);
  v_free := exists (select 1 from sa_free_mail_domains where domain = v_dom);
  v_pct := nullif(coalesce(nullif(d->>'discount_pct', ''), nullif(d->>'bundle_discount_pct', ''))::numeric, 0);
  if v_pct is not null then v_pct := least(greatest(v_pct, 0.01), 15); end if;
  insert into sa_proposal_grants(proposal_id, proposal_number, crm_company_id, email, domain, company_name, discount_pct, valid_until, preapproved)
  values (pr.id, pr.number, pr.company_id, v_email, case when v_free then null else v_dom end,
          (select name from crm_companies where id = pr.company_id), v_pct, nullif(d->>'discount_until', '')::date, true)
  returning * into g;
  select c.id into v_co from surveyor_companies c
   where c.status <> 'blocked'
     and ((not v_free and c.domain = v_dom)
          or lower(c.office_email) = v_email
          or exists (select 1 from surveyor_company_users u where u.company_id = c.id and lower(u.email) = v_email))
   order by c.created_at limit 1;
  if v_co is not null then
    r := sa_proposal_grant_apply(g.id, v_co);
  else
    r := sa_proposal_grant_invite(g.id);
  end if;
  return jsonb_build_object('ok', true, 'grant_id', g.id, 'result', r);
end $$;

create or replace function public.sa_proposal_accept_trg()
returns trigger language plpgsql security definer set search_path to 'public' as $$
begin
  if new.status = 'accepted' and coalesce(old.status, '') <> 'accepted' and new.audience = 'surveyor' then
    begin
      perform sa_proposal_grant_on_accept(new.id);
    exception when others then
      insert into crm_activities(company_id, type, title, summary, created_by)
      values (new.company_id, 'proposal', 'Surveyor access: koppeling na tekenen mislukt', left(sqlerrm, 300), 'systeem');
    end;
  end if;
  return new;
end $$;
drop trigger if exists trg_sa_proposal_accept on public.crm_proposals;
create trigger trg_sa_proposal_accept after update of status on public.crm_proposals
  for each row execute function public.sa_proposal_accept_trg();

create or replace function public.sa_company_grant_before_trg()
returns trigger language plpgsql security definer set search_path to 'public' as $$
declare g sa_proposal_grants;
begin
  g := sa_proposal_grant_find(new.office_email, new.domain);
  if g.id is not null then
    new.early_bird := true;
    if g.preapproved and new.status = 'pending' then
      new.status := 'approved'; new.verified_at := now(); new.verified_by := 'Voorstel ' || coalesce(g.proposal_number, '?');
    end if;
  end if;
  return new;
end $$;
create or replace function public.sa_company_grant_after_trg()
returns trigger language plpgsql security definer set search_path to 'public' as $$
declare g sa_proposal_grants;
begin
  g := sa_proposal_grant_find(new.office_email, new.domain);
  if g.id is not null then perform sa_proposal_grant_apply(g.id, new.id); end if;
  return new;
exception when others then return new;
end $$;
drop trigger if exists trg_sa_company_grant_before on public.surveyor_companies;
create trigger trg_sa_company_grant_before before insert on public.surveyor_companies
  for each row execute function public.sa_company_grant_before_trg();
drop trigger if exists trg_sa_company_grant_after on public.surveyor_companies;
create trigger trg_sa_company_grant_after after insert on public.surveyor_companies
  for each row execute function public.sa_company_grant_after_trg();

create or replace function public.sa_notify_new_company()
returns trigger language plpgsql security definer set search_path to 'public' as $$
declare v_to text := coalesce(nullif((select value from system_settings where key = 'notify_email'), ''), 'reports@globalbqs.com');
        v_pre boolean := new.status = 'approved';
begin
  perform gbqs_send_mail(v_to,
    case when v_pre then 'New surveyor sign-up (pre-approved – ' || coalesce(new.verified_by, 'proposal') || '): '
         else 'New surveyor sign-up – check company: ' end || coalesce(new.name, '?'),
    format(case when v_pre then '<p>A new surveyor company signed up. It was <b>pre-approved</b> because it signed a proposal (%s); no company check needed.</p>'
                else '<p>A new surveyor company signed up and is waiting for the company check.%s</p>' end
        || '<table cellpadding="4" style="font-family:Arial,sans-serif;font-size:14px">'
        || '<tr><td><b>Company</b></td><td>%s</td></tr><tr><td><b>Country</b></td><td>%s</td></tr>'
        || '<tr><td><b>Domain</b></td><td>%s</td></tr><tr><td><b>Website</b></td><td>%s</td></tr>'
        || '<tr><td><b>Early registration</b></td><td>%s</td></tr></table>'
        || case when v_pre then '' else '<p>Approve or reject in the ops app (Surveyors › To check). The surveyor was told: up to two working days.</p>' end,
        case when v_pre then coalesce(new.verified_by, '-') else '' end,
        coalesce(replace(replace(new.name,'<','&lt;'),'>','&gt;'),'–'), coalesce(new.country,'–'),
        coalesce(new.domain,'free e-mail address – credits after check'), coalesce(new.website,'–'),
        case when new.early_bird then 'yes' else 'no' end));
  return new;
exception when others then
  return new;
end $$;

revoke all on function public.sa_proposal_grant_find(text,text), public.sa_proposal_grant_apply(uuid,uuid),
  public.sa_proposal_grant_invite(uuid), public.sa_proposal_grant_on_accept(uuid) from public, anon, authenticated;
grant execute on function public.sa_proposal_grant_find(text,text), public.sa_proposal_grant_apply(uuid,uuid),
  public.sa_proposal_grant_invite(uuid), public.sa_proposal_grant_on_accept(uuid) to service_role;

create or replace function public.sa_clean_parties(p jsonb)
returns jsonb language sql immutable as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'counterparty_name', left(nullif(trim(coalesce(p->>'counterparty_name','')), ''), 120),
    'counterparty_emails', (select coalesce(jsonb_agg(e), '[]'::jsonb) from (
        select distinct lower(trim(x)) e from jsonb_array_elements_text(
          case jsonb_typeof(p->'counterparty_emails') when 'array' then p->'counterparty_emails'
               when 'string' then to_jsonb(regexp_split_to_array(p->>'counterparty_emails', '[,;\s]+')) else '[]'::jsonb end) x
        where lower(trim(x)) ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' limit 5) q),
    'share', case when p->>'share' in ('joint','consent') then p->>'share' end))
$$;

create or replace function public.sa_match_gbqs_client_emails(p_emails text[])
returns uuid language sql stable security definer set search_path to 'public' as $$
  with d as (select distinct lower(split_part(trim(e), '@', 2)) dom from unnest(coalesce(p_emails, '{}'::text[])) e where trim(e) like '%@%')
  select c.id from clients c, d
   where d.dom <> '' and not exists (select 1 from sa_free_mail_domains f where f.domain = d.dom)
     and coalesce(c.suspended_at is null, true)
     and (lower(split_part(coalesce(c.email, ''), '@', 2)) = d.dom
          or lower(split_part(coalesce(c.email_admin, ''), '@', 2)) = d.dom
          or exists (select 1 from client_users cu join auth.users au on au.id = cu.user_id
                      where cu.client_id = c.id and cu.status = 'active' and lower(split_part(au.email, '@', 2)) = d.dom))
   order by c.created_at limit 1
$$;

create or replace function public.sa_share_with_counterparty(p_job_id uuid, p_survey_id uuid, p_path text)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare j surveyor_jobs; s surveys; c surveyor_companies; v_client uuid; v_own uuid; v_kind text; v_vid uuid; ph record; v_id uuid; v_ref text; v_emails text[];
begin
  select * into j from surveyor_jobs where id = p_job_id;
  select * into s from surveys where id = p_survey_id;
  if j.id is null or s.id is null or s.surveyor_job_id is distinct from j.id then return jsonb_build_object('ok', false, 'message', 'not an own job'); end if;
  if coalesce(j.parties->>'share', '') not in ('joint','consent') then return jsonb_build_object('ok', true, 'shared', false, 'reason', 'no consent'); end if;
  select array_agg(x) into v_emails from jsonb_array_elements_text(coalesce(j.parties->'counterparty_emails', '[]'::jsonb)) x;
  v_client := sa_match_gbqs_client_emails(v_emails);
  if v_client is null then return jsonb_build_object('ok', true, 'shared', false, 'reason', 'counterparty is not a GlobalBQS client'); end if;
  v_own := sa_match_gbqs_client(j.surveyor_client_id);
  if v_own = v_client then return jsonb_build_object('ok', true, 'shared', false, 'reason', 'same as client'); end if;
  v_kind := case when j.survey_type like 'on_hire%' then 'on_hire' when j.survey_type like 'off_hire%' then 'off_hire'
                 when j.survey_type = 'bunker_quantity_survey' then 'stocktake' end;
  if v_kind is null then return jsonb_build_object('ok', true, 'shared', false, 'reason', 'survey type not shown as external report'); end if;
  v_vid := coalesce(j.vessel_id, (select id from vessels where imo_number = j.imo_number limit 1));
  if v_vid is null then return jsonb_build_object('ok', true, 'shared', false, 'reason', 'vessel unknown'); end if;
  select * into c from surveyor_companies where id = j.company_id;
  v_ref := coalesce(s.report_number, j.reference);
  select p.lsfo_total, p.hsfo_total, p.lsmgo_total, p.mdo_total into ph
    from survey_phases p where p.survey_id = s.id and p.phase_type in ('single','on_hire','off_hire')
   order by case when p.phase_type = v_kind then 0 else 1 end limit 1;
  select id into v_id from external_surveys where surveyor_job_id = j.id and client_id = v_client;
  if v_id is null then
    insert into external_surveys(client_id, vessel_id, survey_at, port, haven_id, survey_kind, surveyor_company, surveyor_name,
                                 report_reference, lsfo, hsfo, lsmgo, mdo, report_file_path, report_file_name, report_uploaded_at,
                                 source, created_by, notes, surveyor_job_id)
    values (v_client, v_vid, coalesce((s.date_of_survey + coalesce(s.time_of_survey, '12:00'::time))::timestamptz, s.issued_at, now()),
            coalesce((select naam from havens where id = j.haven_id), j.port_text), j.haven_id, v_kind, c.name,
            (select coalesce(nullif(u.full_name, ''), u.email) from surveyor_company_users u where u.user_id = j.assigned_user_id),
            v_ref, greatest(coalesce(ph.lsfo_total, 0), 0), greatest(coalesce(ph.hsfo_total, 0), 0), greatest(coalesce(ph.lsmgo_total, 0), 0), greatest(coalesce(ph.mdo_total, 0), 0),
            p_path, v_ref || '.pdf', now(), 'surveyor', j.created_by,
            'Shared by ' || c.name || ' (' || case j.parties->>'share' when 'joint' then 'joint survey' else 'with consent of the principal' end || ') via GlobalBQS surveyor access', j.id)
    returning id into v_id;
  else
    update external_surveys set report_file_path = p_path, report_uploaded_at = now(), report_reference = v_ref, updated_at = now() where id = v_id;
  end if;
  return jsonb_build_object('ok', true, 'shared', true, 'client_id', v_client, 'external_survey_id', v_id);
end $$;

create or replace function public.sa_portal_job_set_parties(p_job_id uuid, p jsonb)
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare j surveyor_jobs; v jsonb := sa_clean_parties(p); r jsonb;
begin
  select * into j from surveyor_jobs where id = p_job_id and company_id = sa_my_company_id();
  if j.id is null then return jsonb_build_object('ok', false, 'message', 'Job not found.'); end if;
  if not sa_can_manage_location(j.location_id) then return jsonb_build_object('ok', false, 'message', 'Only the office or the location manager can change this.'); end if;
  if j.status in ('cancelled','merged') then return jsonb_build_object('ok', false, 'message', 'This job can no longer be changed.'); end if;
  if v->>'share' is not null and jsonb_array_length(coalesce(v->'counterparty_emails','[]'::jsonb)) = 0 then
    return jsonb_build_object('ok', false, 'message', 'Enter the e-mail address of the counterparty to share the report.');
  end if;
  update surveyor_jobs set parties = v, updated_at = now() where id = j.id;
  if j.status = 'issued' and j.survey_id is not null and v->>'share' is not null then
    r := sa_share_with_counterparty(j.id, j.survey_id,
           (select rl.report_path from sa_report_links rl where rl.survey_id = j.survey_id order by rl.created_at desc limit 1));
  end if;
  return jsonb_build_object('ok', true, 'parties', v, 'shared_now', r,
    'message', case when v->>'share' is null then 'Saved. The report is not shared with the counterparty.'
                    else 'Saved. If the counterparty uses GlobalBQS, the report appears in their portal when it is issued.' end);
end $$;

