    || '      ''shared_with_counterparty'', exists (select 1 from external_surveys es where es.surveyor_job_id = j.id and es.notes like ''Shared by %''),' || chr(10)
    || '      ''created_at'', j.created_at, ''updated_at'', j.updated_at,');
  execute f;
