-- sa_vat_2_vies (10-11-2026): btw-advies verwerkt.
--  * btw-nummer van EU-surveyorbedrijven wordt bij de EU (VIES) gecontroleerd; verlegging alleen bij een geldig nummer,
--    anders 21% (ook als VIES niet bereikbaar is en het nummer nog nooit geldig was).
--  * factuurteksten: verlegd volgens art. 196, buiten de EU volgens art. 44 Btw-richtlijn 2006/112/EG.
--  * systeeminstelling client_invoice_vat_note: vermelding nultarief zeeschepen op klantfacturen (leeg = uit).

alter table public.surveyor_companies
  add column if not exists vat_check_status text check (vat_check_status in ('pending','valid','invalid','unavailable')),
  add column if not exists vat_checked_number text,
  add column if not exists vat_checked_at timestamptz,
  add column if not exists vat_check_name text,
  add column if not exists vat_check_request bigint,
  add column if not exists vat_check_requested_at timestamptz,
  add column if not exists vat_check_message text;

create or replace function public.sa_eu_vies_code(p_country text)
returns text language sql immutable as $$
  select case
    when upper(trim(coalesce(p_country,''))) in ('NL','NETHERLANDS','THE NETHERLANDS','NEDERLAND') then 'NL'
    when upper(trim(coalesce(p_country,''))) in ('GR','EL') then 'EL'
    when upper(trim(coalesce(p_country,''))) = any(array['AT','BE','BG','HR','CY','CZ','DK','EE','FI','FR','DE','HU','IE','IT','LV','LT','LU','MT','PL','PT','RO','SK','SI','ES','SE'])
      then upper(trim(p_country))
  end
$$;

create or replace function public.sa_vies_number(p_country text, p_vat text)
returns text language sql immutable as $$
  with x as (select upper(regexp_replace(coalesce(p_vat,''), '[^A-Za-z0-9]', '', 'g')) v, sa_eu_vies_code(p_country) cc)
  select case
    when x.v = '' or x.cc is null then null
    when left(x.v, 2) ~ '^[A-Z]{2}$' then case when left(x.v,2) = 'GR' then 'EL' else left(x.v,2) end || substr(x.v, 3)
    else x.cc || x.v end
  from x
$$;

create or replace function public.sa_vies_request(p_company uuid)
returns void language plpgsql security definer set search_path to 'public' as $$
declare c surveyor_companies; v_num text; v_id bigint;
begin
  select * into c from surveyor_companies where id = p_company;
  if c.id is null then return; end if;
  v_num := sa_vies_number(c.country, c.vat_number);
  if v_num is null then
    update surveyor_companies set vat_check_status = null, vat_checked_number = null, vat_check_name = null,
           vat_check_request = null, vat_check_message = null where id = c.id;
    return;
  end if;
  v_id := net.http_get('https://ec.europa.eu/taxation_customs/vies/rest-api/ms/' || left(v_num, 2) || '/vat/' || substr(v_num, 3),
                       headers := '{"Accept":"application/json"}'::jsonb, timeout_milliseconds := 20000);
  update surveyor_companies set
    vat_check_request = v_id, vat_check_requested_at = now(),
    vat_check_status = case when vat_check_status = 'valid' and vat_checked_number = v_num then 'valid' else 'pending' end,
    vat_checked_number = v_num
   where id = c.id;
end $$;

create or replace function public.sa_vies_collect(p_company uuid default null)
returns integer language plpgsql security definer set search_path to 'public' as $$
declare r record; resp record; b jsonb; n int := 0; v_err text;
begin
  for r in select id, vat_check_request, vat_check_requested_at, vat_check_status, vat_checked_number
             from surveyor_companies
            where vat_check_request is not null and (p_company is null or id = p_company)
  loop
    select status_code, content, error_msg, timed_out into resp from net._http_response where id = r.vat_check_request;
    if not found then
      if r.vat_check_requested_at < now() - interval '3 minutes' then
        update surveyor_companies set vat_check_request = null,
               vat_check_status = case when vat_check_status = 'valid' then 'valid' else 'unavailable' end,
               vat_check_message = 'No answer from VIES' where id = r.id;
        n := n + 1;
      end if;
      continue;
    end if;
    b := null;
    begin b := resp.content::jsonb; exception when others then b := null; end;
    v_err := coalesce(b->>'userError', resp.error_msg, 'HTTP ' || coalesce(resp.status_code::text, '?'));
    if resp.status_code = 200 and coalesce((b->>'isValid')::boolean, false) then
      update surveyor_companies set vat_check_status = 'valid', vat_checked_at = now(), vat_check_request = null,
             vat_check_name = nullif(nullif(trim(b->>'name'), '---'), ''), vat_check_message = null where id = r.id;
    elsif resp.status_code in (200, 400) and v_err in ('INVALID', 'INVALID_INPUT') then
      update surveyor_companies set vat_check_status = 'invalid', vat_checked_at = now(), vat_check_request = null,
             vat_check_name = null, vat_check_message = 'Not a valid VAT number according to VIES' where id = r.id;
    else
      update surveyor_companies set vat_check_request = null,
             vat_check_status = case when vat_check_status = 'valid' then 'valid' else 'unavailable' end,
             vat_check_message = left('VIES not available: ' || v_err, 200) where id = r.id;
    end if;
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.sa_vies_cron()
returns jsonb language plpgsql security definer set search_path to 'public' as $$
declare n_collect int; n_retry int := 0; r record;
begin
  n_collect := sa_vies_collect(null);
  for r in select id from surveyor_companies
            where vat_check_request is null and sa_vies_number(country, vat_number) is not null
              and (vat_check_status is null
                   or vat_checked_number is distinct from sa_vies_number(country, vat_number)
                   or (vat_check_status in ('unavailable','pending') and coalesce(vat_check_requested_at, 'epoch') < now() - interval '15 minutes')
                   or (vat_check_status = 'valid' and coalesce(vat_checked_at, 'epoch') < now() - interval '90 days'))
            limit 20
  loop
    perform sa_vies_request(r.id); n_retry := n_retry + 1;
  end loop;
  return jsonb_build_object('collected', n_collect, 'requested', n_retry);
end $$;

create or replace function public.sa_vies_trigger()
returns trigger language plpgsql security definer set search_path to 'public' as $$
begin
  if tg_op = 'INSERT' or new.vat_number is distinct from old.vat_number or new.country is distinct from old.country then
    begin perform sa_vies_request(new.id); exception when others then raise warning 'sa_vies_request: %', sqlerrm; end;
  end if;
  return null;
end $$;
drop trigger if exists trg_sa_vies on public.surveyor_companies;
create trigger trg_sa_vies after insert or update of vat_number, country on public.surveyor_companies
  for each row execute function public.sa_vies_trigger();

create or replace function public.sa_vat_for_company(p_company uuid)
returns jsonb language plpgsql volatile security definer set search_path to 'public' as $function$
declare c surveyor_companies; v_cc text; v_num text; v_nl numeric := coalesce(nullif((select value from system_settings where key = 'sa_vat_rate_nl'), '')::numeric, 21);
begin
  if coalesce((select value from system_settings where key = 'sa_vat_mode'), 'off') <> 'by_country' then
    return jsonb_build_object('rate', 0, 'note', null, 'mode', 'off');
  end if;
  begin perform sa_vies_collect(p_company); exception when others then null; end;
  select * into c from surveyor_companies where id = p_company;
  v_cc := sa_eu_vies_code(c.country);
  if v_cc = 'NL' then
    return jsonb_build_object('rate', v_nl, 'note', null, 'mode', 'nl');
  elsif v_cc is not null then
    v_num := sa_vies_number(c.country, c.vat_number);
    if v_num is null then
      return jsonb_build_object('rate', v_nl, 'note', null, 'mode', 'eu_no_vat_number');
    end if;
    if c.vat_check_status = 'valid' and c.vat_checked_number = v_num then
      return jsonb_build_object('rate', 0, 'mode', 'eu_reverse', 'vat_check', 'valid',
        'note', 'VAT reverse-charged pursuant to Article 196 of Directive 2006/112/EC. Customer VAT number: ' || v_num || '.');
    end if;
    return jsonb_build_object('rate', v_nl, 'note', null, 'mode', 'eu_vat_not_verified', 'vat_check', coalesce(c.vat_check_status, 'pending'));
  elsif upper(trim(coalesce(c.country, ''))) = '' then
    return jsonb_build_object('rate', v_nl, 'note', null, 'mode', 'unknown_country');
  end if;
  return jsonb_build_object('rate', 0, 'mode', 'non_eu',
    'note', 'Services outside the scope of EU VAT pursuant to Article 44 of Directive 2006/112/EC.');
end $function$;

do $do$
declare f text; a text := '''vat_number'', c.vat_number,';
begin
  f := pg_get_functiondef('public.sa_portal_company()'::regprocedure);
  if (length(f) - length(replace(f, a, ''))) / length(a) <> 1 then raise exception 'sa_portal_company anker'; end if;
  f := replace(f, a, a || ' ''vat_check_status'', c.vat_check_status, ''vat_check_name'', c.vat_check_name,');
  execute f;
end $do$;

revoke all on function public.sa_vies_request(uuid), public.sa_vies_collect(uuid), public.sa_vies_cron() from public, anon, authenticated;
grant execute on function public.sa_vies_request(uuid), public.sa_vies_collect(uuid), public.sa_vies_cron() to service_role;

insert into system_settings(key, value) values ('client_invoice_vat_note', '')
  on conflict (key) do nothing;

select cron.schedule('gbqs-sa-vies', '*/5 * * * *', $$select public.sa_vies_cron()$$);

-- portaal: VIES-antwoord voor het eigen bedrijf direct ophalen (na opslaan btw-nummer)
create or replace function public.sa_portal_vat_check()
returns jsonb language plpgsql volatile security definer set search_path to 'public' as $$
declare v_company uuid := sa_my_company_id(); c surveyor_companies;
begin
  if v_company is null then return jsonb_build_object('ok', false); end if;
  begin perform sa_vies_collect(v_company); exception when others then null; end;
  select * into c from surveyor_companies where id = v_company;
  return jsonb_build_object('ok', true, 'vat_check_status', c.vat_check_status, 'vat_check_name', c.vat_check_name);
end $$;
