grant execute on function public.sa_portal_vat_check() to authenticated, service_role;

-- Delen met een GBQS-klant (tegenpartij of eigen klant) mislukte als het schip nog niet in de schepenlijst stond ('vessel unknown').
-- Nu: bij een geldig IMO-nummer wordt het schip aangemaakt (naam + IMO), zodat het externe rapport aan het schip kan hangen.
create or replace function public.sa_ensure_vessel(p_imo text, p_name text)
returns uuid language plpgsql security definer set search_path to 'public' as $$
declare v_id uuid; v_imo text := regexp_replace(coalesce(p_imo, ''), '\D', '', 'g');
begin
  if v_imo = '' or not sa_imo_valid(v_imo) then return null; end if;
  select id into v_id from vessels where imo_number = v_imo limit 1;
  if v_id is null then
    insert into vessels(vessel_name, imo_number)
    values (coalesce(nullif(trim(p_name), ''), 'IMO ' || v_imo), v_imo)
    returning id into v_id;
  end if;
  return v_id;
end $$;
revoke all on function public.sa_ensure_vessel(text, text) from public, anon, authenticated;
grant execute on function public.sa_ensure_vessel(text, text) to service_role;

do $do$
declare f text; a text := 'v_vid := coalesce(j.vessel_id, (select id from vessels where imo_number = j.imo_number limit 1));';
  b text := 'v_vid := coalesce(j.vessel_id, (select id from vessels where imo_number = j.imo_number limit 1), sa_ensure_vessel(j.imo_number, j.vessel_name));';
  fn text;
begin
  foreach fn in array array['public.sa_share_with_counterparty(uuid,uuid,text)', 'public.sa_share_as_external(uuid,uuid,text)'] loop
    f := pg_get_functiondef(fn::regprocedure);
    if (length(f) - length(replace(f, a, ''))) / length(a) <> 1 then raise exception '% anker', fn; end if;
    execute replace(f, a, b);
  end loop;
end $do$;
